    # Prefer a mapping interface, otherwise fall back to an iterable
    items_source = None
    if hasattr(self, 'items'):
        # Use the items attribute if it provides (key, value) tuples
        items_source = getattr(self, 'items')
    elif hasattr(self, 'keys') and hasattr(self, 'values'):
        # Mapping object
        items_source = [(k, v) for k, v in zip(self.keys(), self.values())]
    else:
