    if not isinstance(srid_map, dict):
        raise TypeError(f"srid_map must be a dict, got {type(srid_map).__name__}")

    # Ensure field names are strings
    for f in fields:
        if not isinstance(f, str):
            raise TypeError(f"Each field name must be a string, got {type(f).__name__}")

    # Build the class namespace with placeholder attributes for each field
    cls_namespace = {field: None for field in fields}

    # Custom __init__ that accepts coordinates and optional field keyword args
    def __init__(self, x, y, *extra_coords, **kwargs):
        from shapely.geometry import Point as BasePoint  # imported lazily to avoid hard dependency
        # Initialize the base Point with coordinates
        BasePoint.__init__(self, x, y, *extra_coords)
        # Assign any provided field values
        for key, value in kwargs.items():
