def xargs(
    cmd: tuple[str, ...],
    varargs: Sequence[str],
    *,
    color: bool = False,
    target_concurrency: int = 1,
    _max_length: int = _get_platform_max_length(),
    **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """

    # Basic validation
    if not isinstance(cmd, tuple) or not cmd:
        raise TypeError("cmd must be a non-empty tuple of strings")
    if not isinstance(varargs, Sequence):
        raise TypeError("varargs must be a sequence of strings")

    # Compute base command length (without arguments)
    base_len = sum(len(arg) for arg in cmd) + (len(cmd) - 1)

    # Helper to build batches respecting max length
    batches: list[tuple[str, ...]] = []
    current: list[str] = []
    current_len = base_len

    for arg in varargs:
        arg_len = len(arg)
        # decide space addition
        added_len = arg_len + (1 if current else 0)
        if current_len + added_len <= _max_length:
            current.append(arg)
            current_len += added_len
        else:
            if not current:
                # single argument too long, still emit it
                batches.append((arg,))
                current_len = base_len
            else:
                batches.append(tuple(current))
                current = [arg]
                current_len = base_len + arg_len
    if current:
        batches.append(tuple(current))

    # Function to run a single batch
    def _run_batch(batch_args: tuple[str, ...]) -> tuple[int, bytes]:
        try:
            result = subprocess.run(
                list(cmd) + list(batch_args),
                capture_output=True,
                check=False,
                **kwargs,
            )
            return result.returncode, result.stdout
        except Exception as exc:
            return 1, f"Execution failed: {exc}\n".encode()

    # Run batches, possibly concurrently
    all_outputs: list[bytes] = []
    return_code = 0

    if target_concurrency > 1 and len(batches) > 1:
        with concurrent.futures.ThreadPoolExecutor(max_workers=target_concurrency) as executor:
            futures = [executor.submit(_run_batch, b) for b in batches]
            for fut in concurrent.futures.as_completed(futures):
                rc, out = fut.result()
                all_outputs.append(out)
                if rc != 0 and return_code == 0:
                    return_code = rc
    else:
        for b in batches:
            rc, out = _run_batch(b)
            all_outputs.append(out)
            if rc != 0 and return_code == 0:
                return_code = rc

    # If color is requested and platform supports PTY, optionally wrap stdout with escape sequences
    if color:
        try:
            import tty
            import pty

            for i in range(len(all_outputs)):
                all_outputs[i] = b"\x1b[32m" + all_outputs[i] + b"\x1b[0m"
        except Exception:
            pass  # ignore if pty/tty not available

    return return_code, b"".join(all_outputs)<|return|>

def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    import subprocess
    import concurrent.futures

    # Validate inputs
    if not isinstance(cmd, tuple) or len(cmd) == 0:
        raise ValueError("`cmd` must be a non-empty tuple of strings.")
    if not isinstance(varargs, Sequence):
        raise TypeError("`varargs` must be a sequence of strings.")
    if not isinstance(target_concurrency, int) or target_concurrency <= 0:
        target_concurrency = 1

    varargs = tuple(varargs)

    # Partition varargs to respect _max_length
    partitions: list[tuple[str, ...]] = []
    if not varargs:
        partitions = [()]
    else:
        if _max_length <= 0:
            partitions = [varargs]
        else:
            current = []
            current_len = 0
            for arg in varargs:
                arg_len = len(arg.encode("utf-8")) + 1  # +1 for separator
                if current_len + arg_len > _max_length and current:
                    partitions.append(tuple(current))
                    current = [arg]
                    current_len = arg_len
                else:
                    current.append(arg)
                    current_len += arg_len
            if current:
                partitions.append(tuple(current))

    exit_code = 0
    stdout_chunks: list[bytes] = []

    # Helper to run a single command
    def _run(part: tuple[str, ...]) -> subprocess.CompletedProcess[bytes]:
        try:
            return subprocess.run(cmd + part, capture_output=True, **kwargs)
        except Exception as exc:
            # If anything goes wrong just raise so the caller can handle it
            raise RuntimeError(f"Subprocess failed: {exc}") from exc

    if target_concurrency == 1:
        # Sequential execution
        for part in partitions:
            result = _run(part)
            if result.returncode != 0 and exit_code == 0:
                exit_code = result.returncode
            stdout_chunks.append(result.stdout)
    else:
        # Parallel execution
        with concurrent.futures.ThreadPoolExecutor(max_workers=target_concurrency) as executor:
            futures = [_run(part) for part in partitions]
            for future in concurrent.futures.as_completed(futures):
                try:
                    result = future.result()
                except RuntimeError:
                    return 1, b""
                if result.returncode != 0 and exit_code == 0:
                    exit_code = result.returncode
                stdout_chunks.append(result.stdout)

    return exit_code, b"".join(stdout_chunks)<|return|>

