def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    # Validate the input type
    try:
        from collections.abc import Sequence
    except Exception:
        raise RuntimeError('Required typing collections.abc.Sequence not available')

    if not isinstance(seq, Sequence):
        raise TypeError('seq must be a Sequence[str]')

    # Create a deterministic seed from the content of the sequence
    try:
        concatenated = ''.join(seq)
    except Exception as e:
        raise TypeError('All elements of seq must be strings') from e

    # Use SHA256 to generate a reproducible numeric seed
    try:
        import hashlib, random
    except Exception as e:
        raise RuntimeError('Required modules hashlib or random not available') from e

    seed_bytes = hashlib.sha256(concatenated.encode('utf-8')).digest()
    seed = int.from_bytes(seed_bytes, 'big', signed=False)

    rng = random.Random(seed)
    shuffled = list(seq)
    rng.shuffle(shuffled)
    return shuffled<|return|>

