    """Deterministically shuffle"""
    try:
        items = list(seq)
    except Exception as e:
        raise TypeError("seq must be an iterable of strings") from e

    for i, item in enumerate(items):
        if not isinstance(item, str):
            raise TypeError(f"All elements must be str; element {i} is {type(item)}")

    import hashlib, random
    seed_bytes = hashlib.sha256(''.join(items).encode('utf-8')).digest()
    seed_int = int.from_bytes(seed_bytes, 'big')
    rnd = random.Random(seed_int)
    rnd.shuffle(items)
    return items<|return|>

