                        cached_val = cache[k] if k in cache else _MISSING
                    except Exception:
                        cached_val = _MISSING
                if cached_val is not _MISSING:
                    return cached_val
            except Exception:
                # On any error, do not return cached value
                cached_val = _MISSING
            finally:
