def _reset_logging(cls):
    """
    Reset
    """
    try:
        # Obtain the logger for this class (if any)
        logger = logging.getLogger(cls.__name__)
        # Remove and close all existing handlers
        for handler in list(logger.handlers):
            logger.removeHandler(handler)
            try:
                handler.flush()
            except Exception:
                pass
            try:
                handler.close()
            except Exception:
                pass
        # Reset the logger's level to the default (INFO)
        logger.setLevel(logging.INFO)
        # Attach a new default StreamHandler with a simple formatter
        stream_handler = logging.StreamHandler()
        formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
        stream_handler.setFormatter(formatter)
        logger.addHandler(stream_handler)
    except Exception as exc:
        raise RuntimeError(f"Failed to reset logging for class {cls.__name__}") from exc<|return|>

