def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    # Validate inputs
    if not all(isinstance(ol, (list, tuple)) for ol in orderings):
        raise TypeError("All orderings must be lists or tuples")
    if not orderings:
        return []

    # Check suffix consistency between orders that share elements
    # Keep list of orderings as tuples for indexing
    ord_tuples = [tuple(o) for o in orderings]
    for i in range(len(ord_tuples)):
        for j in range(i + 1, len(ord_tuples)):
            o1 = ord_tuples[i]
            o2 = ord_tuples[j]
            shared = set(o1).intersection(o2)
            if not shared:
                continue
            for elem in shared:
                idx1 = o1.index(elem)
                idx2 = o2.index(elem)
                if o1[idx1:] != o2[idx2:]:
                    raise ValueError(f"Suffix conflict for element {elem!r} between "
                                     f"ordering {i} and {j}")

    # Build directed graph of precedence relations
    graph = {}
    all_nodes = []
    seen = set()
    for order in orderings:
        for elem in order:
            if elem not in graph:
                graph[elem] = set()
            if elem not in seen:
                seen.add(elem)
                all_nodes.append(elem)
    for order in orderings:
        for a, b in zip(order, order[1:]):
            graph[a].add(b)

    # Compute indegrees
    indegree = {node: 0 for node in graph}
    for node, succs in graph.items():
        for s in succs:
            indegree[s] += 1

    # Kahn's algorithm with deterministic ordering
    from collections import deque
    zero = deque([n for n in all_nodes if indegree[n] == 0])
    result = []

    while zero:
        n = zero.popleft()
        result.append(n)
        for s in graph[n]:
            indegree[s] -= 1
            if indegree[s] == 0:
                zero.append(s)

    if len(result) != len(graph):
        raise ValueError("Cycle detected or missing elements in merge")

    return result
<|return|>

