def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Validate that classes is iterable
    try:
        iter(classes)
    except TypeError:
        raise TypeError('classes must be an iterable of class objects')
    # Convert to list and validate each element
    classes = list(classes)
    for c in classes:
        if not isinstance(c, type):
            raise TypeError(f'Expected class object, got {type(c).__name__}')
    # Build minimal list
    minimal = []
    for c in classes:
        # Skip duplicate entries
        if c in minimal:
            continue
        skip = False
        to_remove = []
        for m in minimal:
            if issubclass(m, c):
                # c is ancestor of m → cannot add
                skip = True
                break
            if issubclass(c, m):
                # c is subclass of m → m redundant
                to_remove.append(m)
        if not skip:
            for m in to_remove:
                minimal.remove(m)
            minimal.append(c)
    return minimal<|return|>

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not isinstance(classes, list):
        raise TypeError(f"Expected a list of classes, got {type(classes)}")
    result = []
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"Expected a class, got {type(cls)}")
        # Skip if cls is a subclass of an already chosen base
        redundant = False
        for existing in result:
            try:
                if issubclass(cls, existing):
                    redundant = True
                    break
            except TypeError:
                continue
        if redundant:
            continue
        # Remove any existing bases that are subclasses of cls
        result = [e for e in result if not (e is not cls and issubclass(e, cls))]
        result.append(cls)
    return result<|return|>

