    if not isinstance(all, bool):
        raise ValueError("Parameter 'all' must be a bool.")
    try:
        # Collect names of all non-callable, non-private attributes
        attr_names = []
        for name in dir(self):
            if name.startswith('_'):
                continue
            try:
                value = getattr(self, name)
            except Exception:
                # Skip attributes that raise on access
                continue
            if callable(value):
                continue
            attr_names.append(name)
        return attr_names
    except Exception as e:
        # Re-raise any unexpected errors for debugging
        raise e<|return|>

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for item in sequence:
        if isinstance(item, (list, tuple)):
            # Recursively expand nested sequences
            _normalizeargs(item, output)
        else:
            output.append(item)
