def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # If sequence is not iterable (e.g. a single interface), treat it as a singleton list
    try:
        iterator = iter(sequence)
    except TypeError:
        return output + [sequence]

    for item in iterator:
        # Expand tuples/lists recursively
        if isinstance(item, (tuple, list)):
            output.extend(_normalizeargs(item, []))
        else:
            # Preserve individual interfaces or implements specs as-is
            output.append(item)

    return output<|return|>

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.
    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if sequence is None:
        return output

    # Ensure sequence is iterable (but not string)
    if isinstance(sequence, (str, bytes)):
        # Treat a single string/interface as a best‑guess Declaration
        output.append(Declaration(sequence))
        return output

    for arg in sequence:
        # Expand tuples/lists/more iterables recursively
        if isinstance(arg, (list, tuple)) and not isinstance(arg, (str, bytes)):
            _normalizeargs(arg, output)
        else:
            # Directly accepted as a Declaration
            if isinstance(arg, Declaration):
                output.append(arg)
            else:
                # Try to wrap unknown items into a Declaration; if that fails,
                # just store the item itself (user awareness is required)
                try:
                    output.append(Declaration(arg))
                except Exception:
                    output.append(arg)
    return output<|return|>

