def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    # ensure we have a list to accumulate results
    if output is None:
        output = []

    # Treat a single non-iterable (but not a string) as a sequence
    try:
        iter(sequence)
    except TypeError:
        sequence = [sequence]

    # Prevent treating strings or bytes as iterables of characters
    if isinstance(sequence, (str, bytes)):
        sequence = [sequence]

    for arg in sequence:
        # If it's a tuple, fall through to recursive normalisation
        if isinstance(arg, tuple):
            output.extend(_normalizeargs(arg))
        # If it's an instance of Declaration, keep as-is
        elif isinstance(arg, Declaration):
            output.append(arg)
        # If it's a string (interface name) or other primitive, treat as individual interface
        elif isinstance(arg, (str, bytes)):
            output.append(arg)
        else:
            # For other objects (e.g., implements specs or custom objects), we just store them
            output.append(arg)

    return output<|return|>

def _c_optimizations_available():
    """Return the C optimization module, if available, otherwise
    a false value.

    If the optimizations are required but not available, this
    raises the ImportError.

    This does not say whether they should be used or not.
    """
    try:
        import importlib
        return importlib.import_module("c_optimizations")
    except Exception as exc:
        # If a global flag indicates that C optimizations are required,
        # raise ImportError, otherwise silently return False.
        if globals().get("_C_OPTIMIZATIONS_REQUIRED", False):
            raise ImportError("C optimizations required but not available") from exc
        return False<|return|>

def _should_attempt_c_optimizations():
    """Return a true value if we should attempt to use the C optimizations.

    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    import os, sys

    # If PURE_PYTHON is explicitly set to true, don't use C optimizations
    pure_python_env = os.environ.get("PURE_PYTHON")
    if pure_python_env is not None:
        pure_python_env = pure_python_env.strip().lower()
        if pure_python_env in ("1", "true", "yes"):
            return False

    # C extensions might not be compatible with PyPy or could be slower
    # It's safer to avoid them when running on PyPy
    try:
        if getattr(sys, "implementation", None):
            if sys.implementation.name.lower() == "pypy":
                return False
    except Exception:
        # If we can't determine the implementation, fall back to using C
        pass

    # Default to using C optimizations when conditions above are not met
    return True<|return|>

def _c_optimizations_ignored():
    """The opposite of `_c_optimizations_required`."""
    return not _c_optimizations_required()
<|return|>

def _c_optimizations_ignored():
    """The opposite of `_c_optimizations_required`."""
    try:
        required = _c_optimizations_required()
    except NameError as e:
        raise RuntimeError("The required function `_c_optimizations_required` is not defined") from e
    except Exception as e:
        raise RuntimeError("Error while calling `_c_optimizations_required`") from e

    if not isinstance(required, bool):
        raise TypeError("_c_optimizations_required() must return a boolean value")

    return not required<|return|>

def _c_optimizations_ignored():
    """The opposite of `_c_optimizations_required`."""
    try:
        # Return the negation of the required optimizations flag.
        return not _c_optimizations_required()
    except NameError:
        # If the required function is not available, assume no optimizations are required.
        return False<|return|>

