def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value* or with *make_bins()* (depending on the initialization).
    """
    try:
        # Reset current context
        self.context = {}

        # Reinitialize bins
        if hasattr(self, "initial_value") and self.initial_value is not None:
            # Initialize copy of initial_value for each existing bin
            if hasattr(self, "bins"):
                if isinstance(self.bins, list):
                    self.bins = [self.initial_value for _ in self.bins]
                else:
                    try:
                        # If bins has a constructor that accepts a value (e.g., numpy array)
                        self.bins = type(self.bins)(self.initial_value)
                    except Exception:
                        # fallback to list of values
                        self.bins = [self.initial_value]
            else:
                self.bins = [self.initial_value]
        else:
            # Fall back to calling make_bins() if available
            if hasattr(self, "make_bins") and callable(self.make_bins):
                self.bins = self.make_bins()
            else:
                raise AttributeError(
                    "Histogram has neither an 'initial_value' nor a callable 'make_bins()' to reinitialize bins."
                )
    except Exception as exc:
        raise RuntimeError(f"Failed to reset histogram: {exc}") from exc<|return|>

