def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
        Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    try:
        out_lines = []
        if header is not None:
            out_lines.append(str(header))
        for point in self:
            items = []
            # handle objects with explicit attributes
            if hasattr(point, "coords") and hasattr(point, "value"):
                items.extend(point.coords)
                items.extend(point.value)
            elif hasattr(point, "x"):
                items.append(point.x)
                if hasattr(point, "y"):
                    items.append(point.y)
                if hasattr(point, "value"):
                    items.append(point.value)
            # handle tuples/lists
            elif isinstance(point, (tuple, list)):
                if len(point) == 2 and isinstance(point[0], (tuple, list)):
                    items.extend(point[0])
                    if isinstance(point[1], (tuple, list)):
                        items.extend(point[1])
                    else:
                        items.append(point[1])
                else:
                    items.extend(point)
            else:
                items.append(point)
            out_lines.append(separator.join(map(str, items)))
        return "\n".join(out_lines)
    except Exception as exc:
        raise ValueError(f"Failed to convert graph to CSV: {exc}") from exc<|return|>

def to_csv(self, separator=",", header=None):
        """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
              Iterables are converted to tables.

        Convert graph's points to CSV.

        *separator* delimits values, the default is comma.

        *header*, if not ``None``, is the first string of the output
        (new line is added automatically).

        Since a graph can be multidimensional,
        for each point first its coordinate is converted to string
        (separated by *separator*), then each part of its value.

        To convert :class:`Graph` to CSV inside a Lena sequence,
        use :class:`lena.output.ToCSV`.
        """
        # Determine the iterable that yields the points of the graph.
        try:
            points_iter = getattr(self, "points", None)
            if points_iter is None:
                points_iter = self
        except Exception as exc:
            raise ValueError(f"Failed to access graph points: {exc}") from exc

        lines = []

        # Add header if provided.
        if header is not None:
            lines.append(str(header))

        for point in points_iter:
            # Attempt to unpack if the point is a tuple/list.
            try:
                coord, value = point
            except Exception:
                # Try more guesswork for dict-like points.
                coord = None
                value = None
                if isinstance(point, dict):
                    coord = point.get("coord") or point.get("coordinates")
                    value = point.get("value") or point.get("values") or point.get("data")
                # If still missing, fall back to the whole point.
                if coord is None:
                    coord = point
                if value is None:
                    value = None

            row_parts = []

            # Handle coordinate part.
            if isinstance(coord, (list, tuple)):
                for c in coord:
                    row_parts.append(str(c))
            else:
                # Single coordinate value
                row_parts.append(str(coord))

            # Handle value part.
            if isinstance(value, (list, tuple)):
                for v in value:
                    row_parts.append(str(v))
            else:
                # May be None: skip adding None to preserve format.
                if value is not None:
                    row_parts.append(str(value))

            lines.append(separator.join(row_parts))

        # Join all lines with newlines. Do not add a trailing newline.
        csv_output = "\n".join(lines)
        return csv_output<|return|>

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # validate input
    if not isinstance(coord_name, str):
        raise TypeError(f"coord_name must be a string, got {type(coord_name).__name__}")

    # try to locate the internal mapping that holds error indices
    mapping = None
    # common attribute names that might hold the mapping
    for attr in ("_error_indices", "error_indices", "errors", "err_indices"):
        if hasattr(self, attr):
            potential = getattr(self, attr)
            if isinstance(potential, dict):
                mapping = potential
                break

    # if no dictionary was found, return an empty list
    if mapping is None:
        return []

    # fetch indices for the requested coordinate
    try:
        indices = mapping.get(coord_name, [])
    except Exception as exc:
        raise ValueError(f"Failed to retrieve error indices for '{coord_name}': {exc}") from exc

    # Ensure a list is returned
    if isinstance(indices, (list, tuple, set)):
        return list(indices)

    # If indices is an iterator or another iterable type
    try:
        return list(indices)
    except TypeError:
        # If indices is a single value or non-iterable, wrap it in a list
        return [indices] if indices is not None else []
<|return|>

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Normalize coordinate name to lowercase
    coord = coord_name.lower()
    # Defensive check: only allow recognised coordinate names
    allowed = {"x", "y", "z", "width", "height", "depth"}
    if coord not in allowed:
        raise ValueError(f"Invalid coordinate name: {coord_name!r}")
    # Construct the attribute name that should hold the error indices
    # Convention: _{coord}_err_indices (e.g. _x_err_indices)
    attr_name = f"_{coord}_err_indices"
    if not hasattr(self, attr_name):
        # Provide a clear error if the attribute is missing
        raise AttributeError(
            f"The object does not have error‐indices for coordinate '{coord_name}'. "
            f"Expected attribute {attr_name!r}."
        )
    indices = getattr(self, attr_name)
    # Ensure the returned value is iterable and contains integers
    try:
        it = iter(indices)
    except TypeError:
        raise TypeError(
            f"Attribute {attr_name!r} should be iterable (list/tuple/numpy array)."
        )
    if not all(isinstance(i, int) for i in indices):
        raise ValueError(
            f"All entries in {attr_name!r} must be integers but got {indices!r}."
        )
    return indices<|return|>

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate.

    Parameters:
        coord_name (str): The name of the coordinate.

    Returns:
        list[int]: A list of error indices that refer to the given coordinate.
    """
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")

    # Attempt to use a cached mapping if available
    cache = getattr(self, "_err_indices_cache", None)
    if isinstance(cache, dict):
        return cache.get(coord_name, [])

    # Gather indices from the errors collection
    indices = []
    errors = getattr(self, "errors", None)

    if errors is None:
        return []

    # If errors is a dictionary mapping coordinates to index lists
    if isinstance(errors, dict):
        return list(errors.get(coord_name, []))

    # Assume errors is an iterable of error objects
    for idx, err in enumerate(errors):
        coord = None
        if hasattr(err, "coord"):
            coord = getattr(err, "coord")
        elif hasattr(err, "name"):
            coord = getattr(err, "name")
        elif hasattr(err, "coord_name"):
            coord = getattr(err, "coord_name")
        elif isinstance(err, dict):
            coord = err.get("coordinate")
        if coord == coord_name:
            indices.append(idx)

    # Cache the result for future calls
    setattr(self, "_err_indices_cache", {coord_name: indices})
    return indices<|return|>

def _update_context(self, context):
        """Update *context* with the properties of this graph.

        *context.error* is appended with indices of errors.
        Example subcontext for a graph with fields "E,t,error_E_low":
        {"error": {"x_low": {"index": 2}}}.
        Note that error names are called "x", "y" and "z"
        (this corresponds to first three coordinates,
        if they are present), which allows to simplify plotting.
        Existing values are not removed
        from *context.value* and its subcontexts.

        Called on "destruction" of the graph (for example,
        in :class:`.ToCSV`). By destruction we mean conversion
        to another structure (like text) in the flow.
        The graph object is not really destroyed in this process.
        """
        # Ensure the context has an 'error' attribute
        try:
            error_ctx = context.error
        except AttributeError:
            # If context has no 'error', try setting an empty dict
            context.error = {}
            error_ctx = context.error

        # error_ctx should be a mapping; if not, set to an empty dict
        if error_ctx is None or not isinstance(error_ctx, dict):
            context.error = {}
            error_ctx = context.error

        # Ensure we have a sub-dict under the key 'error'
        if 'error' not in error_ctx or not isinstance(error_ctx['error'], dict):
            error_ctx['error'] = {}
        subctx = error_ctx['error']

        # Helper to translate field names to the compact "x","y","z" style
        coord_map = {'x': 'x', 'y': 'y', 'z': 'z'}

        # Iterate through attributes of the graph looking for error annotations
        for attr_name in dir(self):
            # Skip private and built‑in attributes
            if attr_name.startswith('_'):
                continue
            # Look for attributes that look like error markers
            if not (attr_name.endswith('_low') or attr_name.endswith('_high')):
                continue
            # Check that the attribute actually exists on the instance
            try:
                value = getattr(self, attr_name)
            except Exception:
                continue
            # Only bother with error indices that are integers
            if not isinstance(value, int):
                continue
            # Determine base name after removing the 'error_' prefix
            if attr_name.startswith('error_'):
                base = attr_name[6:]    # strip leading 'error_'
            else:
                base = attr_name
            # Normalize the coordinate name to use x/y/z if appropriate
            name_part, _sep, suffix = base.partition('_')
            coord = coord_map.get(name_part, name_part)
            key = f"{coord}_{suffix}"
            # Store the index under the appropriate key
            if key not in subctx or not isinstance(subctx[key], dict):
                subctx[key] = {}
            subctx[key]['index'] = value
        # Nothing is returned; the context is modified in place.<|return|>

def _update_context(self, context):
        """Update *context* with the properties of this graph.

        *context.error* is appended with indices of errors.
        Example subcontext for a graph with fields "E,t,error_E_low":
        {"error": {"x_low": {"index": 2}}}.
        Note that error names are called "x", "y" and "z"
        (this corresponds to first three coordinates,
        if they are present), which allows to simplify plotting.
        Existing values are not removed
        from *context.value* and its subcontexts.

        Called on "destruction" of the graph (for example,
        in :class:`.ToCSV`). By destruction we mean conversion
        to another structure (like text) in the flow.
        The graph object is not really destroyed in this process.
        """
        # Ensure the context has the required attributes
        if not hasattr(context, "error") or context.error is None:
            context.error = {}
        elif not isinstance(context.error, dict):
            # If error exists but is not a dict, try to cast
            try:
                context.error = dict(context.error)
            except Exception:
                context.error = {}

        # Collect non-error attribute names in the order they appear
        field_names = [k for k in self.__dict__
                       if not k.startswith("_") and not callable(getattr(self, k))
                       and not k.startswith("error_")]

        # Map field index to coordinate name ('x', 'y', 'z')
        coord_map = {}
        for idx, name in enumerate(field_names[:3]):  # only first three
            if idx == 0:
                coord_map[name] = "x"
            elif idx == 1:
                coord_map[name] = "y"
            elif idx == 2:
                coord_map[name] = "z"

        # Iterate over all attributes to find error fields
        for attr, value in self.__dict__.items():
            if not attr.startswith("error_"):
                continue  # skip non-error fields
            # Parse the error attribute: expected form error_<var>_<level>
            parts = attr.split("_")
            if len(parts) < 3:
                # If no explicit level, skip this attribute
                continue
            _, var_name, level = parts[0], parts[1], "_".join(parts[2:])
            var_name = parts[1]
            level = "_".join(parts[2:])  # in case level contains underscores

            # Find index of the variable in the field list
            if var_name in coord_map:
                coord_name = coord_map[var_name]
                idx = field_names.index(var_name)
            else:
                # Fall back to searching the field list generically
                try:
                    idx = field_names.index(var_name)
                    # If more than three, use the ordinal coordinate name
                    coord_name = {"0": "x", "1": "y", "2": "z"}.get(str(idx % 3), f"c{idx}")
                except ValueError:
                    # Variable not found; skip this error
                    continue

            # Build the key for this error in the context
            error_key = f"{coord_name}_{level}"

            # Append the index to the appropriate subcontext
            if error_key not in context.error:
                context.error[error_key] = {"index": idx}
            else:
                # If already exists, we can either overwrite or maintain list
