def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Basic validation
    try:
        len_edges = len(edges)
        len_bins = len(bins)
    except Exception as exc:
        raise TypeError("bins and edges must be indexable containers") from exc

    if len_edges != len_bins + 1:
        raise ValueError(
            "Number of edges must be one more than number of bins "
            f"(got {len_bins} bins and {len_edges} edges)."
        )

    total = 0.0
    for idx, b in enumerate(bins):
        try:
            width = float(edges[idx + 1]) - float(edges[idx])
        except Exception as exc:
            raise TypeError(
                f"Edge values must be numeric (edges[{idx}] and edges[{idx+1}])"
            ) from exc

        if width <= 0:
            raise ValueError(
                f"Edge width must be positive for bin index {idx} "
                f"(got width {width})."
            )

        try:
            val = float(b)
        except Exception as exc:
            raise TypeError(f"Bin values must be numeric (bins[{idx}] = {b})") from exc

        total += val * width

    return total<|return|>

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    if bins is None or edges is None:
        raise TypeError("Both bins and edges must be provided.")
    try:
        nbins = len(bins)
        nedges = len(edges)
    except TypeError:
        raise TypeError("bins and edges must be sized sequences.")
    if nedges != nbins + 1:
        raise ValueError(f"Edges length must be one greater than bins length (got {nbins} bins and {nedges} edges).")
    # calculate bin widths
    widths = []
    for i in range(nedges - 1):
        try:
            w = edges[i+1] - edges[i]
        except TypeError as exc:
            raise TypeError(f"Edges must support subtraction: {exc}") from exc
        widths.append(w)
    # compute the integral as sum of bin values times width
    total = 0.0
    for b, w in zip(bins, widths):
        try:
            total += float(b) * float(w)
        except Exception as exc:
            raise ValueError(f"Bins and widths must be numeric: {exc}") from exc
    return total<|return|>

