def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both d1 and d2 must be dictionaries")

    # If recursion depth exhausted, no recursive difference
    if level == 0:
        return {}

    diff = {}
    for key, val1 in d1.items():
        if key not in d2:
            diff[key] = val1
        else:
            val2 = d2[key]
            # If both are dicts and recursion is still allowed
            if isinstance(val1, dict) and isinstance(val2, dict) and (level > 1 or level == -1):
                subdiff = difference(val1, val2, level - 1 if level > 0 else -1)
                if subdiff:
                    diff[key] = subdiff
            else:
                # Include differing values
                if val1 != val2:
                    diff[key] = val1
    return diff<|return|>

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Basic sanity checks
    if not hasattr(self, 'edges') or not hasattr(self, 'data'):
        raise AttributeError("Histogram object must have 'edges' and 'data' attributes.")
    if not isinstance(coord, (list, tuple)):
        raise TypeError("coord must be a list or tuple of coordinates.")
    if len(coord) != len(self.edges):
        raise ValueError(f"Coordinate dimensionality ({len(coord)}) does not match histogram dimensionality ({len(self.edges)}).")

    try:
        float(weight)
    except Exception:
        raise TypeError("weight must be numeric.")

    indices = []
    for d, val in enumerate(coord):
        bounds = self.edges[d]
        if not isinstance(bounds, list):
            bounds = list(bounds)
        # If coordinate is outside the overall bounds, ignore
        if val < bounds[0] or val >= bounds[-1]:
            return
        # Find the bin index for this dimension
        bin_index = None
        for i in range(len(bounds) - 1):
            if bounds[i] <= val < bounds[i + 1]:
                bin_index = i
                break
        if bin_index is None:
            return  # safety fall‑back, though shouldn't happen
        indices.append(bin_index)

    # Convert list of indices to a tuple for array indexing
    indices = tuple(indices)
    try:
        self.data[indices] += weight
    except Exception as exc:
        raise RuntimeError(f"Failed to increment histogram bin {indices}: {exc}") from exc<|return|>

