    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    import numpy as np

    # Validate coordinate dimensionality
    try:
        coord = np.asarray(coord, dtype=float)
    except Exception as exc:
        raise ValueError(f"Coordinate must be array-like. Error: {exc}") from exc

    if coord.shape[0] != len(self.edges):
        raise ValueError(
            f"Coordinate dimension {coord.shape[0]} does not match histogram "
            f"dimension {len(self.edges)}"
