    # Compute bin indices for each dimension
    indices = []
    for d, (c, edges) in enumerate(zip(coord, self.edges)):
        # Searchsorted finds insertion index to maintain sorted order.
        idx = np.searchsorted(edges, c, side="right") - 1
        if idx < 0 or idx >= len(edges) - 1:
            # coordinate falls outside the edges, ignore this point
            return
        indices.append(idx)

    # Convert list to tuple for indexing
    idx_tuple = tuple(indices)

    try:
        self.data[idx_tuple] += weight
    except Exception as exc:
        raise RuntimeError(
            f"Failed to update histogram data at indices {idx_tuple}: {exc}"
        ) from exc
