    # Ensure histogram data exists
    if not hasattr(self, "data"):
        raise AttributeError("Histogram object has no 'data' attribute")
    # Try to obtain shape; fall back to list-based shape detection
    try:
        shape = self.data.shape
    except Exception:
        # Infer list shape
        shape = [len(self.data)]
        tmp = self.data
        while isinstance(tmp, list) and tmp:
            shape.append(len(tmp))
            tmp = tmp[0]
        shape = tuple(shape)

    # Dimensionality check
    if len(idx) != len(shape):
        # wrong dimensionality – silently ignore
        return

    # Bounds check
    for i, c in enumerate(idx):
        if c < 0 or c >= shape[i]:
            return

    # Increment the bin
    try:
        self.data[idx] += weight
    except Exception:
        # If data is not a NumPy array, try nested indexing
        elem = self.data
        for d in idx[:-1]:
            elem = elem[d]
        try:
