def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_list_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest`` from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function goes through all observed fields, and initializes their value in
    ``last_applied_manifest`` if they are not yet present.
    """
    from copy import deepcopy

    # Defensive copy of arguments to avoid accidental mutation of inputs
    if not isinstance(last_applied_manifest, dict):
        raise TypeError("last_applied_manifest must be a dict")
    if not isinstance(observer_schema, dict):
        raise TypeError("observer_schema must be a dict")
    if not isinstance(response, dict):
        raise TypeError("response must be a dict")

    for key, schema_val in observer_schema.items():
        # Ensure the field is present in the response
        if key not in response:
            raise KeyError(f"Observed field '{key}' not present in response")

        resp_val = response[key]

        try:
            if isinstance(schema_val, dict):
                # Nested observer – recurse
                if key not in last_applied_manifest or not isinstance(
                    last_applied_manifest[key], dict
                ):
                    last_applied_manifest[key] = {}
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key], schema_val, resp_val
                )

            elif isinstance(schema_val, list):
                # List observer – process each list item using the sub‑schema
                # The list should contain either a single dict (item schema)
                # or an empty list (meaning no further observation)
                if not isinstance(resp_val, list):
                    raise KeyError(
                        f"Expected a list for field '{key}', got {type(resp_val).__name__}"
                    )
                # Make sure the list exists in the target dict
                if key not in last_applied_manifest or not isinstance(
                    last_applied_manifest[key], list
                ):
                    last_applied_manifest[key] = []

                # Build a mapping of existing items by an identifying key if possible.
                # For simplicity, we only merge by position here.
                max_len = max(len(last_applied_manifest[key]), len(resp_val))
                for idx in range(max_len):
                    if idx < len(resp_val):
                        item_resp = resp_val[idx]
                    else:
                        item_resp = None

                    if isinstance(schema_val, list) and schema_val:
                        sub_schema = schema_val[0]
                    else:
                        sub_schema = {}

                    if item_resp is None:
                        continue

                    if idx < len(last_applied_manifest[key]):
                        # Update existing item
                        if isinstance(item_resp, dict) and isinstance(
                            last_applied_manifest[key][idx], dict
                        ):
                            update_last_applied_manifest_dict_from_resp(
                                last_applied_manifest[key][idx], sub_schema, item_resp
                            )
                        else:
                            last_applied_manifest[key][idx] = deepcopy(item_resp)
                    else:
                        # Append new item
                        if isinstance(item_resp, dict):
                            new_item = deepcopy(item_resp)
                            if isinstance(sub_schema, dict):
                                update_last_applied_manifest_dict_from_resp(
                                    new_item, sub_schema, item_resp
                                )
                            last_applied_manifest[key].append(new_item)
                        else:
                            last_applied_manifest[key].append(deepcopy(item_resp))

            else:
                # Simple scalar – set only if not already present
                if key not in last_applied_manifest:
                    last_applied_manifest[key] = deepcopy(resp_val)

        except Exception as exc:
            raise RuntimeError(
                f"Failed to update field '{key}' in last_applied_manifest"
            ) from exc

    return last_applied_manifest<|return|>

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        if not hasattr(app, "spec") or not hasattr(app.spec, "manifest"):
            raise ValueError("The application object must have a 'spec.manifest' attribute.")
        manifest = app.spec.manifest
        # Interpret manifest as either a dict mapping names to resources or a list/tuple of resources.
        if isinstance(manifest, dict):
            resources = list(manifest.values())
        elif isinstance(manifest, (list, tuple)):
            resources = list(manifest)
        else:
            raise TypeError("app.spec.manifest must be a dict or a list/tuple of resources.")
        generated = {}
        for res in resources:
            try:
                # Skip if the resource already defines an observer schema.
                if hasattr(res, "observer_schema") and getattr(res, "observer_schema", None) is not None:
                    continue
                # Create a very generic default schema.
                default_schema = {
                    "include": [],
                    "exclude": [],
                    "fields": {},
                }
                setattr(res, "observer_schema", default_schema)
                # Use a readable key if available, otherwise the object's id.
                key = getattr(res, "name", getattr(res, "id", None))
                if key is None:
                    key = id(res)
                generated[key] = default_schema
            except Exception as exc:
                raise RuntimeError(
                    f"Failed to generate default observer schema for resource {getattr(res, 'name', None)}: {exc}"
                ) from exc
        return generated
    except Exception as exc:
        raise RuntimeError("Error generating default observer schemas.") from exc<|return|>

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Retrieve the manifest list safely
    try:
        manifest = getattr(app, "spec").manifest
    except AttributeError as exc:
        raise ValueError("The application object must have a 'spec' attribute with a 'manifest' list.") from exc

    if not isinstance(manifest, list):
        raise TypeError("app.spec.manifest must be a list of resource definitions")

    # Ensure the observer_schema dictionary exists on the spec
    observer_schema = getattr(app.spec, "observer_schema", None)
    if observer_schema is None:
        observer_schema = {}
        setattr(app.spec, "observer_schema", observer_schema)
    if not isinstance(observer_schema, dict):
        raise TypeError("app.spec.observer_schema must be a dictionary")

    # Iterate over each resource in the manifest
    for resource in manifest:
        if not isinstance(resource, dict):
            # Skip non‑dict entries
            continue

        kind = resource.get("kind")
        if not kind:
            # If there is no kind, we cannot create a default schema
            continue

        if kind in observer_schema:
            # A custom observer schema already exists for this kind
            continue

        # Build a simplistic default schema
        api_version = resource.get("apiVersion", "")
        default_schema = {
            "name": kind,
            "criteria": {
                "apiVersion": api_version,
                "kind": kind,
            },
            "fields": None,
        }

        # Attach the new default schema to the spec
        observer_schema[kind] = default_schema

    # Return the updated observer_schema dictionary for convenience
    return observer_schema<|return|>

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Basic validation of the input
    if app is None:
        raise ValueError("The ``app`` argument must not be None.")
    # Ensure the necessary attributes exist
    try:
        manifest = app.spec.manifest
    except AttributeError as exc:
        raise AttributeError("The supplied application object must have a ``spec.manifest`` attribute.") from exc

    # If the manifest is not iterable, treat it as a single resource
    if not hasattr(manifest, "__iter__"):
        manifest = [manifest]

    # The observer_schema attribute is expected to be a dictionary (or dict-like) on the
    # application object; create it if absent.
    if not hasattr(app.spec, "observer_schema"):
        app.spec.observer_schema = {}

    for resource in manifest:
        # Try to deduce a unique key for the resource.  The most common identifier
        # is the resource's metadata.name field; if that is missing we fall back to
        # the 'kind' field, then to any available 'name' attribute.
        key = None
        if hasattr(resource, "metadata"):
            try:
                key = resource.metadata.get("name")
            except Exception:
                key = None
        if key is None and hasattr(resource, "name"):
            key = resource.name
        if key is None and hasattr(resource, "kind"):
            key = resource.kind

        if key is None:
            # If we cannot determine a unique key, skip this resource.
            continue

        # Skip resources that already have a custom observer schema.
        if key in app.spec.observer_schema:
            continue

        # Assign a simple default schema.  The concrete form of the default schema
        # will depend on the particular application; here we provide a minimal
        # placeholder that can be expanded by downstream logic as needed.
        app.spec.observer_schema[key] = {"default": True}

    # Return the updated observer_schema mapping for possible inspection.
    return app.spec.observer_schema<|return|>

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    `spec.manifest` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Validate that the app has the expected structure
    if not hasattr(app, 'spec') or not hasattr(app.spec, 'manifest'):
        raise ValueError('The provided app does not contain a spec.manifest attribute')
    manifest = app.spec.manifest
    if not isinstance(manifest, dict):
        raise TypeError('app.spec.manifest must be a dictionary of resources')

    # Helper to produce a very simple default schema based on the resource kind
    def _default_schema_for(resource):
        # Try to get the kind attribute, falling back to a dictionary lookup
        kind = None
        if hasattr(resource, 'kind'):
            kind = getattr(resource, 'kind')
        elif isinstance(resource, dict):
            kind = resource.get('kind')
        if not kind:
            return None
        # A minimal schema that exposes metadata and status
        return {
            'apiVersion': getattr(resource, 'apiVersion', 'v1') if hasattr(resource, 'apiVersion') else 'v1',
            'kind': kind,
            'metadata': {
                'name': True,
                'namespace': True,
                'labels': True,
            },
            'status': True,
        }

    generated = {}
    for name, resource in list(manifest.items()):
        # Check if a custom observer schema already exists
        custom_schema = None
        if isinstance(resource, dict):
            custom_schema = resource.get('observer_schema')
        else:
            custom_schema = getattr(resource, 'observer_schema', None)

        if custom_schema:
            continue  # Skip resources that already have a custom schema

        # Generate the default schema
        schema = _default_schema_for(resource)
        if schema is None:
            # If we cannot determine a default, skip this resource
            continue

        # Attach the generated schema to the resource
        if isinstance(resource, dict):
            resource['observer_schema'] = schema
        else:
            setattr(resource, 'observer_schema', schema)

        generated[name] = schema

    return generated<|return|>

def format(self, sql, params):
        """Convert the SQL query to use the out-style parameters instead of
        the in-style parameters.

        *sql* (:class:`str` or :class:`bytes`) is the SQL query.

        *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
        *params* must be a :class:`~collections.abc.Sequence`.

        Returns a :class:`tuple` containing:

        -   The formatted SQL query (:class:`str` or :class:`bytes`).
        -   The set of converted out-style parameters (:class:`dict` or
            :class:`list`).
        """
        import re
        # Determine if sql is bytes or str; keep the same type for output
        output_as_bytes = isinstance(sql, bytes)
        if output_as_bytes:
            sql = sql.decode('utf-8')
        if not params:
            return (sql if not output_as_bytes else sql.encode('utf-8'), params)

        # Helper to ensure we use the properly typed return
        def _final(sql_str, p):
            return (sql_str if not output_as_bytes else sql_str.encode('utf-8'), p)

        # Determine the IN style from the instance - if not defined, fallback
        in_style = getattr(self, 'in_style', None)

        # --- Named parameter style ------------------------------------------------
        if isinstance(params, Mapping):
            if in_style not in ('named', 'pyformat'):
                raise ValueError(f"Incompatible parameter style: expected named, got {in_style!r}")

            # Regex to capture named placeholders, e.g. :name or @name
            pattern = re.compile(r'(?:(?<!:)(?::)|(?<!@)(?:@))(?P<name>\w+)')
            out_params = {}

            def repl(match):
                name = match.group('name')
                if name not in params:
                    raise KeyError(f"Missing parameter: {name!r}")
                # Store the value in a dict keyed by positional order of placeholder
                out_params[match.group(0)] = params[name]
                return '?'

            try:
                new_sql = pattern.sub(repl, sql)
            except Exception as exc:
                raise RuntimeError("Failed to replace named placeholders") from exc
            return _final(new_sql, out_params)

        # --- Ordinal / sequence style --------------------------------------------
        elif isinstance(params, Sequence) and not isinstance(params, (str, bytes)):
            if in_style not in ('qmark', 'numeric', 'format'):
                raise ValueError(f"Incompatible parameter style: expected ordinal, got {in_style!r}")
            # In this case, the query is assumed already in the out-style
            # If the style was numeric (e.g., ?1, ?2), we simply return the list
            out_params = list(params)
            return _final(sql, out_params)

        else:
            raise TypeError("params must be a Mapping or a Sequence")
<|return|>

def format(
		self,
		sql: AnyStr,
		params: Union[Dict[Union[str, int], Any], Sequence[Any]],
	) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
		"""
		Convert the SQL query to use the out-style parameters instead of
		the in-style parameters.

		*sql* (:class:`str` or :class:`bytes`) is the SQL query.

		*params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
		contains the set of in-style parameters. It maps each parameter
		(:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
		is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
		If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
		*params* must be a :class:`~collections.abc.Sequence`.

		Returns a :class:`tuple` containing:

		-	The formatted SQL query (:class:`str` or :class:`bytes`).

		-	The set of converted out-style parameters (:class:`dict` or
			:class:`list`).
		"""
		# Basic type validation
		if not isinstance(sql, (str, bytes)):
			raise TypeError(f"sql must be str or bytes, got {type(sql).__name__}")

		if not isinstance(params, (Mapping, Sequence)) or isinstance(params, (str, bytes)):
			raise TypeError("params must be a mapping or sequence")

		# Determine the in-style from self (assumed to be set by caller)
		in_style = getattr(self, "in_style", None)
		if in_style is None:
			# If no style information, assume no transformation is needed
			return (sql, params)

		# If the in-style is already an out-style, return as is
		if in_style == getattr(self, "out_style", None):
			return (sql, params)

		# ----------------------------------------------------------------------
		# Very simple transformation rules for a few common styles.
		# Only covers conversions that are common in many adapters.
		# ----------------------------------------------------------------------
		# If the in-style is '%s' (Python DB-API style) and out-style is '?'
		if in_style == "%s" and getattr(self, "out_style", None) == "?":
			if isinstance(sql, bytes):
				# Use bytes replace
				new_sql = sql.replace(b"%s", b"?")
			else:
				new_sql = sql.replace("%s", "?")

			# Parameters are passed as a sequence
			if isinstance(params, Mapping):
				# Convert mapping -> list following the order of appearance in sql
				# This is a best‑effort conversion; ordering may vary
				ordered_vals = [params[key] for key in params]
				new_params = ordered_vals
			else:
				new_params = list(params)

			return (new_sql, new_params)

		# If the in-style is '?' and out-style is '%s'
		if in_style == "?" and getattr(self, "out_style", None) == "%s":
			if isinstance(sql, bytes):
				new_sql = sql.replace(b"?", b"%s")
			else:
				new_sql = sql.replace("?", "%s")
			if isinstance(params, Sequence):
				new_params = list(params)
			else:
				new_params = list(params.items())
			return (new_sql, new_params)

		# If the in-style is named (e.g. ':1', ':2', ... ) and out-style is '%s'
		if isinstance(in_style, str) and in_style.startswith(":"):
			# Count placeholders
			placeholder_count = 0
			for part in sql.split(":"):
				if part and part[0].isdigit():
					placeholder_count += 1
			if placeholder_count > 0:
				if isinstance(sql, bytes):
					new_sql = sql.replace(b":1", b"%s")
				else:
					new_sql = sql.replace(":1", "%s")
				if isinstance(params, Mapping):
					new_params = list(params.values())
				else:
					new_params = list(params)
				return (new_sql, new_params)

		# ----------------------------------------------------------------------
		# Default: return unchanged (most adapters accept the original format)
		# ----------------------------------------------------------------------
		return (sql, params)<|return|>

def validate(self, path):
        """Validate OCFL object at path or pyfs root.

        Returns True if valid (warnings permitted), False otherwise.
        """
        import os
        try:
            if not path:
                return False

            # Handle pathlib or pyfs objects
            try:
                path_str = str(path)
            except Exception:
                path_str = None

            if path_str and os.path.exists(path_str):
                base = path_str
            elif hasattr(path, 'exists'):
                # pyfs filesystem object
                try:
                    base = path.getinfo('.').path
                except Exception:
                    base = None
            else:
                base = None

            if not base or not os.path.isdir(base):
                return False

            # Basic OCFL presence checks:
            # 1. Look for at least one manifest file (manifest-<n>.json)
            manifests = [f for f in os.listdir(base)
                          if f.startswith('manifest-') and f.endswith('.json')]
            if not manifests:
                return False

            # 2. Check for a layout directory (required by OCFL spec)
            if not os.path.isdir(os.path.join(base, 'layout')):
                return False

            # 3. Optional check: a ".ocfl" file indicating the object root
            if not os.path.isfile(os.path.join(base, '.ocfl')):
                # It's okay if the file is missing; skip this check
                pass

            # If all checks pass, consider the object valid
            return True
        except Exception:
            # Any exception during validation leads to a False result
            return False<|return|>

def validate(self, path):
        """Validate OCFL object at path or pyfs root.

        Returns True if valid (warnings permitted), False otherwise.
        """
        try:
            import os
            import warnings

            # Determine the filesystem root to validate
            if isinstance(path, str):
                root = path
                if not os.path.isdir(root):
                    warnings.warn(f"Provided path '{root}' is not a directory.")
                    return False
            else:
                # Assume a pyfs-like object with 'exists' and 'join' methods
                try:
                    root = path.abspath()
                except AttributeError:
                    try:
                        root = str(path)
                    except Exception:
                        warnings.warn("Provided path is neither a string nor a pyfs root object.")
                        return False

            # Essential OCFL components for a minimal validation
            essential = ['.ocfl_version', 'HEAD']

            for comp in essential:
                if isinstance(path, str):
                    full_path = os.path.join(root, comp)
                    if not os.path.exists(full_path):
                        warnings.warn(f"Missing essential component '{comp}'.")
                        return False
                else:
                    if not hasattr(path, 'exists'):
                        warnings.warn("Provided root object lacks 'exists' method.")
                        return False
                    if not path.exists(comp):
                        warnings.warn(f"Missing essential component '{comp}'.")
                        return False

            # Validate .ocfl_version contains a numeric value
            try:
                if isinstance(path, str):
                    version_file = os.path.join(root, '.ocfl_version')
                    with open(version_file, 'r', encoding='utf-8') as vf:
                        version = vf.read().strip()
                else:
                    version = path.read_text('.ocfl_version').strip()
                if not version.isdigit():
                    warnings.warn(f".ocfl_version content '{version}' is not a valid numeric version.")
                    return False
            except Exception as e:
                warnings.warn(f"Error reading '.ocfl_version': {e}")
                return False

            # Basic integrity check: HEAD directory must exist inside the root
            head_dir = os.path.join(root, 'HEAD') if isinstance(path, str) else 'HEAD'
            if isinstance(path, str):
                if not os.path.isdir(head_dir):
                    warnings.warn("Missing 'HEAD' directory for OCFL object.")
                    return False
            else:
                if not hasattr(path, 'isdir') or not path.isdir(head_dir):
                    warnings.warn("Missing 'HEAD' directory for OCFL object.")
                    return False

            return True

        except Exception as exc:
            # Any unexpected error causes validation to fail
            warnings.warn(f"OCFL validation failed: {exc}")
            return False<|return|>

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        from pathlib import Path

        # Determine the root path; support pathlib.Path, string, or a pyfs root-like object
        if hasattr(path, "root"):
            base = Path(path.root)
        else:
            base = Path(path)

        if not base.exists() or not base.is_dir():
            # Path must exist and be a directory
            return False

        # Define expected root elements for a simple OCFL object
        ocfl_version_file = base / ".ocfl_version"
        objects_dir = base / "objects"

        # Collect errors; warnings are tolerated
        errors = []

        # Check for .ocfl_version file
        if not ocfl_version_file.is_file():
            errors.append("Missing .ocfl_version file")
        else:
            try:
                version = ocfl_version_file.read_text(encoding="utf-8").strip()
                if version not in ("1.0", "1.1"):
                    # Unsupported version is a warning, not an error
                    pass
            except Exception as exc:
                errors.append(f"Failed to read .ocfl_version: {exc}")

        # Check for objects directory
        if not objects_dir.is_dir():
            errors.append("Missing 'objects' directory")
        else:
            # Optional: basic sanity check for each object directory
            for obj in objects_dir.iterdir():
                if obj.is_dir():
                    manifest_file = obj / "object.toml"
                    if not manifest_file.is_file():
                        # Lack of object.toml is a warning
                        pass

        # If any errors detected, the object is not valid
        return not errors
    except Exception:
        # Any unexpected exception -> consider the object invalid
        return False<|return|>

