def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    try:
        if hasattr(self, "validator"):
            val = self.validator
            # Prefer a get_status method if available
            if hasattr(val, "get_status") and callable(val.get_status):
                status = val.get_status()
            else:
