    later versions than the version being described.
    """
    if not isinstance(inventory, (dict, list, tuple)):
        raise TypeError("inventory must be a mapping or sequence of items")

    from collections import defaultdict

    path_map = defaultdict(set)

    # Helper to add entry to map
    def _add(logical_path, content_file, item_version):
        if logical_path is None or content_file is None:
            return
