                item_vs = str(item_version)
                target_vs = str(version)
                if item_vs == target_vs or item_vs > target_vs:
                    path_map[logical_path].add(content_file)
        except Exception:
            pass

    if isinstance(inventory, dict):
        items = inventory.items()
        for logical_path, info in items:
            if isinstance(info, dict):
                content_file = info.get("content_file") or info.get("path")
                item_version = info.get("version")
                _add(logical_path, content_file, item_version)
            else:
                # Treat value as the content file
                _add(logical_path, info, None)
    else:
        # inventory is a sequence; expect each element to be a dict or a (path, info) tuple
        for element in inventory:
            if isinstance(element, (list, tuple)) and len(element) == 2:
                logical_path, info = element
                if isinstance(info, dict):
                    content_file = info.get("content_file") or info.get("path")
                    item_version = info.get("version")
                    _add(logical_path, content_file, item_version)
                else:
                    _add(logical_path, info, None)
            elif isinstance(element, dict):
                logical_path = element.get("logical_path") or element.get("path")
                content_file = element.get("content_file") or element.get("path")
                item_version = element.get("version")
                _add(logical_path, content_file, item_version)
