                            files_accum.update(files)
                        else:
                            files_accum.add(files)
                except Exception:
                    # Skip problematic version entries
                    continue
            if files_accum:
                result[log_path] = files_accum
    except Exception as e:
        # Wrap any unexpected runtime error
        raise RuntimeError("Failed to build logical path map") from e

    return result<|return|>

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        raise ValueError("inventory must not be None")
    if version is None:
        raise ValueError("version must not be None")

    path_map = {}
    try:
        for entry in inventory:
            # Retrieve version
            try:
                ent_version = getattr(entry, "version")
            except AttributeError:
                ent_version = entry.get("version") if isinstance(entry, dict) else None
            if ent_version is None:
                continue
            if ent_version > version:
                continue

            # Retrieve logical path
            try:
                logical_path = getattr(entry, "logical_path")
            except AttributeError:
                logical_path = entry.get("logical_path") if isinstance(entry, dict) else None
            if logical_path is None:
                continue

            # Retrieve content file
            try:
                content_file = getattr(entry, "content_file")
            except AttributeError:
                content_file = entry.get("content_file") if isinstance(entry, dict) else None
            if content_file is None:
                continue

            path_map.setdefault(logical_path, set()).add(content_file)
    except Exception as exc:
        raise RuntimeError("Failed to build logical path map") from exc

    return path_map<|return|>

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    target = str(version)
    result = {}
    for lp, ver_map in inventory.items():
        if not isinstance(ver_map, dict):
            continue
        files = set()
        for ver, entries in ver_map.items():
            try:
                ver_str = str(ver)
            except Exception:
                continue
            # include files from the requested version or any later version
            if ver_str >= target:
                if isinstance(entries, (list, tuple, set)):
                    files.update(entries)
                else:
                    files.add(entries)
        if files:
            result[lp] = files
    return result<|return|>

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Prepare the result dictionary
    path_map = {}

    # Quick sanity check on the input types
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary mapping versions to data")

    # Resolve the target version key
    # The inventory may use int, float, or string keys.
    # We support direct equality comparison; for numeric comparisons,
    # convert all keys to a common type if possible.
    target_key = None
    for key in inventory:
        try:
            # Attempt to compare as numbers if hashable with version
            if isinstance(key, (int, float)) and isinstance(version, (int, float)):
                if key == version:
                    target_key = key
                    break
            else:
                if key == version:
                    target_key = key
                    break
        except Exception:
            continue

    if target_key is None:
        # If no exact match, try to find equivalent string or numeric conversion
        try:
            target_key = int(version) if isinstance(version, str) else version
        except Exception:
            target_key = version

    # Collect all logical paths and content files for the target and later versions
    for key, data in inventory.items():
        # Determine if this key represents a later version or the target version
        try:
            is_later_or_equal = False
            if isinstance(key, (int, float)) and isinstance(target_key, (int, float)):
                is_later_or_equal = key >= target_key
            else:
                # Fallback: include only if key equals the target
                is_later_or_equal = key == target_key
        except Exception:
            is_later_or_equal = False

        if not is_later_or_equal:
            continue

        # Normalize the data structure for mapping extraction
        mapping = None
        if isinstance(data, dict):
            # Assume mapping of logical_path -> content_file
            mapping = data
        elif isinstance(data, list):
            # Assume list of dicts with 'logical_path' and 'content_file' keys
            mapping = {}
            for item in data:
                if isinstance(item, dict):
                    lp = item.get('logical_path')
                    cf = item.get('content_file')
                    if lp is not None and cf is not None:
                        mapping[lp] = cf
        elif isinstance(data, tuple):
            # Treat tuple as (logical_path, content_file) or list thereof
            if len(data) == 2:
                mapping = {data[0]: data[1]}
            else:
                mapping = {}
                for pair in data:
                    if isinstance(pair, (list, tuple)) and len(pair) == 2:
                        mapping[pair[0]] = pair[1]
        else:
            # Unsupported data type; skip
            continue

        if not mapping:
            continue

        # Populate the result mapping
        for logical_path, content_file in mapping.items():
            # Ensure logical_path is hashable
            try:
                hash(logical_path)
            except Exception:
                continue

            if logical_path not in path_map:
                path_map[logical_path] = set()
            path_map[logical_path].add(content_file)

    return path_map<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError(f"Expected fixity to be a dict, got {type(fixity).__name__}")

    # The fixity block must contain a 'files' key with a list of entries
    if 'files' not in fixity:
        raise ValueError("Missing 'files' key in fixity block")

    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError(f"'files' should be a list, got {type(files).__name__}")

    # Ensure each entry is a dict containing a 'path' (and optional 'checksum')
    seen_paths = set()
    for idx, entry in enumerate(files):
        if not isinstance(entry, dict):
            raise ValueError(f"Entry {idx} in 'files' must be a dict, got {type(entry).__name__}")

        if 'path' not in entry:
            raise ValueError(f"Missing 'path' in entry {idx} of 'files'")

        path = entry['path']
        if not isinstance(path, str):
            raise ValueError(f"'path' in entry {idx} must be a string, got {type(path).__name__}")

        # path should not be duplicated
        if path in seen_paths:
            raise ValueError(f"Duplicate path detected in fixity block: {path}")
        seen_paths.add(path)

        # Ensure the path exists in the manifest
        if path not in manifest_files:
            raise ValueError(f"Fixity entry refers to unknown file: {path}")

        # Optional: check that checksum key exists if required
        if 'checksum' in entry and not isinstance(entry['checksum'], str):
            raise ValueError(f"'checksum' in entry {idx} must be a string, got {type(entry['checksum']).__name__}")

    # All checks passed
    return True<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Validate top‑level type
    if not isinstance(fixity, dict):
        raise ValueError(f"fixity must be a dict, got {type(fixity).__name__}")

    # Normalise manifest to a set for O(1) lookups
    try:
        manifest_set = set(manifest_files or ())
    except Exception as exc:  # pragma: no cover
        raise ValueError("manifest_files must be an iterable of file identifiers") from exc

    # Iterate over all referenced files
    for file_id, data in fixity.items():
        # File identifier sanity
        if not isinstance(file_id, str):
            raise ValueError(f"File identifier in fixity block must be a string, got {type(file_id).__name__}")

        # Ensure the file is actually listed in the manifest
        if file_id not in manifest_set:
            raise ValueError(f"File '{file_id}' referenced in fixity block is not present in the manifest")

        # Validate the data structure for this file
        if isinstance(data, dict):
            # Commonly a dict containing a hash or checksum
            if "hash" not in data and "checksum" not in data:
                raise ValueError(
                    f"Fixity data for '{file_id}' is a dict but missing 'hash' or 'checksum' key"
                )
            if "hash" in data and not isinstance(data["hash"], str):
                raise ValueError(f"'hash' value for '{file_id}' must be a string")
            if "checksum" in data and not isinstance(data["checksum"], str):
                raise ValueError(f"'checksum' value for '{file_id}' must be a string")
        elif not isinstance(data, str):
            # A simple string (e.g. a hash) is accepted
            raise ValueError(
                f"Fixity data for '{file_id}' must be either a dict or a string, "
                f"got {type(data).__name__}"
            )
    return True<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic sanity checks for input types
    if not isinstance(fixity, (dict, list)):
        raise ValueError(f"Fixity must be a dict or list, got {type(fixity).__name__}")

    # Normalize manifest to a set for fast membership checks
    try:
        manifest_set = set(manifest_files)
    except TypeError:
        raise ValueError("manifest_files must be an iterable of file names")

    # Determine the list of file entries in the fixity block
    if isinstance(fixity, dict) and "files" in fixity:
        entries = fixity["files"]
    else:
        entries = fixity

    # entries should be a list or iterable of file descriptors
    if not isinstance(entries, (list, tuple)):
        raise ValueError("Fixity block must contain a list of file descriptors")

    # Validate each file descriptor
    for idx, entry in enumerate(entries, start=1):
        if not isinstance(entry, dict):
            raise ValueError(f"Entry {idx} in fixity block is not a dict")

        if "file" not in entry:
            raise ValueError(f"Entry {idx} is missing required 'file' key")

        file_name = entry["file"]
        if not isinstance(file_name, str):
            raise ValueError(f"The 'file' value in entry {idx} must be a string")

        if file_name not in manifest_set:
            raise ValueError(f"File '{file_name}' referenced in fixity block is not present in the manifest")

        # Optional: check that a checksum or similar exists
        if "checksum" not in entry:
            raise ValueError(f"Entry {idx} is missing required 'checksum' key")

    # If we reach this point, the fixity block passes basic validation
    return True<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Verify fixity is a list or a single dict
    if isinstance(fixity, dict):
        entries = [fixity]
    elif isinstance(fixity, list):
        entries = fixity
    else:
        raise TypeError("fixity must be a dict or a list of dicts")

    # Normalize manifest_files to a set for fast lookup
    if not isinstance(manifest_files, (set, list)):
        raise TypeError("manifest_files must be a set or a list")
    manifest_set = set(manifest_files)

    seen_files = set()
    for idx, entry in enumerate(entries):
        if not isinstance(entry, dict):
            raise ValueError(f"Fixity entry at index {idx} is not a dict")

        # Check required keys
        for key in ("file", "hash"):
            if key not in entry:
                raise ValueError(f"Fixity entry at index {idx} missing required key '{key}'")

        file_path = entry["file"]
        if file_path not in manifest_set:
            raise ValueError(f"Fixity references file '{file_path}' not present in the manifest")

        if file_path in seen_files:
            raise ValueError(f"Duplicate fixity entry for file '{file_path}'")
        seen_files.add(file_path)

    # Optional: ensure that every file in the manifest has a corresponding entry
    # (this is not strictly required but can be helpful)
    missing_for_manifest = manifest_set - seen_files
    if missing_for_manifest:
        raise ValueError(f"Manifest contains files not listed in fixity: {sorted(missing_for_manifest)}")

    # If no exceptions were raised, validation succeeded
    return True<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, list):
        raise TypeError(f"Expected fixity to be a list, got {type(fixity).__name__}")
    if not isinstance(manifest_files, (set, list, tuple)):
        raise TypeError(f"Expected manifest_files to be a set/list/tuple, got {type(manifest_files).__name__}")

    # Ensure we have a set of known file names
    known_files = set(manifest_files)

    seen_files = set()

    for idx, entry in enumerate(fixity):
        if not isinstance(entry, dict):
            raise ValueError(f"Fixity entry at index {idx} is not a dict (got {type(entry).__name__})")

        # Required keys
        for key in ("file", "hash"):
            if key not in entry:
                raise ValueError(f"Fixity entry at index {idx} missing required key '{key}'")

        file_name = entry["file"]
        if not isinstance(file_name, str):
            raise ValueError(f"File name in fixity entry at index {idx} must be a string (got {type(file_name).__name__})")

        if file_name not in known_files:
            raise ValueError(f"File '{file_name}' referenced in fixity block is not listed in the manifest")

        if file_name in seen_files:
            raise ValueError(f"Duplicate file reference '{file_name}' found in fixity block at index {idx}")

        seen_files.add(file_name)

        # Optional: validate hash is a string
        hash_val = entry["hash"]
        if not isinstance(hash_val, str):
            raise ValueError(f"Hash value in fixity entry at index {idx} must be a string (got {type(hash_val).__name__})")

    # All checks passed
    return True<|return|>

