def match_file_by_prefix(prefix, file_path):
    """
    Identify if a `file_path` belongs to a document package by a given `prefix`

    Retorna `True` para documentos pertencentes a um pacote.

    Parameters
    ----------
    prefix : str
        Filename prefix
    file_path : str
        File path
    Returns
    -------
    bool
        True - file belongs to the package
    """
    try:
        import os
        # Ensure inputs are string-like
        if not isinstance(prefix, str) or not isinstance(file_path, str):
            # If file_path is a pathlib.Path or similar, convert to string
            if isinstance(file_path, (bytes, bytearray)):
                file_path = file_path.decode()
            if isinstance(file_path, (object,)):
                try:
                    file_path = str(file_path)
                except Exception:
                    return False
            if not isinstance(prefix, str):
                try:
                    prefix = str(prefix)
                except Exception:
                    return False

        basename = os.path.basename(file_path)
        return basename.startswith(prefix)
    except Exception:
        # Any parsing or attribute errors result in False
        return False<|return|>

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    if not isinstance(folder, str):
        raise TypeError("folder must be a string path")
    if not os.path.isdir(folder):
        raise FileNotFoundError(f"Folder '{folder}' does not exist or is not a directory")

    package_data = {}
    try:
        # First, collect all basenames of XML files
        xml_basenames = set()
        for root, _, files in os.walk(folder):
            for f in files:
                basename, ext = os.path.splitext(f)
                if ext.lower() == ".xml":
                    xml_basenames.add(basename)

        # Now, group every file that shares those basenames
        for root, _, files in os.walk(folder):
            for f in files:
                basename, _ = os.path.splitext(f)
                if basename in xml_basenames:
                    full_path = os.path.join(root, f)
                    package_data.setdefault(basename, []).append(full_path)

        # Optionally, sort file lists for deterministic output
        for key in package_data:
            package_data[key].sort()
    except OSError as exc:
        raise RuntimeError(f"Error while scanning folder '{folder}': {exc}") from exc

    return package_data<|return|>

