    if not isinstance(basename, str) or not basename:
        raise ValueError("basename must be a non-empty string")
    if not isinstance(file_path, str) or not file_path:
        raise ValueError("file_path must be a non-empty string")

    # Resolve to an absolute path and verify existence
    abs_path = os.path.abspath(file_path)
    if not os.path.isfile(abs_path):
        raise FileNotFoundError(f"File not found: {abs_path}")

    # Ensure the asset registry exists
    if not hasattr(self, "assets") or self.assets is None:
        self.assets = {}

    # Avoid duplicate basenames
    if basename in self.assets:
        raise ValueError(f"Asset '{basename}' already exists.")

    # Store the mapping
    self.assets[basename] = abs_path
    return None<|return|>

def add_asset(self, basename, file_path):
    """Add an asset mapping basename to file_path.

    Parameters:
        basename (str): The asset name to use.
        file_path (str): Filesystem path of the asset.

    Raises:
        TypeError: If arguments are not strings.
        ValueError: If the asset with this basename already exists.
        RuntimeError: If the assignment fails for unexpected reasons.
    """
    if not isinstance(basename, str):
        raise TypeError("The 'basename' argument must be a string.")
    if not isinstance(file_path, str):
        raise TypeError("The 'file_path' argument must be a string.")
    # Ensure the assets collection exists
    if not hasattr(self, "assets") or not isinstance(self.assets, dict):
        self.assets = {}
    if basename in self.assets:
        raise ValueError(f"An asset with the basename '{basename}' already exists.")
    try:
        self.assets[basename] = file_path
    except Exception as exc:
        raise RuntimeError(f"Failed to add asset '{basename}': {exc}") from exc
    return None<|return|>

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    # Validate the input path
    if not isinstance(zip_path, str):
        raise TypeError("zip_path must be a string representing a file path")

    try:
        # Open the zip file for reading
        with zipfile.ZipFile(zip_path, 'r') as zf:
            grouped = {}
            for info in zf.infolist():
                # Skip directories
                if info.is_dir():
                    continue

                # Determine the XML basename
                try:
                    basename = os.path.basename(info.filename)
                except Exception:
                    continue  # If basename extraction fails, skip this entry

                # Read file data
                try:
                    data = zf.read(info)
                except Exception:
                    continue  # Skip unreadable files

                # Initialize group if not exists
                if basename not in grouped:
                    grouped[basename] = {}

                # Store the data with the full relative path as key
                grouped[basename][info.filename] = data

        return grouped

    except FileNotFoundError as e:
        raise FileNotFoundError(f"Zip file not found: {zip_path}") from e

    except zipfile.BadZipFile as e:
        raise RuntimeError(f"Bad zip file '{zip_path}': {e}") from e

    except Exception as e:
        raise RuntimeError(f"Error while exploring zip file '{zip_path}': {e}") from e<|return|>

