    Parameters
    ----------
    zip_path : str
        Zip file path

    Returns
    -------
    dict
        A dictionary where each key is the basename of an XML file (without extension)
        and each value is a list of dictionaries representing the files belonging
        to that package. Each file dictionary contains:
            - "path": the relative path inside the zip
            - "content": the raw bytes of the file

    Notes
    -----
    Non-XML files that do not share the basename of any XML file are ignored.
    If the zip file cannot be opened or read, an appropriate exception is raised.
    """
    import os
    import zipfile

    # Validate input
    if not isinstance(zip_path, (str, bytes)):
        raise TypeError(f"zip_path must be a string or bytes-like object, got {type(zip_path).__name__}")

    if not os.path.exists(zip_path):
        raise FileNotFoundError(f"Zip file '{zip_path}' does not exist")

    package_map = {}

    try:
        with zipfile.ZipFile(zip_path, "r") as zf:
            # First pass: collect basenames of all XML files
            xml_basenames = set()
            for info in zf.infolist():
                if info.is_dir():
                    continue
                try:
                    filename = info.filename
                except AttributeError:
                    continue
                if filename.lower().endswith(".xml"):
                    base = os.path.splitext(os.path.basename(filename))[0]
                    xml_basenames.add(base)

            # Second pass: group all files that share a base name
            for info in zf.infolist():
                if info.is_dir():
                    continue
                try:
                    filename = info.filename
                except AttributeError:
                    continue
                base = os.path.splitext(os.path.basename(filename))[0]
                if base in xml_basenames:
                    try:
                        content = zf.read(info)
                    except Exception as e:
                        # If a file cannot be read, skip it but log the issue
                        # Using a simple print here; replace with logging if required
                        print(f"Warning: could not read '{filename}' from zip: {e}")
                        continue
                    package_map.setdefault(base, []).append({
                        "path": filename,
                        "content": content
                    })
    except zipfile.BadZipFile as e:
        raise zipfile.BadZipFile(f"Unable to process zip file '{zip_path}': {e}") from e
    except Exception as e:
        # Catch-all for unexpected errors, re-raise with context
        raise RuntimeError(f"Error while exploring zip '{zip_path}': {e}") from e

    return package_map<|return|>

