def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.

    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    import re
    try:
        if not issue or not isinstance(issue, str):
            return (None, None)

        s = issue.strip()

        # Encontrar o número principal (pode ser intervalo)
        num_match = re.search(r'\b\d+(?:-\d+)?\b', s)
        if num_match:
            num_str = num_match.group(0)
            # Se não houver hifen, converte para int
            number = int(num_str) if '-' not in num_str else num_str
        else:
            number = None

        # Buscar termo de suplemento depois do número principal
        start = num_match.end() if num_match else 0
        remaining = s[start:]

        # Procurar padrões de suplemento (Suppl, Spe, Supp, Supl., etc.)
        suppl_match = re.search(
            r'\b(?:Suppl|Supl|Supp|Spe|s)[\.\s]*\b(?:(\d+)(?:\b|$))?',
            remaining,
            re.IGNORECASE
        )

        if suppl_match:
            if suppl_match.group(1):
                # Se houver número após o termo, usar esse número
                try:
                    suppl = int(suppl_match.group(1))
                except ValueError:
                    suppl = None
            else:
                # Se não há número, apenas indicar a presença do termo
                suppl = None
        else:
            suppl = None

        return (number, suppl)

    except Exception:
        # Em caso de erro inesperado, devolve None
        return (None, None)<|return|>

def pretty(self, indent=0, debug=False):
        """Return a pretty formatted representation of self."""
        prefix = '  ' * indent
        if debug:
            return prefix + repr(self)

        # Handle no attributes
        lines = [prefix + f"{self.__class__.__name__}("]
        attrs = []
        for key in sorted(self.__dict__):
            if key.startswith('_') or callable(self.__dict__[key]):
                continue
            value = self.__dict__[key]
            try:
                if hasattr(value, "pretty") and callable(value.pretty):
                    val_str = value.pretty(indent + 1, debug)
                else:
                    val_str = repr(value)
            except Exception:
                val_str = repr(value)
            attrs.append('  ' * (indent + 1) + f"{key}={val_str}")
        if attrs:
            lines.extend(attrs)
            lines[-1] = lines[-1] + ')'
        else:
            lines[-1] = lines[-1] + ')'

        # Include child elements if iterable
        if hasattr(self, "__iter__"):
            for child in self:
                if hasattr(child, "pretty") and callable(child.pretty):
                    lines.append(child.pretty(indent + 1, debug))
        return "\n".join(lines)<|return|>

