        ind = '    ' * depth
        if hasattr(o, 'tag'):
            tag = getattr(o, 'tag', o.__class__.__name__)
        else:
            tag = o.__class__.__name__
        # Gather attributes if present
        attrs = {}
        if hasattr(o, 'attrib') and isinstance(o.attrib, dict):
            attrs = o.attrib
        elif hasattr(o, 'attributes') and isinstance(o.attributes, dict):
            attrs = o.attributes
        elif hasattr(o, 'attribs') and isinstance(o.attribs, dict):
            attrs = o.attribs
        attr_str = ''
        if attrs:
            parts = [f'{k}="{v}"' for k, v in attrs.items()]
            attr_str = ' ' + ' '.join(parts)
        # Start building the line
        line = f'{ind}{tag}{attr_str}'
        if debug:
            line += f' ({o.__dict__})'
        # Process children
        children = []
        if hasattr(o, 'children') and isinstance(o.children, (list, tuple)):
            children = o.children
        elif hasattr(o, '__iter__'):
            try:
                children = list(o)
            except Exception:
                children = []
        if children:
            line += ':\n'
            for child in children:
                try:
                    line += _fmt(child, depth + 1) + '\n'
                except Exception:
                    line += f'{ind}    {repr(child)}\n'
        return line.rstrip()

    return _fmt(self, indent)<|return|>

