    Return a pretty formatted representation of self.
    """
    # Validate arguments
    if not isinstance(indent, int) or indent < 0:
        raise ValueError("indent must be a non‑negative integer")
    if not isinstance(debug, bool):
        raise ValueError("debug must be a boolean")

    # If debug mode requested, fall back to the object’s repr for maximum detail
    if debug:
        return repr(self)

    lines = []
    prefix = " " * (indent * 2)

    # Build the opening tag with class name and optional id/attributes
    tag_parts = [f"{prefix}<{self.__class__.__name__}"]
    if hasattr(self, "id") and getattr(self, "id", None):
        tag_parts.append(f" id='{self.id}'")
    if hasattr(self, "attributes") and isinstance(self.attributes, dict):
        for k, v in self.attributes.items():
            tag_parts.append(f" {k}='{v}'")
    tag_parts.append(">")

    lines.append("".join(tag_parts))

    # Recursively pretty‑print child elements if any
    try:
        for child in self:
            # Child must itself have a pretty method; if not, use its repr
            if hasattr(child, "pretty") and callable(child.pretty):
                lines.append(child.pretty(indent + 1, debug))
            else:
                lines.append(" " * ((indent + 1) * 2) + repr(child))
    except TypeError:
        # The object is not iterable; nothing to add
        pass

    # Closing tag
    lines.append(f"{prefix}</{self.__class__.__name__}>")

    return "\n".join(lines)<|return|>

