def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Helper functions that work with a generic expression tree
    def _get_op(expr):
        """Return the operation name of an expression if it exists."""
        return getattr(expr, "op", None)

    def _get_args(expr):
        """Return the operands of an expression if it exists."""
        return getattr(expr, "args", None)

    def _is_not(expr):
        return _get_op(expr) == "Not"

    def _match_descendant(parent, node):
        """Return the child of node that equals parent, if any."""
        for child in _get_args(node) or []:
            if child == parent:
                return child
        return None

    def _remove_subexpression(expr, sub):
        """Return expr without sub in its arguments (used for absorption)."""
        new_args = tuple(a for a in _get_args(expr) or [] if a != sub)
        if len(new_args) == 1:
            return new_args[0]
        return type(expr)(expr.op, *new_args)

    def _apply_absorption(A, B):
        """Return improved expression if absorption applies, else None."""
        op = _get_op(B)
        if op not in ("And", "Or"):
            return None
        if A in (_get_args(B) or []):
            return A
        return None

    def _apply_negative_absorption(A, B):
        """Return improved expression if negative absorption applies, else None."""
        op = _get_op(B)
        if op not in ("And", "Or"):
            return None
        args = _get_args(B) or ()
        # Find a child that is (~A | B) or (~A & B)
        for child in args:
            if _is_not(child) and child.args[0] == A:
                # child is ~A
                # find the other part of the disjunction/conjunction
                remaining = [c for c in args if c != child]
                if not remaining:
                    continue
                other = remaining[0]
                # New expression depends on the outer op
                if op == "And":
                    # A & (~A | B) => A & B
                    return type(A)(A.op, A, other)
                else:  # op == "Or"
                    # A | (~A & B) => A | B
                    return type(A)(A.op, A, other)
        return None

    # Work with a copy to avoid mutating the input
    new_args = list(args)

    # Keep applying until stable
    changed = True
    while changed:
        changed = False
        n = len(new_args)
        for i in range(n):
            for j in range(n):
                if i == j:
                    continue
                A = new_args[i]
                B = new_args[j]
                # Try normal absorption
                new_expr = _apply_absorption(A, B)
                if new_expr is not None:
                    new_args[j] = new_expr
                    changed = True
                    continue
                # Try negative absorption
                new_expr = _apply_negative_absorption(A, B)
                if new_expr is not None:
                    new_args[j] = new_expr
                    changed = True

    # Remove duplicates while preserving order
    seen = set()
    unique = []
    for e in new_args:
        key = repr(e)
        if key not in seen:
            seen.add(key)
            unique.append(e)

    return unique<|return|>

