def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    if sys.version_info[0] >= 3:
        # In Python 3 tzname() already returns str, nothing to do
        return namefunc

    def _wrapper(*args, **kwargs):
        try:
            name = namefunc(*args, **kwargs)
        except Exception as e:
            # Propagate exceptions from the original function
            raise e

        # In Python 2 `unicode` is the text type, `str` is bytes
        if isinstance(name, unicode):
            try:
                # Encode to bytes using UTF‑8, falling back to the default encoding
                return name.encode('utf-8')
            except Exception:
                return name.encode(sys.getdefaultencoding(), 'ignore')
        return name

    return _wrapper<|return|>

