def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    # Build command representation
    if isinstance(commands, str):
        # Use the command string and append any args
        cmd = commands
        if args:
            try:
                import shlex
                cmd += ' ' + ' '.join(shlex.quote(str(a)) for a in args)
            except Exception:
                cmd += ' ' + ' '.join(map(str, args))
        use_shell = True
    else:
        # commands is expected to be a list or tuple
        if not isinstance(commands, (list, tuple)):
            raise TypeError("commands must be a string or a list/tuple of arguments")
        cmd = list(commands)
        if args:
            if not isinstance(args, (list, tuple)):
                raise TypeError("args must be a list or tuple")
            cmd.extend(args)
        use_shell = False

    if verbose:
        import sys
        print(f"Running command: {cmd}", file=sys.stderr)

    # Combine environment variables
    if env is None:
        env = {}
    try:
        env_combined = os.environ.copy()
        env_combined.update(env)
    except Exception:
        env_combined = env

    # Prepare stderr handling
    stderr_mode = subprocess.DEVNULL if hide_stderr else None

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=stderr_mode,
            env=env_combined,
            shell=use_shell,
            check=True,
        )
    except subprocess.CalledProcessError as exc:
        # Include command and return code in the exception message
        raise RuntimeError(
            f"Command {cmd!r} exited with non-zero status {exc.returncode}"
        ) from exc

    # Decode bytes to string
    try:
        output = result.stdout.decode("utf-8", errors="replace")
    except Exception:
        output = str(result.stdout)

    return output<|return|>

