                        print(f"WARNING: Validation failed for element {type(element).__name__}: {exc}")

            # Optional digest check
            if valid and check_digests and hasattr(element, "check_digest"):
                try:
                    if not bool(element.check_digest()):
                        valid = False
                        if show_warnings:
                            print(f"WARNING: Digest mismatch for element {type(element).__name__}")
                except Exception as exc:
                    valid = False
                    if show_warnings:
                        print(f"WARNING: Digest check failed for element {type(element).__name__}: {exc}")

            if valid:
                good_objects += 1

            # Recurse into children if iterable
            try:
                for child in element:
                    _validate(child)
            except TypeError:
                # Not iterable – nothing to do
                pass
            except Exception as exc:
                if show_warnings:
                    print(f"WARNING: Iterating children of {type(element).__name__} failed: {exc}")

        _validate(self)
        return num_objects, good_objects<|return|>

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        num_objects = 0
        good_objects = 0
        errors = []
        warnings = []

        def _walk(obj):
            nonlocal num_objects, good_objects
            num_objects += 1

            valid = True

            if validate_objects:
                try:
                    if hasattr(obj, "validate"):
                        obj.validate()
                    elif hasattr(obj, "is_valid"):
                        valid = bool(obj.is_valid)
                except Exception as exc:  # pragma: no cover
                    valid = False
                    errors.append(f"Validation error in {obj!r}: {exc}")

            if check_digests and hasattr(obj, "check_digest"):
                try:
                    if not obj.check_digest():
                        valid = False
                        errors.append(f"Digest mismatch in {obj!r}")
                except Exception as exc:  # pragma: no cover
                    valid = False
                    errors.append(f"Digest check error in {obj!r}: {exc}")

            if valid:
                good_objects += 1
            else:
                if show_warnings:
                    warnings.append(f"Object {obj!r} failed validation")

            # Recurse into children if iterable
            if hasattr(obj, "__iter__"):
                for child in obj:
                    if child is obj:
                        continue
                    _walk(child)

        _walk(self)

        if show_warnings:
            for w in warnings:
                print(f"WARNING: {w}")

        if errors:
            raise ValueError(
                f"Hierarchy validation failed for {num_objects - good_objects} objects: "
                + "; ".join(errors)
            )

        return num_objects, good_objects<|return|>

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    if not hasattr(self, 'root_path'):
        raise AttributeError("Instance lacks 'root_path' attribute.")
    root = self.root_path
    try:
        if os.path.exists(root):
            if os.listdir(root):
