        else:
            os.makedirs(root, exist_ok=False)
        data_dir = os.path.join(root, 'data')
        epoch_dir = os.path.join(data_dir, '1')
        os.makedirs(epoch_dir, exist_ok=True)
        manifest_path = os.path.join(root, 'manifest.json')
        if not os.path.exists(manifest_path):
            with open(manifest_path, 'w', encoding='utf-8') as f:
                f.write('{}')
    except Exception as exc:
        raise RuntimeError(f"Failed to initialize OCFL storage root at '{root}': {exc}") from exc<|return|>

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import os

    # Get the root path; raise an informative error if not set
    if not hasattr(self, 'path'):
        raise AttributeError("The object must have a 'path' attribute pointing to the storage root location.")

    root_path = self.path

    # Create the root directory if it doesn't already exist
    try:
        os.makedirs(root_path, exist_ok=True)
    except OSError as exc:
        raise RuntimeError(f"Failed to create storage root directory '{root_path}': {exc}") from exc

    # Define standard OCFL files that should exist in a fresh root
    ocfl_version_file = os.path.join(root_path, ".ocfl_version")
    manifest_file = os.path.join(root_path, "manifest.json")

    # Create the OCFL version file if missing
    try:
        if not os.path.exists(ocfl_version_file):
            with open(ocfl_version_file, "w", encoding="utf-8") as f:
                # Default to version 2.0; this can be updated later if needed
                f.write("2.0\n")
    except OSError as exc:
        raise RuntimeError(f"Could not create OCFL version file at '{ocfl_version_file}': {exc}") from exc

    # Create an empty manifest file if missing
    try:
        if not os.path.exists(manifest_file):
            with open(manifest_file, "w", encoding="utf-8") as f:
                f.write("{}\n")
    except OSError as exc:
        raise RuntimeError(f"Could not create manifest file at '{manifest_file}': {exc}") from exc

    # Mark the object as initialized so callers can check
    setattr(self, "_is_initialized", True)<|return|>

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if version is None:
        raise ValueError("Version cannot be None")
    # If the input is an integer, just increment and return as a string
    if isinstance(version, int):
        return str(version + 1)
    if not isinstance(version, str):
        raise TypeError(f"Expected str or int for version, got {type(version).__name__}")
    import re
    pattern = re.compile(r'^(.*?)(\d+)$')
    match = pattern.match(version)
    if not match:
        raise ValueError(f"Unable to parse a numeric version from '{version}'")
    prefix, number_part = match.groups()
    try:
        number = int(number_part)
    except ValueError as exc:
        raise ValueError(f"Numeric part '{number_part}' of version '{version}' is not an integer") from exc
    new_number = number + 1
    new_number_str = str(new_number)
    # Preserve original zero padding if present
    if len(new_number_str) < len(number_part) and number_part.startswith('0'):
        new_number_str = new_number_str.zfill(len(number_part))
    return f"{prefix}{new_number_str}"<|return|>

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import json

    # Basic type checks for the input
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    for dir_name in version_dirs:
        if not isinstance(dir_name, str):
            raise TypeError("Each directory name in version_dirs must be a string")

    # Prepare a container for digest mismatches
    if not hasattr(self, "_version_digest_mismatches"):
        self._version_digest_mismatches = {}

    # Iterate over each version directory
    for vdir in version_dirs:
        # Assume inventory file is named 'inventory.json' inside the directory.
        inv_path = os.path.join(vdir, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Inventory file not found for version '{vdir}': {inv_path}")

        # Load and parse the inventory
        try:
            with open(inv_path, "r", encoding="utf-8") as fp:
                inventory = json.load(fp)
        except (OSError, json.JSONDecodeError) as exc:
            raise ValueError(f"Failed to load inventory at {inv_path}: {exc}") from exc

        # Inventory must be a mapping of content IDs to digests
        if not isinstance(inventory, dict):
            raise ValueError(f"Invalid inventory format in {inv_path}: expected a JSON object")

        # Compare each entry against the root inventory (if available)
        root_inventory = getattr(self, "root_inventory", None)
        if root_inventory is None:
            # No root inventory to compare against – simply record the existence of the inventory
            continue

        for content_id, digest in inventory.items():
            root_digest = root_inventory.get(content_id)
            if root_digest is None:
                # The content ID is new in this version – nothing to compare
                continue
            if digest != root_digest:
                # Store a mismatch record
                mismatches = self._version_digest_mismatches.setdefault(vdir, [])
                mismatches.append((content_id, digest, root_digest))

    # Expose the mismatch collection for other methods to use
    return self._version_digest_mismatches
<|return|>

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        import os
        import json

        if not isinstance(version_dirs, (list, tuple)):
            raise TypeError("version_dirs must be a list or tuple of directory names")

        # Store differences for each version relative to the root (first) inventory
        self._inventory_differences = {}
        root_inv = None

        for idx, vdir in enumerate(version_dirs):
            if not isinstance(vdir, str):
                raise TypeError(f"version directory names must be strings; got {type(vdir).__name__}")

            inventory_path = os.path.join(vdir, "inventory.json")
            if not os.path.isfile(inventory_path):
                raise FileNotFoundError(
                    f"No inventory found for version directory '{vdir}'. "
                    "Expected file 'inventory.json'."
                )

            try:
                with open(inventory_path, "r", encoding="utf-8") as f:
                    inv = json.load(f)
            except Exception as exc:
                raise ValueError(
                    f"Could not load inventory from '{inventory_path}': {exc}"
                ) from exc

            # Ensure the inventory has a digests section
            inv_digests = inv.get("digests")
            if inv_digests is None or not isinstance(inv_digests, dict):
                raise ValueError(
                    f"Inventory in '{inventory_path}' lacks a valid 'digests' dictionary."
                )

            if idx == 0:
                # The first inventory is considered the root
                root_inv = inv
                self._inventory_differences[vdir] = {}
                continue

            # Compare current inventory against the root
            differences = {"mismatched": {}, "missing": []}
            root_digests = root_inv.get("digests", {})

            # Check for missing digests that were present in the root
            for key in root_digests:
                if key not in inv_digests:
                    differences["missing"].append(key)

            # Check for digests that differ from the root
            for key, digest in inv_digests.items():
                root_digest = root_digests.get(key)
                if root_digest is None:
                    # New content introduced in this version
                    continue
                if digest != root_digest:
                    differences["mismatched"][key] = {
                        "root": root_digest,
                        "current": digest,
                    }

            self._inventory_differences[vdir] = differences

        # The method does not return anything; the differences are stored in
        # `self._inventory_differences` for later use.<|return|>

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import json

    def _load_inventory(dir_path):
        """Attempt to load an inventory file from the given directory.
        The inventory is expected to be either a JSON list or JSON object
        mapping file paths to digests. Returns a dictionary mapping file
        paths to digests (or None if digest is unknown)."""
        inventory_filenames = ['inventory.json', 'inventory.txt', 'inventory.yaml', 'inventory.yml']
        for filename in inventory_filenames:
            full = os.path.join(dir_path, filename)
            if os.path.isfile(full):
                try:
                    with open(full, 'r', encoding='utf-8') as fp:
                        data = json.load(fp)
                    if isinstance(data, dict):
                        return data
                    elif isinstance(data, list):
                        return {item: None for item in data}
                except Exception:
                    # Malformed inventory; ignore this file
                    return None
        return None

    root_inventory = None
    mismatched_digests = []            # list of tuples (path, root_digest, current_digest)
    missing_in_root = []               # list of tuples (version_dir, missing_path)
    errors = []                        # general error messages

    for idx, ver_dir in enumerate(version_dirs, start=1):
        if not os.path.isdir(ver_dir):
            errors.append(f"Version directory '{ver_dir}' does not exist.")
            continue

        inv = _load_inventory(ver_dir)
        if inv is None:
            errors.append(f"Inventory not found or malformed in '{ver_dir}'.")
            continue

        if root_inventory is None:
            # first version becomes the root baseline
            root_inventory = inv
            continue

        # Compare current inventory to root
        for path, digest in inv.items():
            if path not in root_inventory:
                # file added – no issue, but we keep it for further checks
                continue
            root_digest = root_inventory[path]
            if root_digest != digest:
                mismatched_digests.append((path, root_digest, digest))

        # Check that all files from root are present in this version
        for path in root_inventory:
            if path not in inv:
                missing_in_root.append((ver_dir, path))

    # Store or report results
    self._validation_report = {
        'errors': errors,
        'mismatched_digests': mismatched_digests,
        'missing_in_root': missing_in_root
    }

    # Return a summary of findings to allow callers to act on them
    return {
        'valid': not errors,
        'errors': errors,
        'mismatched_digests': mismatched_digests,
        'missing_in_root': missing_in_root
    }<|return|>

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import hashlib

    # Validate input type
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")

    if not version_dirs:
        raise ValueError("version_dirs cannot be empty")

    # Store mismatched digests per file path
    self._mismatched_digests = {}

    def _file_digest(file_path):
        """Return SHA256 digest of the given file."""
        try:
            with open(file_path, "rb") as f:
                h = hashlib.sha256()
                for chunk in iter(lambda: f.read(8192), b""):
                    h.update(chunk)
            return h.hexdigest()
        except OSError as exc:
            raise IOError(f"Unable to read file '{file_path}': {exc}") from exc

    # Load the root inventory (first version)
    root_dir = version_dirs[0]
    root_inv_path = os.path.join(root_dir, "inventory.xml")
    if not os.path.isfile(root_inv_path):
        raise FileNotFoundError(f"Root inventory file not found: '{root_inv_path}'")

    try:
        with open(root_inv_path, "r", encoding="utf-8") as f:
            root_entries = [line.strip() for line in f if line.strip()]
    except OSError as exc:
        raise IOError(f"Error reading root inventory '{root_inv_path}': {exc}") from exc

    root_set = set(root_entries)

    # Helper to parse an inventory file
    def _parse_inventory(dir_path):
        inv_path = os.path.join(dir_path, "inventory.xml")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Inventory file not found in '{dir_path}': expected '{inv_path}'")
        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                return [line.strip() for line in f if line.strip()]
        except OSError as exc:
            raise IOError(f"Error reading inventory '{inv_path}': {exc}") from exc

    # Iterate over each subsequent version
    for idx, dir_path in enumerate(version_dirs[1:], start=2):
        current_entries = _parse_inventory(dir_path)
        current_set = set(current_entries)

        # Ensure current inventory contains all entries from root
        missing = root_set - current_set
        if missing:
            raise ValueError(
                f"Inventory in '{dir_path}' is missing {len(missing)} entries present in root inventory: {missing}"
            )

        # Compare digests for files present in both inventories
        for rel_path in root_set:
            root_file = os.path.join(root_dir, rel_path)
            current_file = os.path.join(dir_path, rel_path)

            if not os.path.isfile(current_file):
                # If the file disappeared, treat as missing rather than digest mismatch
                continue

            try:
                root_digest = _file_digest(root_file)
                current_digest = _file_digest(current_file)
            except IOError as exc:
                raise IOError(f"Digest validation failed for '{rel_path}' in '{dir_path}': {exc}") from exc

            if root_digest != current_digest:
                self._mismatched_digests.setdefault(rel_path, []).append(
                    f"Version {idx} (dir '{dir_path}') differs from root digest "
                    f"{root_digest[:8]}... vs {current_digest[:8]}..."
                )

    # The method returns the dictionary of mismatched digests; an empty dict means no mismatches
    return self._mismatched_digests<|return|>

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    from pathlib import Path
    try:
        p = Path(path)
    except Exception as exc:
        return f"invalid_path: {exc}"

    if not p.exists():
        return "nonexistent"

    if p.is_file():
        return "file"

    # Directory case – look for a '0=*' Namaste file
    try:
        namaste_files = [f for f in p.iterdir()
                         if f.is_file() and f.name.startswith("0=") and "=" in f.name]
    except OSError as exc:
        return f"access_error: {exc}"

    if namaste_files:
        return "object"

    # If no Namaste file, see if this looks like a storage root
    if (p / "objects").is_dir():
        return "root"

    return "unknown"<|return|>

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    import re
    try:
        if not os.path.exists(path):
            return f"path does not exist: {path}"
        if os.path.islink(path):
            # Resolve the link
            path = os.path.realpath(path)
        if os.path.isfile(path):
            return 'file'
        if os.path.isdir(path):
            # Check for a directory that contains a 0=* subdirectory
            for item in os.listdir(path):
                if re.match(r'^0=', item):
                    sub = os.path.join(path, item)
                    if os.path.isdir(sub):
                        return 'object'
            # Check for characteristics of a storage root
            # Common root indicator: existence of a directory named '_ocfl'
            if any(name.startswith('_ocfl') or name.endswith('_ocfl') for name in os.listdir(path)):
                return 'root'
            # If there is an inventory file directly in the root it might be the root
            if any(name == 'inventory' for name in os.listdir(path)):
                return 'root'
            # Default fallback
            return 'unknown directory'
        # If it's neither file nor dir (e.g., socket, FIFO), just return type
        return f"unknown file type: {type(path)}"
    except PermissionError:
        return f"Permission denied for {path}"
    except Exception as e:
        return f"Error accessing {path}: {e}"<|return|>

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Ensure params is a dictionary
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    # Nothing to do if no bug_ids were supplied
    if bug_ids is None:
        return params
    # Build a list of string bug ids
    ids = []
    try:
        if isinstance(bug_ids, (list, tuple, set)):
            ids = [str(b) for b in bug_ids if b is not None]
        else:
            # Assume a single id has been passed
            ids = [str(bug_ids)]
    except Exception as exc:
        raise ValueError("bug_ids must be an iterable of IDs or a single ID") from exc
    if not ids:
        return params
    # Construct the comma‑separated IDs string
    params['ids'] = ','.join(ids)
    return params<|return|>

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dict")
    # Convert bug_ids into a list of string IDs
    try:
        if isinstance(bug_ids, str):
            bug_ids_list = [bid.strip() for bid in bug_ids.split(',') if bid.strip()]
        else:
            bug_ids_list = [str(bid) for bid in bug_ids]
    except Exception as exc:
        raise ValueError(f"Unable to interpret bug_ids: {exc}") from exc
    if not bug_ids_list:
        return params
    # Insert or merge into the params dictionary
    if "ids" in params:
        if not isinstance(params["ids"], list):
            raise TypeError("Existing 'ids' value must be a list")
        params["ids"].extend(bug_ids_list)
    else:
        params["ids"] = bug_ids_list
    return params<|return|>

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dict")
    # Normalize bug_ids to an iterable of id strings
    if isinstance(bug_ids, str):
        bug_id_list = [bug_ids]
    else:
        try:
            bug_id_list = list(bug_ids)
        except TypeError:
            bug_id_list = [bug_ids]
    # Convert all ids to strings and remove empty values
    bug_id_set = {str(bid) for bid in bug_id_list if bid not in (None, "", [])}
    if not bug_id_set:
        return params
    # Merge with existing 'ids' entry if present
    if "ids" in params:
        existing = params["ids"]
        if isinstance(existing, str):
            existing_set = {bid.strip() for bid in existing.split(",") if bid.strip()}
            bug_id_set.update(existing_set)
        elif isinstance(existing, (list, tuple)):
            bug_id_set.update(str(bid) for bid in existing)
    # Store back as a comma‑separated string (Bugzilla accepts that)
    params["ids"] = ",".join(sorted(bug_id_set))
    return params<|return|>

