def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    import argparse
    try:
        parser = argparse.ArgumentParser()
        # Subparsers can be added by callers before invoking this function.
        # We always add a placeholder so that any detected subparser name is accessible.
        subparsers = parser.add_subparsers(dest='__subparser_name', metavar='subparser')
        # Parse known args; keep unknowns so callers can parse subparser specific options if needed.
        known_args, unknown_args = parser.parse_known_args(list(unparsed_arguments))
        result = {'global': known_args}

        # If a subparser was detected, store its namespace separately.
        subparser_name = getattr(known_args, '__subparser_name', None)
        if subparser_name:
            # `unknown_args` likely contains options that belong to the subparser.
            # Convert them into a simple Namespace for the caller to use.
            # This simplistic conversion assumes `--key value` or `--flag` syntax.
            sub_args_dict = {}
            it = iter(unknown_args)
            for token in it:
                if token.startswith('--'):
                    key = token.lstrip('-').replace('-', '_')
                    # Check if next token is a value or another flag
                    try:
                        nxt = next(it)
                    except StopIteration:
                        nxt = None
                    if nxt and not nxt.startswith('-'):
                        sub_args_dict[key] = nxt
                    else:
                        sub_args_dict[key] = True
                        # put back the token if it was another flag
                        if nxt and nxt.startswith('-'):
                            it = (token for token in [nxt] + list(it))
                else:
                    # positional or invalid token; ignore or store as list
                    sub_args_dict.setdefault('positional', []).append(token)
            result[subparser_name] = argparse.Namespace(**sub_args_dict)
        return result
    except Exception as exc:
        raise RuntimeError(f"Argument parsing error: {exc}") from exc<|return|>

