            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from collections import OrderedDict

    def is_mapping_node(node):
        """Return True if the node is (likely) a MappingNode."""
        return hasattr(node, 'tag') and node.tag == 'tag:yaml.org,2002:map' and isinstance(node.value, list)

    def merge_values(existing, incoming):
        """Merge two node values according to rules."""
        if is_mapping_node(existing) and is_mapping_node(incoming):
            # Recursive merge of mapping contents
            return MappingNode(
                tag='tag:yaml.org,2002:map',
                value=deep_merge_nodes(existing.value + incoming.value)
            )
        else:
            # Non-mapping or differing types: last wins
            return incoming

    # Perform merging using an OrderedDict to preserve insertion order of first occurrence
    merged = OrderedDict()
    key_to_original = {}

    for key_node, value_node in nodes:
        key = getattr(key_node, 'value', None)
        if key is None:
            # Fallback: use string representation if 'value' attribute doesn't exist
            key = str(key_node)
        if key in merged:
            merged[key] = merge_values(merged[key], value_node)
        else:
            merged[key] = value_node
            key_to_original[key] = key_node

    # Build final list of tuples preserving the order of first appearances
    result = [(key_to_original[key], merged[key]) for key in merged]
    return result

