def bash_completion():
    """
    Return a bash completion script for the borgmatic command.
    Produce this by introspecting borgmatic's command-line argument parsers.
    """
    import argparse
    import importlib

    # Try to import borgmatic and locate a global ArgumentParser instance.
    try:
        borg = importlib.import_module('borgmatic')
    except Exception as exc:
        return f"# Failed to import borgmatic: {exc}"
    parser = None
    for name in dir(borg):
        obj = getattr(borg, name)
        if isinstance(obj, argparse.ArgumentParser):
            parser = obj
            break
    if parser is None:
        # Attempt to find a parser in any submodule of borgmatic
        for subname in dir(borg):
            submodule = getattr(borg, subname)
            if isinstance(submodule, type) and hasattr(submodule, '__file__'):
                try:
                    mod = importlib.import_module(f'borgmatic.{subname}')
                    for nm in dir(mod):
                        obj = getattr(mod, nm)
                        if isinstance(obj, argparse.ArgumentParser):
                            parser = obj
                            break
                except Exception:
                    continue
            if parser is not None:
                break

    if parser is None:
        return "# No argparse.ArgumentParser instance could be found in borgmatic."

    # Try to generate the bash completion script using argcomplete.
    try:
        from argcomplete.completion import get_bash_completion_script
    except Exception as exc:
        return f"# Unable to import argcomplete to generate completion script: {exc}"

    try:
        # The function name __argcomplete__ is what argcomplete expects.
        script = get_bash_completion_script(parser, function_name='__argcomplete')
        return script
    except Exception as exc:
