def bash_completion():
    '''
    Return a bash completion script for the borgmatic command.
    Produce this by introspecting borgmatic's command-line argument parsers.
    '''
    try:
        import pkgutil
        import importlib
        import sys

        # Find all modules under the borgmatic package that expose a get_parser()
        parsers = {}
        for _, module_name, is_pkg in pkgutil.iter_modules(pkgutil.sys.path):
            if not module_name.startswith('borgmatic'):
                continue
            if is_pkg:
                continue
            try:
                m = importlib.import_module(module_name)
            except Exception:
                continue
            get_parser = getattr(m, 'get_parser', None)
            if callable(get_parser):
                try:
                    parsers[module_name] = get_parser()
                except Exception:
                    pass

        # Build a dictionary of subcommand names to a list of options
        completions = {}
        for name, parser in parsers.items():
            opts = []
            for action in parser._actions:
                if action.option_strings:
                    opts.extend(action.option_strings)
                else:
                    opts.append(action.dest)
            completions[name] = opts

        # Build a bash completion script
        lines = [
            '_borgmatic_complete(){',
            '    local cur prev words cword',
            '    COMPREPLY=()',
            '    _get_comp_words_by_ref -n : cur prev words cword',
            '    case "$prev" in',
            '    *)',
            f'        COMPREPLY=$(compgen -W "{ " ".join(sorted(completions.keys())) }" -- "$cur")',
            '        ;;',
            '    esac',
            '    return 0',
            '}',
            'complete -F _borgmatic_complete borgmatic'
        ]
        return "\n".join(lines)

    except Exception as err:
        return f'# Error generating bash completion: {err}'

def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    import argparse

    # Create a top‑level parser.  Subparsers are expected to be added by the caller
    # before this function is invoked; otherwise the parser will simply handle
    # the global arguments.
    top_parser = argparse.ArgumentParser(add_help=False)
    subparsers = top_parser.add_subparsers(dest='subcommand', metavar='command')
    # Using parse_known_args so that unknown arguments are left in the list of
    # remaining arguments rather than causing a SystemExit.
    try:
        namespace, remaining = top_parser.parse_known_args(unparsed_arguments)
    except Exception as exc:
        # In the unlikely event of a parsing error, return an empty dictionary so
        # that the caller can decide how to handle the failure.
        return {}

    # If a subcommand was detected, return a mapping from the subcommand name to
    # the namespace.  Otherwise return the namespace under the key "global".
    if namespace.subcommand:
        return {namespace.subcommand: namespace}
    else:
        return {'global': namespace}<|return|>

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError('unparsed_arguments must be a sequence')
    if not isinstance(subparsers, dict):
        raise TypeError('subparsers must be a dict')

    parsed = {}
    known_all = set()

    for name, parser in subparsers.items():
        try:
            namespace, remaining = parser.parse_known_args(unparsed_arguments)
        except Exception as exc:
            raise RuntimeError(f'Failed to parse arguments for subparser "{name}": {exc}') from exc

        parsed[name] = namespace
        # Determine which arguments this parser consumed
        consumed = set(unparsed_arguments) - set(remaining)
        known_all.update(consumed)

    remaining_all = [arg for arg in unparsed_arguments if arg not in known_all]
    return parsed, remaining_all<|return|>

