def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not isinstance(size, str):
        raise ValueError(f"size must be a string, got {type(size).__name__}")
    s = size.strip()
    if s == "":
        raise ValueError("size string cannot be empty")
    import re
    match = re.fullmatch(r"([0-9]*\.?[0-9]+)\s*([A-Za-z]*?)", s)
    if not match:
        raise ValueError(f"Could not parse size: {size!r}")
    num_str, unit = match.groups()
    try:
        number = float(num_str)
    except ValueError:
        raise ValueError(f"Invalid numeric part in size: {size}")
    unit = unit.lower()
    if unit.endswith("b") and unit != "b":
        unit = unit[:-1]  # drop trailing 'b' in units like kb, mb, etc.
    factor = 1
    if unit:
        base = unit[0]
        if base == "k":
            factor = 10**3
        elif base == "m":
            factor = 10**6
        elif base == "g":
            factor = 10**9
        elif base == "t":
            factor = 10**12
        elif base == "p":
            factor = 10**15
        elif base == "e":
            factor = 10**18
        elif base == "b":
            factor = 1
        else:
            raise ValueError(f"Unknown unit in size: {size}")
    return int(round(number * factor))<|return|>

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable `dicts`.

    Parameters
    ----------
    dicts : iterable of dict-like
        Each element is expected to be a mapping with numeric values. Non-mapping
        or non-numeric entries will raise ``TypeError``.

    Returns
    -------
    dict
        A new dictionary containing the sum of values for each key.

    Examples
    --------
    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    if dicts is None:
        return result
    # allow any iterable; if dicts is a single dict, treat as a single-element iterable
    try:
        iter(dicts)
    except TypeError:
        dicts = [dicts]
    for d in dicts:
        try:
            items = d.items()
        except AttributeError:
            raise TypeError(f"Expected mapping type, got {type(d).__name__}") from None
        for key, value in items:
            if not isinstance(value, (int, float, complex)):
                raise TypeError(f"Value for key {key!r} must be numeric, got {type(value).__name__}")
            result[key] = result.get(key, 0) + value
    return result<|return|>

