def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args.
    Custom URL items are expected to be in the form ``{key}`` and will
    be replaced by the corresponding value from *url_args*.
    """
    # Validate arguments
    if not isinstance(url, str):
        raise TypeError(f"url must be a string, got {type(url).__name__}")
    if not isinstance(url_args, dict):
        raise TypeError(f"url_args must be a dict, got {type(url_args).__name__}")

    # If there is nothing to replace, return the original URL
    if not url_args:
        return url

    # Attempt simple replacement for each key
    result = url
    for key, value in url_args.items():
        try:
            placeholder = f"{{{key}}}"
            # Only replace if the placeholder actually exists in the URL
            if placeholder in result:
                result = result.replace(placeholder, str(value))
        except Exception:
            # Log the error but continue processing other items
            # (logging is omitted here to keep this lightweight)
            continue

    return result<|return|>

