    if not url_args:
        return url
    # Ensure the input URL is a string
    try:
        url = str(url)
    except Exception:
        raise TypeError("url must be a string-like object")
    # Build a dictionary of arguments
    if isinstance(url_args, dict):
        mapping = dict(url_args)
    else:
        try:
            mapping = {k: v for k, v in url_args}
        except Exception:
            raise TypeError("url_args must be a dict or an iterable of (key, value) pairs")
    # Replace placeholders in the form {placeholder}
    import re
    pattern = re.compile(r'{([^}]+)}')
    def _replace(match):
        key = match.group(1)
        if key in mapping:
            return str(mapping[key])
        raise ValueError(f"Missing value for URL placeholder '{key}'")
    return pattern.sub(_replace, url)<|return|>

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    import re
    # Validate input types
    if not isinstance(url, str):
