def vertex3tuple(vertices):
    """return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::

        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    """
    if vertices is None:
        raise ValueError("vertices must not be None")
    try:
        verts = list(vertices)
    except TypeError as exc:
        raise TypeError("vertices must be an iterable") from exc

    n = len(verts)
    if n == 0:
        return []
    if n == 1:
        return [(verts[0], verts[0], verts[0])]

    triples = [(verts[(i - 1) % n], verts[i], verts[(i + 1) % n]) for i in range(n)]
    return triples<|return|>

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError(f"Number must be an integer, got {type(number).__name__}")
    if number < 0:
        raise ValueError("Number must be non‑negative")
    if not isinstance(alphabet, (list, tuple)) or not alphabet:
        raise ValueError("Alphabet must be a non‑empty list or tuple of strings")
    if not all(isinstance(ch, str) for ch in alphabet):
        raise TypeError("All elements of alphabet must be strings")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"Padding must be an integer, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("Padding must be non‑negative")

    base = len(alphabet)

    # Convert number to digits in base `base`
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        num = number
        while num > 0:
            digits.append(alphabet[num % base])
            num //= base
        digits.reverse()

    result = ''.join(digits)

    # Apply padding if requested
    if padding is not None and len(result) < padding:
        # Pad with the "zero" character (alphabet[0])
        result = alphabet[0] * (padding - len(result)) + result

    return result<|return|>

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise TypeError("The 'number' argument must be an integer.")
    if not isinstance(alphabet, list) or not alphabet:
        raise ValueError("The 'alphabet' argument must be a non-empty list.")
    base = len(alphabet)
    if base < 2:
        raise ValueError("The alphabet must contain at least two symbols to represent numbers.")
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("Padding must be a non-negative integer or None.")
    # Handle negative numbers: prepend a minus sign; the rest is converted as positive
    negative = number < 0
    num = abs(number)
    # Special case for zero – avoid an infinite loop
    if num == 0:
        result = alphabet[0]
    else:
        digits = []
        while num:
            num, rem = divmod(num, base)
            digits.append(alphabet[rem])
        # The digits list is least‑significant first; reverse it to get the correct order
        digits.reverse()
        # Pad with the first alphabet character if required
        if padding is not None and len(digits) < padding:
            digits = [alphabet[0]] * (padding - len(digits)) + digits
        result = "".join(digits)
    # Prepend negative sign if needed
