        raise ValueError("alphabet must contain only single-character strings")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet contains duplicate characters")
    base = len(alphabet)
    if base <= 1:
        raise ValueError("alphabet must contain at least two distinct characters")

    # Convert number to base `base` representation
    if number == 0:
        result = alphabet[0]
