def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError(f"{cls!r} is not a class")
    result = set()
    try:
        def _walk(c):
            for sub in c.__subclasses__():
                result.add(sub)
                _walk(sub)
        _walk(cls)
    except Exception as e:
        # In case of recursion limit or other runtime issues, return what we have
        raise RuntimeError(f"Error while retrieving subclasses of {cls.__name__}: {e}") from e
    return result<|return|>

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("The argument must be a class (type).")
    seen = set()
    result = []

    def _collect(current):
        try:
            subs = current.__subclasses__()
        except AttributeError:
            return
        for sub in subs:
            if sub not in seen:
                seen.add(sub)
                result.append(sub)
                _collect(sub)

    _collect(cls)
    return result<|return|>

