def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if not isinstance(destination_path, Path):
        try:
            destination_path = Path(destination_path)
        except Exception as e:
            raise TypeError("destination_path must be a pathlib.Path or convertible to one") from e

    if not destination_path.exists():
        try:
            destination_path.mkdir(parents=True, exist_ok=True)
        except Exception as e:
            raise OSError(f"Could not create destination directory '{destination_path}'") from e

    try:
        with requests.get(url, stream=True, timeout=30) as r:
            r.raise_for_status()
            temp_path = destination_path / "repo_archive.tar.gz"
            with open(temp_path, "wb") as f:
                for chunk in r.iter_content(chunk_size=8192):
                    if chunk:
                        f.write(chunk)
    except requests.RequestException as e:
        raise RuntimeError(f"Failed to download archive from {url}") from e

    try:
        import tarfile
        if not tarfile.is_tarfile(temp_path):
            raise ValueError(f"The downloaded file at {temp_path} is not a tar archive")
        with tarfile.open(temp_path, "r:gz") as tar:
            tar.extractall(path=destination_path)
    except (tarfile.TarError, Exception) as e:
        raise RuntimeError(f"Failed to extract the archive '{temp_path}'") from e
    finally:
        try:
            temp_path.unlink()
        except Exception:
            pass

    return destination_path<|return|>

