def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    from pathlib import Path

    # Resolve paths
    archive = Path(archive_path)
    if not archive.is_file():
        raise FileNotFoundError(f"Archive does not exist: {archive_path}")

    tmp_dir = Path(tmp_path)
    tmp_dir.mkdir(parents=True, exist_ok=True)

    # Determine extraction target directory name
    if filename is None:
        # Strip common multi‑part extensions
        base_name = archive.name
        for ext in (".tar.gz", ".tgz", ".tar.bz2", ".tbz2", ".tar.xz", ".txz"):
            if base_name.endswith(ext):
                base_name = base_name[: -len(ext)]
                break
        else:
            base_name = Path(base_name).stem
        filename = base_name

    target_dir = tmp_dir / filename
    target_dir.mkdir(parents=True, exist_ok=True)

    # Choose extraction command based on file extension
    cmd = None
    try:
        suffixes = [s.lower() for s in archive.suffixes]  # handles multi extensions
        if ".tar" in suffixes and ".gz" in suffixes:
            cmd = ["tar", "-xzf", str(archive), "-C", str(target_dir)]
        elif ".tar" in suffixes and ".bz2" in suffixes:
            cmd = ["tar", "-xjf", str(archive), "-C", str(target_dir)]
        elif ".tar" in suffixes and ".xz" in suffixes:
            cmd = ["tar", "-xJf", str(archive), "-C", str(target_dir)]
        elif ".zip" in suffixes:
            cmd = ["unzip", "-q", str(archive), "-d", str(target_dir)]
        else:
