def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import subprocess
    from pathlib import Path

    # Resolve paths
    archive = Path(archive_path)
    if not archive.is_file():
        raise FileNotFoundError(f"Archive file '{archive_path}' does not exist.")

    tmp_dir = Path(tmp_path).expanduser()
    tmp_dir.mkdir(parents=True, exist_ok=True)

    # Determine extraction target name
    if filename:
        target_name = Path(filename).stem
    else:
        target_name = archive.stem
    extract_dir = tmp_dir / target_name

    if extract_dir.exists():
        raise FileExistsError(f"Extraction target '{extract_dir}' already exists.")

    # Determine archive type and build extraction command
    suffixes = [s.lower() for s in archive.suffixes]
    cmd: List[str]
    if archive.suffix.lower() == ".zip":
        cmd = ["unzip", "-q", str(archive), "-d", str(tmp_dir)]
    elif any(s in suffixes for s in (".tar", ".tar.gz", ".tgz", ".tar.bz2", ".tbz2")):
        cmd = ["tar", "-xf", str(archive), "-C", str(tmp_dir)]
    else:
        raise ValueError(f"Unsupported archive format: {''.join(suffixes)}")

    try:
        subprocess.run(cmd, check=True)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(
            f"Extraction command failed: {' '.join(cmd)} ⟶ {e}"
        ) from e

    # Detect the actual extracted root directory
    contents = list(tmp_dir.iterdir())
    if len(contents) == 1 and contents[0].is_dir():
        root = contents[0]
    else:
        root = tmp_dir

    return root.as_uri()
<|return|>

def addignored(ignored=None):
    """Use the git command to obtain the file names, turn it into a list,
    sort the list for only ignored files, return those files as a single
    string with each filename separated by a comma."""
    try:
        cmd = ["git", "ls-files", "--others", "--ignored", "--exclude-standard"]
        # If a specific path is provided, just use it in the command
        if ignored:
            cmd.append(ignored)
        output = subprocess.check_output(
            cmd,
            universal_newlines=True,
            stderr=subprocess.DEVNULL
        )
        files = [f.strip() for f in output.splitlines() if f.strip()]
        files.sort()
        return ",".join(files)
    except Exception:
