def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    freq = frequency.strip().lower()
    if freq == "always":
        return None

    parts = freq.split()
    if len(parts) != 2:
        raise ValueError(f"Unable to parse frequency: '{frequency}'")

    number_str, unit = parts
    try:
        number = int(number_str)
    except ValueError:
        try:
            number = float(number_str)
            if not number.is_integer():
                raise ValueError
            number = int(number)
        except Exception:
            raise ValueError(f"Invalid number in frequency: '{number_str}'") from None

    unit = unit.rstrip('s')  # normalize if plural

    kwargs = {}
    if unit in ('day', 'days'):
        kwargs['days'] = number
    elif unit in ('week', 'weeks'):
        kwargs['weeks'] = number
    elif unit in ('hour', 'hours'):
        kwargs['hours'] = number
    elif unit in ('minute', 'minutes'):
        kwargs['minutes'] = number
    elif unit in ('second', 'seconds'):
        kwargs['seconds'] = number
    elif unit in ('millisecond', 'milliseconds'):
        kwargs['milliseconds'] = number
    else:
        raise ValueError(f"Unsupported time unit in frequency: '{unit}'")

    return datetime.timedelta(**kwargs)<|return|>

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not isinstance(host, str):
        raise TypeError("host must be a string")

    host = host.strip()
    if host.lower() == "localhost":
        return True

    try:
        addresses = socket.getaddrinfo(host, None, proto=socket.IPPROTO_TCP)
    except socket.gaierror:
        return False

    for family, _, _, _, sockaddr in addresses:
        address = sockaddr[0]
        try:
            import ipaddress
            ip = ipaddress.ip_address(address)
            if ip.is_loopback:
                return True
        except Exception:
            continue

    return False<|return|>

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Quick string checks for common localhost representations
    if not host:
        return False

    if host == "localhost" or host.lower() == "localhost":
        return True

    # Resolve the host to addresses and check if any are loopback
    try:
        addrinfo = socket.getaddrinfo(host, None)
    except socket.gaierror:
        # Unable to resolve; cannot be localhost
        return False

    for family, _, _, _, sockaddr in addrinfo:
        try:
            # sockaddr is a tuple; IPv4: (address, port, ...), IPv6: (address, port, flowinfo, scopeid)
            ip = sockaddr[0]
        except (IndexError, TypeError):
            continue

        if family == socket.AF_INET:
            # IPv4 loopback range: 127.0.0.0/8
            if ip == "127.0.0.1" or ip.split(".")[0] == "127":
                return True
        elif family == socket.AF_INET6:
            # IPv6 loopback address is ::1
            if ip == "::1":
                return True

    return False<|return|>

def is_local(host):
    """
    Checks if the user supplied host is the localhost.

    Parameters
    ----------
    host : str or any
        The hostname or IP address to test.

    Returns
    -------
    bool
        ``True`` if the host resolves to the local machine, otherwise ``False``.
    """
    import socket
    try:
        if host is None:
            return False
        host_str = str(host).strip()
        # Basic standard localhost definitions
        if host_str.lower() in ('localhost', '127.0.0.1', '::1'):
            return True

        # Resolve the provided hostname/IP
        try:
            addrinfo = socket.getaddrinfo(host_str, None)
        except Exception:
            return False

        # Resolve localhost to get the local IP addresses for comparison
        try:
            local_addrinfo = socket.getaddrinfo('localhost', None)
        except Exception:
            return False

        local_ips = {ai[4][0] for ai in local_addrinfo}
        # If any of the resolved addresses match a local address, return True
        for ai in addrinfo:
            if ai[4][0] in local_ips:
                return True

        return False
    except Exception:
        # Any unexpected error (e.g. invalid host format) results in False
        return False<|return|>

