def make_find_paths(find_paths):
    '''
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    '''
    try:
        if not find_paths:
            return []

        result = []
        for item in find_paths:
            # Ensure string type for processing
            if not isinstance(item, str):
                try:
                    item = str(item)
                except Exception as exc:
                    raise ValueError(f"Unable to convert find path to string: {item}") from exc

            # If the item already looks like a pattern (contains ':'), leave it alone
            if ':' in item:
                result.append(item)
            else:
                # Escape any regex metacharacters in the fragment to avoid unintended globbing
                escaped_fragment = re.escape(item)
                # Wrap the fragment with the standard search glob
                result.append(f"sh:**/*{escaped_fragment}*/**")
        return result
    except Exception as exc:
        # Re‑raise with context
        raise RuntimeError(f"Error generating find paths: {exc}") from exc<|return|>

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    import sys
    try:
        # Windows platforms
        if sys.platform.startswith('win'):
            # MSYSTEM is typically set to "MINGW64" or "MINGW32" by Git Bash
            msystem = os.environ.get('MSYSTEM', '').lower()
            if msystem in ('mingw64', 'mingw32', 'msys'):
                return True
            # Some installations set OSTYPE to "msys"
            if os.environ.get('OSTYPE', '').lower().startswith('msys'):
                return True
        return False
    except Exception:
        # In case environment variables or platform checks raise an unexpected error
        return False<|return|>

