def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Extract variable name and optional default from the matcher
    if isinstance(matcher, dict):
        var_name = matcher.get('name') or matcher.get('var')
        default_val = matcher.get('default')
    elif hasattr(matcher, 'group'):
        try:
            var_name = matcher.group(1)
        except IndexError:
            raise ValueError('Matcher does not contain a variable name.')
        default_val = matcher.group(2) if matcher.lastindex and matcher.lastindex >= 2 else None
    else:
        raise TypeError('Matcher must be a dict or a re.Match-like object.')

    if not isinstance(var_name, str):
        raise ValueError('Variable name must be a string.')

    # Retrieve the environment variable
    env_value = os.getenv(var_name)
    if env_value is not None:
        return env_value.strip()

    # Use the default value if provided
    if default_val is not None:
        return default_val.strip()

    # If neither environment value nor default is available, raise an error
    raise KeyError(f'Environment variable "{var_name}" is not defined and no default was provided.')
