def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError: if the href is not a valid URL or missing essential parts
    """
    if not isinstance(image_href, str):
        raise ValueError(f"image_href must be a string, got {type(image_href).__name__}")

    try:
        parsed = urllib.parse.urlparse(image_href)
    except Exception as exc:
        raise ValueError(f"Unable to parse URL '{image_href}': {exc}") from exc

    if not parsed.scheme:
        raise ValueError(f"URL must have a scheme (http/https), got: '{image_href}'")
    if not parsed.netloc:
        raise ValueError(f"URL must have a network location, got: '{image_href}'")

    use_ssl = parsed.scheme.lower() == "https"

    # Extract the image id from the path. Strip trailing slashes first
    path = parsed.path or ""
    image_id = path.rstrip("/").split("/")[-1] if path else ""

    if not image_id:
        # Fallback: try the query component, just in case
        image_id = parsed.query or ""
    if not image_id:
        raise ValueError(f"Could not determine an image id from URL '{image_href}'")

    return image_id, parsed.netloc, use_ssl<|return|>

