def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    # Ensure the roots set is a mutable set
    if roots is None:
        roots_set: Set["Node"] = set()
    else:
        roots_set = set(roots)

    # Collect all children (subjects) and all parents (objects)
    children: Set["Node"] = set()
    parents: Set["Node"] = set()

    try:
        for child, _, parent in graph.triples((None, prop, None)):
            children.add(child)
            parents.add(parent)
    except Exception as exc:
        # In case graph.triples cannot be iterated, raise a descriptive error
        raise RuntimeError(f"Unable to iterate over triples with predicate {prop}") from exc

    # Determine nodes that are children but have no parents -> roots
    for child in children:
        if child not in parents:
            roots_set.add(child)

    return roots_set<|return|>

