def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    import json
    import os
    import re

    logger = logging.getLogger('config_loader')
    configs = {}
    error_records = []

    def resolve_env_vars(obj):
        """Recursively resolve ${VAR} placeholders in string values."""
        if isinstance(obj, dict):
            return {k: resolve_env_vars(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [resolve_env_vars(item) for item in obj]
        if isinstance(obj, str):
            def replace_var(match):
                var_name = match.group(1)
                return os.getenv(var_name, match.group(0))
            # Replace ${VAR} patterns
            return re.sub(r'\$\{([^}]+)\}', replace_var, obj)
        return obj

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                try:
                    config = json.load(f)
                except json.JSONDecodeError as e:
                    # Try to load as YAML if json fails
                    try:
                        import yaml
                        config = yaml.safe_load(f)
                    except Exception as yaml_exc:
                        msg = f"Failed to parse JSON/YAML for file '{filename}': {e}"
                        record = logging.LogRecord(logger.name, logging.ERROR,
                                                  filename, 0, msg, None, None)
                        error_records.append(record)
                        continue

            if resolve_env:
                config = resolve_env_vars(config)

            # Merge overrides if provided
            if overrides and filename in overrides:
                for key, val in overrides[filename].items():
                    config[key] = val

            configs[filename] = config

        except FileNotFoundError:
            msg = f"Configuration file not found: {filename}"
            record = logging.LogRecord(logger.name, logging.ERROR,
                                      filename, 0, msg, None, None)
            error_records.append(record)
        except Exception as exc:
            msg = f"Error loading configuration '{filename}': {exc}"
            record = logging.LogRecord(logger.name, logging.ERROR,
                                      filename, 0, msg, None, None)
            error_records.append(record)

    return configs, error_records<|return|>

