def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    from collections.abc import Sequence

    # Fast path: if seq is already a sequence (list, tuple, str, bytes, range, etc.)
    try:
        if isinstance(seq, Sequence):
            return seq, type(seq)
    except Exception:
        pass

    # If seq is an iterable but not a sequence, try to materialise it into a list.
    try:
        derived = list(seq)
    except TypeError:
        # seq is not iterable; package it into a singleton list instead.
        derived = [seq]

    # Return the derived sequence and its type.
    return derived, type(derived)<|return|>

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if seq is None:
        raise ValueError("seq must not be None")

    orig_type = type(seq)

    # If seq is already a sequence type that we want to keep as-is
    if isinstance(seq, (list, tuple, str, bytes)):
        sequence = seq
    else:
        try:
            iterator = iter(seq)
        except TypeError:
            raise TypeError(f"Object of type {orig_type.__name__} is not iterable")

        if bufsize is not None and bufsize > 0:
            # Collect up to bufsize items from the iterator
            sequence = []
            for _ in range(bufsize):
                try:
                    sequence.append(next(iterator))
                except StopIteration:
                    break
        else:
            sequence = list(iterator)

    return (sequence, orig_type)<|return|>

