    Note that after changing (filling) the histogram
    one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Helper: get the raw histogram data.
    # The histogram data is expected to be stored in an attribute named
    # ``data`` or ``values`` or ``counts``; fall back to the first numeric
    # attribute found in ``self.__dict__``.
    def _get_hist_data():
        for name in ('data', 'values', 'counts'):
            if hasattr(self, name):
                return getattr(self, name)
        # try to find a list/array among instance attributes
        for attr in self.__dict__.values():
            if isinstance(attr, (list, tuple, bytearray)):
                return attr
        raise AttributeError(
            "Histogram object does not expose a suitable data attribute "
            "(expected 'data', 'values', or 'counts')."
        )

    # Get current scale or compute if needed
    if other is None:
        # compute or fetch existing scale
        if recompute or not hasattr(self, '_scale') or self._scale is None:
            hist = _get_hist_data()
            try:
                self._scale = float(sum(hist))
            except Exception as exc:
                raise ValueError(
                    "Unable to compute scale: histogram data must be numeric."
                ) from exc
        return self._scale

    # == Rescaling part ==
    # Validate the target scale
    if not isinstance(other, (int, float)):
        raise TypeError("other must be a number when rescaling the histogram.")
    # If we don't have a cached scale, compute it first
    if not hasattr(self, '_scale') or self._scale is None:
        self.scale(recompute=True)
    if self._scale == 0:
        # Zero scale cannot be used for rescaling
        raise LenaValueError(
            "Cannot rescale histogram with zero scale."
        )
    factor = float(other) / self._scale

    # Scale the underlying histogram data
    hist = _get_hist_data()
    try:
        # Try numpy-style multiplication if possible
        scaled = hist * factor
    except Exception:
        # fallback to list/tuple multiplication
        scaled = [v * factor for v in hist]
