    if hasattr(self, 'data'):
        self.data = scaled
    elif hasattr(self, 'values'):
        self.values = scaled
    elif hasattr(self, 'counts'):
        self.counts = scaled
    else:
        # No standard attribute found; store back in the first numeric
        for key, value in self.__dict__.items():
            if value is hist:
                self.__dict__[key] = scaled
