    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before, it is computed and stored for
    subsequent use (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram one must explicitly
    recompute the scale if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Determine if we need to recompute the scale
    if recompute or not hasattr(self, "_scale_cache"):
        # Try to compute the integral from common storage attributes
        if hasattr(self, "bins"):
            self._scale_cache = sum(self.bins)
        elif hasattr(self, "counts"):
            self._scale_cache = sum(self.counts)
        else:
            # Fallback: try to sum numerical attributes present in the instance
            try:
                self._scale_cache = sum(float(v)
                                       for v in vars(self).values()
                                       if isinstance(v, (int, float)))
            except Exception:
                self._scale_cache = 0.0

    if other is None:
        return self._scale_cache

    # Rescaling requested
    if not isinstance(other, (int, float)):
        raise TypeError("other must be None or a numeric value")

    if self._scale_cache == 0:
        raise LenaValueError("cannot rescale histogram with zero scale")

    factor = other / self._scale_cache

    # Apply the scaling factor to the underlying bin counts
    if hasattr(self, "bins"):
        self.bins = [c * factor for c in self.bins]
    elif hasattr(self, "counts"):
        self.counts = [c * factor for c in self.counts]
    else:
        # If no known container, attempt to scale numeric attributes
        for key, val in vars(self).items():
            if isinstance(val, (int, float)):
                setattr(self, key, val * factor)

    # Update the cached scale to the new value
    self._scale_cache = other
    return self
