            if current_scale is None:
                current_scale = _compute_total()
            if current_scale == 0.0:
                raise LenaValueError("Cannot rescale a histogram with zero scale")

            # Compute scale ratio
            ratio = other / current_scale

            # Adjust underlying histogram counts to new scale
            if hasattr(self, 'values'):
                self.values = [int(round(v * ratio)) for v in self.values]
            elif hasattr(self, 'counts'):
                self.counts = [int(round(v * ratio)) for v in self.counts]
            elif isinstance(self, dict):
