def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Basic validation of inputs
    if not hasattr(hist, "bins"):
        raise TypeError("hist must have a 'bins' attribute representing histogram bins")
    if make_value is not None and not callable(make_value):
        raise TypeError("make_value must be None or a callable")

    # Choose scale
    if scale is True:
        # Assume histogram has a 'scale' attribute
        scale = getattr(hist, "scale", None)
    elif scale is not None and not isinstance(scale, (int, float, str)):
        raise TypeError("scale must be None, True, or a numeric/string value")

    # Prepare list of points
    points = []
    # Determine dimensionality based on first value
    first_bin = next(iter(hist.bins), None)
    if first_bin is None:
        # Empty histogram; return an empty graph
        # Assume graph has constructor accepting field_names and scale, and points list
        return Graph(field_names=field_names, scale=scale, points=points)

    # Helper to extract coordinate
    def _get_coord(bin_obj):
        if get_coordinate == "left":
            return getattr(bin_obj, "left")
        if get_coordinate == "right":
            return getattr(bin_obj, "right")
        if get_coordinate == "middle":
            left = getattr(bin_obj, "left")
            right = getattr(bin_obj, "right")
            return (left + right) / 2
        raise ValueError(f"Invalid get_coordinate: {get_coordinate!r}")

    # Use first bin to deduce shape of values
    bin_content = getattr(first_bin, "content")
    if make_value is None:
        val = bin_content
    else:
        val = make_value(bin_content)

    # Determine expected dimension
    if isinstance(val, (list, tuple)):
        expected_dim = len(val)
    else:
        expected_dim = 1

    if len(field_names) < 2:
        raise ValueError("field_names must contain at least two names (x and y)")
    if len(field_names) != expected_dim + 1:
        raise ValueError(
            f"Number of field_names ({len(field_names)}) does not match "
            f"expected dimension ({expected_dim + 1})"
        )

    # Build points from all bins
    for bin_obj in hist.bins:
        # Extract coordinate
        try:
            x_val = _get_coord(bin_obj)
        except AttributeError as exc:
            raise AttributeError(
                f"Histogram bin object {bin_obj!r} lacks required attribute for get_coordinate"
            ) from exc

        # Extract value(s)
        content = getattr(bin_obj, "content")
        if make_value is None:
            v = content
        else:
            v = make_value(content)

        # Create a mapping for this point
        point = {field_names[0]: x_val}
        if isinstance(v, (list, tuple)):
            for name, val_i in zip(field_names[1:], v):
                point[name] = val_i
        else:
            point[field_names[1]] = v

        points.append(point)

    # Construct and return the graph
    try:
        graph = Graph(field_names=field_names, scale=scale, points=points)
    except Exception as exc:
        # Fallback: try manual creation if Graph constructor differs
        graph = Graph()
        graph.field_names = field_names
        graph.scale = scale
        graph.points = points
        # If construction still fails, re-raise
        if not hasattr(graph, "points"):
            raise RuntimeError("Failed to create graph from histogram") from exc

    return graph<|return|>

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # determine iterable of bins
    if hasattr(hist, 'bins'):  # common attribute name
        bins = list(hist.bins)
    elif hasattr(hist, '__iter__'):
        bins = list(hist)
    else:
        raise TypeError("hist must be iterable or have a 'bins' attribute")

    if make_value is None:
        make_value = lambda bin_: bin_

    # function to extract coordinate
    def get_coord(bin_):
        # try direct attribute first
        if hasattr(bin_, get_coordinate):
            return getattr(bin_, get_coordinate)
        # fallback to common names
        if get_coordinate == "left":
            for attr in ("left_edge", "lower_edge", "left"):
                if hasattr(bin_, attr):
                    return getattr(bin_, attr)
        elif get_coordinate == "right":
            for attr in ("right_edge", "upper_edge", "right"):
                if hasattr(bin_, attr):
                    return getattr(bin_, attr)
        elif get_coordinate == "middle":
            # try infer from left and right
            left = None
            right = None
            for attr in ("left_edge", "lower_edge", "left"):
                if hasattr(bin_, attr):
                    left = getattr(bin_, attr)
                    break
            for attr in ("right_edge", "upper_edge", "right"):
                if hasattr(bin_, attr):
                    right = getattr(bin_, attr)
                    break
            if left is not None and right is not None:
                return (left + right) / 2.0
            # if bin is iterable with two elements
            if hasattr(bin_, '__len__') and len(bin_) >= 2:
                return float((bin_[0] + bin_[1]) / 2)
        raise ValueError(f"cannot obtain coordinate '{get_coordinate}' from bin: {bin_}")

    result = []

    # prepare graph output format (list of tuples)
    x_name = field_names[0]
    y_names = list(field_names[1:])

    for bin_ in bins:
        try:
            x_val = get_coord(bin_)
        except Exception as e:
            raise ValueError(f"error getting coordinate from bin: {e}") from e

        try:
            y_val = make_value(bin_)
        except Exception as e:
            raise ValueError(f"error applying make_value to bin: {e}") from e

        if isinstance(y_val, (list, tuple)):
            if len(y_val) != len(y_names):
                raise ValueError(
                    f"make_value returned {len(y_val)} values but field_names contain "
                    f"{len(y_names)} names"
                )
            point = (x_val,) + tuple(y_val)
        else:
            if len(y_names) != 1:
                raise ValueError(
                    f"make_value returned scalar but field_names expects "
                    f"{len(y_names)} values"
                )
            point = (x_val, y_val)

        result.append(point)

    # attach scale info if requested
    graph = {"points": result, "field_names": field_names}
    if scale is True:
        if hasattr(hist, "scale"):
            graph["scale"] = getattr(hist, "scale")
        else:
            graph["scale"] = None
    elif scale is not None:
        graph["scale"] = scale

    return graph<|return|>

def _verify(iface, candidate, tentative=False, vtype=None):
    """Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.
    """
    errors = []

    # 1. Check interface declaration
    if not tentative:
        try:
            declared = iface.providedBy(candidate)
        except Exception:
            declared = False
        if not declared:
            errors.append(
                f"{candidate!r} does not claim to provide {iface.__name__}"
            )

    # 2. Check required methods
    try:
        methods = iface.methods
    except Exception:
        # Fallback for older interface versions
        methods = getattr(iface, 'methods', {})
    for name in methods:
        if not hasattr(candidate, name):
            errors.append(f"Missing method {name!r}")
        else:
            attr = getattr(candidate, name)
            if not callable(attr):
                errors.append(f"{name!r} is not callable")

    # 3. Check required attributes
    try:
        attributes = iface.attributes
    except Exception:
        attributes = getattr(iface, 'attributes', {})
    for name in attributes:
        if not hasattr(candidate, name):
            errors.append(f"Missing attribute {name!r}")

    # 4. Raise accumulated errors or return True
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        raise Invalid("\n".join(errors))

    return True<|return|>

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    # Validate that iface is a class (or type)
    if not isinstance(iface, type):
        raise TypeError("iface must be a class/type")

    # Determine the candidate's class
    if isinstance(candidate, type):
        cand_cls = candidate
    else:
        # If candidate is an instance, get its actual class
        try:
            cand_cls = candidate.__class__
        except AttributeError:
            raise TypeError("candidate must be a class or an object with a __class__ attribute")

    # Quick subclass check (works for concrete subclasses)
    try:
        if issubclass(cand_cls, iface):
            return True
    except Exception:
        # issubclass may raise TypeError if cand_cls is not a class; ignore here
        pass

    # Gather attributes/methods defined on the interface
    # Use dir() to get all names, ignoring dunder ones
    iface_names = [n for n in dir(iface) if not (n.startswith('__') and n.endswith('__'))]

    # Check presence of each attribute/method on candidate class
    missing = []
    for name in iface_names:
        try:
            if not hasattr(cand_cls, name):
                missing.append(name)
        except Exception:
            missing.append(name)

    if missing:
        if tentative:
            return False
        else:
            missing_str = ", ".join(missing)
            raise ValueError(f"Candidate {cand_cls.__name__} does not provide required interface '{iface.__name__}'. Missing members: {missing_str}")

    return True<|return|>

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    # Allow checking both classes and instances; raise or return False if not satisfactory
    try:
        if isinstance(candidate, type):
            # candidate is a class or type, check subclass relationship
            if not issubclass(candidate, iface):
                raise TypeError(f"{candidate.__name__} does not provide interface {iface.__name__}")
        else:
            # candidate is an instance, check instance relationship
            if not isinstance(candidate, iface):
                raise TypeError(f"Instance of type {type(candidate).__name__} does not provide interface {iface.__name__}")
    except Exception as exc:
        if tentative:
            return False
        raise
    return True<|return|>

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    import inspect

    # Basic sanity checks
    if iface is None:
        raise ValueError("Interface argument 'iface' cannot be None.")
    if candidate is None:
        raise ValueError("Candidate argument 'candidate' cannot be None.")

    try:
        # If iface is a class/type, use isinstance/issubclass logic
        if isinstance(iface, type):
            if isinstance(candidate, type):
                result = issubclass(candidate, iface)
            else:
                result = isinstance(candidate, iface)
            return result

        # Otherwise, treat iface as a duck-typing descriptor
        # Determine the set of required attributes
        attrs = getattr(iface, "__abstractmethods__", None)
        if attrs is None:
            # Grab callables defined on the iface that are not private
            attrs = [name for name, val in inspect.getmembers(iface, predicate=callable)
                     if not name.startswith("_")]
        # Verify each required attribute is present in candidate
        for name in attrs:
            if not hasattr(candidate, name):
                if tentative:
                    return False
                raise AttributeError(
                    f"Candidate {candidate!r} missing required attribute '{name}' for interface."
                )
            # If the interface attribute is a callable, the candidate's should also be callable
            if callable(getattr(iface, name, None)):
                if not callable(getattr(candidate, name)):
                    if tentative:
                        return False
                    raise TypeError(
                        f"Attribute '{name}' of candidate is not callable as required by interface."
                    )

        return True

    except Exception as exc:
        if tentative:
            return False
        raise
