def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Gather all metaclasses from the supplied bases
    metaclasses = []
    for base in bases:
        m = type(base)
        if m not in metaclasses:
            metaclasses.append(m)

    # If an explicit metaclass was supplied, add it to the list
    if explicit_mc is not None:
        if explicit_mc not in metaclasses:
            metaclasses.append(explicit_mc)

    # If no metaclasses were found, default to the normal type
    if not metaclasses:
        return type

    # Find the most-derived metaclass that is a subclass of all others.
    # This algorithm follows Python's metaclass resolution rules.
