    # native ISO format (which includes the offset).
    if dt.tzinfo is None or dt.tzinfo.utcoffset(dt) is None:
        return dt.strftime("%Y-%m-%dT%H:%M:%SZ")
    return dt.isoformat()<|return|>

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    # Accept both datetime and date objects
    try:
        if hasattr(dt, "tzinfo"):
            # datetime instance
            if isinstance(dt.tzinfo, type(None)):
                # naive datetime; treat as UTC
                dt_utc = dt.replace(tzinfo=timezone.utc)
            else:
                dt_utc = dt.astimezone(timezone.utc)
            return dt_utc.strftime("%Y-%m-%dT%H:%M:%SZ")
        # If dt has no tzinfo attribute, treat as a date
        elif hasattr(dt, "year"):
            return dt.strftime("%Y-%m-%d")
        else:
            raise ValueError
    except Exception as exc:
        raise ValueError("format_dt expects a datetime or date instance") from exc<|return|>

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not isinstance(text, str):
        raise TypeError("Input must be a string")
    import re
    try:
        url_pattern = r'(?P<url>(https?://|www\.)[^\s<]+)'
        def _repl(match):
            url = match.group('url')
            href = url if url.startswith(('http://', 'https://')) else 'http://' + url
            return f'<a href="{href}" target="_blank" rel="nofollow">{url}</a>'
        return re.sub(url_pattern, _repl, text)
    except re.error as e:
        # If the regex fails for any reason, return the original text unmodified
        return text<|return|>

