def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        import requests
    except ImportError as e:
        raise ImportError("The 'requests' library is required to fetch content types.") from e

    try:
        # Perform a HEAD request to get headers without downloading the body
        response = requests.head(url, allow_redirects=True, timeout=10, verify=False)
        # Return the Content-Type header if present; otherwise, return None
        return response.headers.get('Content-Type')
    except requests.exceptions.RequestException:
        # Any request-related error (connection issues, timeout, invalid URL, etc.) results in None
        return None
