def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    children_by_tag = {}
    if node is None:
        return children_by_tag
    # Support ElementTree, lxml, BeautifulSoup, and simple iterables of children
    try:
        for child in node:
            # Skip non-element nodes like text or comments
            tag = None
            if hasattr(child, "tag"):          # lxml or ElementTree
                tag = child.tag
            elif hasattr(child, "nodeName"):   # some DOM-like APIs
                tag = child.nodeName
            elif hasattr(child, "name"):       # BeautifulSoup tag
                tag = child.name
            if tag is None:
                continue
            # In case of duplicate tags, keep the first occurrence
            if tag not in children_by_tag:
                children_by_tag[tag] = child
    except TypeError:
        # The node is not iterable; try getchildren() if available
        if hasattr(node, "getchildren"):
            for child in node.getchildren():
                tag = getattr(child, "tag", None)
                if tag is None:
                    continue
                if tag not in children_by_tag:
                    children_by_tag[tag] = child
    return children_by_tag
