def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    """Ensure that sender and entity handles match.

    Basically we've already verified the sender is who they say when receiving the payload. However, the sender might
    be trying to set another author in the payload itself, since Diaspora has the sender in both the payload headers
    AND the object. We must ensure they're the same.
    """
    if sender_handle is None or entity_handle is None:
        raise ValueError("Both sender_handle and entity_handle must be provided and non-None.")
    if not isinstance(sender_handle, str):
        raise TypeError(f"sender_handle must be a string, got {type(sender_handle).__name__}")
    if not isinstance(entity_handle, str):
        raise TypeError(f"entity_handle must be a string, got {type(entity_handle).__name__}")
    if sender_handle != entity_handle:
        raise ValueError(f"Sender handle '{sender_handle}' does not match entity handle '{entity_handle}'.")
    return True<|return|>

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    from urllib.parse import urlparse, urljoin

    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if document_path is None:
        document_path = ".well-known/nodeinfo"

    # Parse and validate the base URL
    parsed = urlparse(url)
    if not parsed.scheme or not parsed.netloc:
        raise ValueError(f"Invalid base URL: {url!r}")

    # Construct the full document URL and extract hostname for the software name
    base_url = f"{parsed.scheme}://{parsed.netloc}"
    hostname = parsed.hostname or parsed.netloc
    document_url = urljoin(base_url.rstrip("/") + "/", document_path.lstrip("/"))

    # Build the NodeInfo JSON structure
    nodeinfo = {
        "nodes": [
            {
                "protocols": ["activitypub"],
                "software": {
                    "name": hostname,
                    "version": "0.1"
                }
            }
        ],
        "version": "0.2"
    }

    return {"url": document_url, "document": nodeinfo}<|return|>

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Basic validation of the URL
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    if "://" not in url:
        raise ValueError("url must contain a scheme (e.g., http:// or https://)")
    scheme, rest = url.split("://", 1)
    if scheme.lower() not in ("http", "https") or not rest:
        raise ValueError("url must be a valid http/https URL")

    base = url.rstrip("/")
    path = document_path if document_path is not None else "/.well-known/nodeinfo"
    if not path.startswith("/"):
        path = "/" + path
    full_url = base + path

    # Construct a minimal NodeInfo .well-known document according to the spec
    try:
        node_info = {
            "error": None,
            "version": "1.1",
            "nodes": [
                {
                    "name": "NodeInfo",
                    "description": "NodeInfo server",
                    "type": "hub",
                    "url": full_url,
                    "fields": [
                        {
                            "name": "id",
                            "type": "string",
                            "description": "Node's unique identifier",
                        }
                    ],
                }
            ],
        }
    except Exception as exc:
        raise RuntimeError("Failed to build NodeInfo document") from exc

    return node_info<|return|>

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Basic validation of the base URL
    if not isinstance(url, str) or not url:
        raise ValueError("`url` must be a non-empty string.")
    if not (url.startswith("http://") or url.startswith("https://")):
        raise ValueError("`url` must begin with 'http://' or 'https://'.")

    base = url.rstrip("/")  # remove trailing slash if present

    # Determine the NodeInfo document path
    if document_path:
        if not isinstance(document_path, str):
            raise ValueError("`document_path` must be a string if provided.")
        # Ensure the path starts with a slash
        if not document_path.startswith("/"):
            document_path = "/" + document_path
        nodeinfo_href = base + document_path
    else:
        # Default path for NodeInfo 2.0 as per the spec
        nodeinfo_href = f"{base}/.well-known/nodeinfo/2.0"

    # Build the .well-known NodeInfo manifest
    result = {
        "nodes": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": nodeinfo_href,
            }
        ],
        "links": [
            {"rel": "self", "href": f"{base}/.well-known/nodeinfo"},
        ],
    }

    return result<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree as ET

    if not isinstance(document, str) or not document.strip():
        raise ValueError("Document must be a non-empty string")

    # First attempt to parse as JSON
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            return data
    except json.JSONDecodeError:
        pass

    # Fallback to XRD (XML) parsing
    try:
        root = ET.fromstring(document)
    except ET.ParseError as exc:
        raise ValueError("Unable to parse webfinger document as JSON or XRD XML") from exc

    result: Dict[str, object] = {}

    # Extract subject
    subject_elem = None
    for elem in root.iter():
        if elem.tag.lower().endswith("subject"):
            subject_elem = elem
            break
    result["subject"] = subject_elem.text if subject_elem is not None else None

    # Extract links
    links = []
    for elem in root.iter():
        if elem.tag.lower().endswith("link"):
            link: Dict[str, object] = {
                "rel": elem.attrib.get("rel"),
                "href": elem.attrib.get("href"),
            }
            # Optional attributes
            if "type" in elem.attrib:
                link["type"] = elem.attrib["type"]
            if "title" in elem.attrib:
                link["title"] = elem.attrib["title"]
            links.append(link)
    result["links"] = links

    return result<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # First try to parse as JSON
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            return data
        else:
            raise ValueError("JSON does not represent a dictionary.")
    except json.JSONDecodeError:
        # If JSON parsing fails, try XRD (XML)
        pass
    except Exception as exc:
        raise ValueError(f"Error parsing JSON: {exc}") from exc

    try:
        root = ET.fromstring(document)
    except ET.ParseError as exc:
        raise ValueError("Document is neither valid JSON nor valid XRD XML.") from exc

    subject = None
    properties: Dict[str, str] = {}

    for elem in root.iter():
        tag = elem.tag
        # Strip namespace if present
        if '}' in tag:
            tag = tag.split('}', 1)[1]
        if tag == 'Subject':
            subject = elem.text
        elif tag == 'Property':
            uri = elem.attrib.get('uri')
            if uri:
                properties[uri] = elem.text or ''

    if subject is None:
        raise ValueError("No Subject element found in XRD document.")

    return {
        'subject': subject,
        'properties': properties
    }<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    if not isinstance(document, str):
        raise TypeError("document must be a string")

    doc_str = document.strip()
    if not doc_str:
        # empty input
        return {}

    # Attempt JSON parsing first
    try:
        parsed_json = json.loads(doc_str)
        if not isinstance(parsed_json, dict):
            raise ValueError("JSON webfinger must be an object at the top level")
        return parsed_json
    except json.JSONDecodeError:
        # Not JSON, fall back to XRD (XML)
        pass

    # Attempt XRD parsing
    try:
        root = ET.fromstring(doc_str)
    except ET.ParseError as e:
        raise ValueError(f"Failed to parse webfinger document as JSON or XML: {e}")

    # Helper to extract text from element or None
    def _text(elem):
        return elem.text.strip() if elem is not None and elem.text is not None else None

    result: Dict = {}
    # Namespaces handling: XRD may have default namespace, strip it
    ns = {}
    if root.tag.startswith("{"):
        # extract namespace
        ns_uri = root.tag[root.tag.find("{")+1:root.tag.find("}")]
        ns = {"xrd": ns_uri}

    def _find(tag, namespace=""):
        if namespace:
            return root.find(f".//xrd:{tag}", ns)
        return root.find(f".//{tag}")

    # Subject
    subject = _find("Subject") or _find("subject")
    if subject is not None:
        result["subject"] = _text(subject)

    # Aliases - may be multiple <Alias> elements
    aliases = []
    for alias_elem in root.findall(".//xrd:Alias", ns) or root.findall(".//Alias"):
        alias_text = _text(alias_elem)
        if alias_text:
            aliases.append(alias_text)
    if aliases:
        result["aliases"] = aliases

    # Links
    links = []
    for link in root.findall(".//xrd:Link", ns) or root.findall(".//Link"):
        link_dict: Dict = {}
        for attr in ["rel", "type", "href", "template"]:
            val = link.get(attr)
            if val is not None:
                link_dict[attr] = val
        # If link has <Properties> or <Property> children, gather them
        props = {}
        for prop in link.findall(".//xrd:Property", ns) or link.findall(".//Property"):
            key = prop.get("name")
            value = _text(prop)
            if key and value:
                props[key] = value
        if props:
            link_dict["properties"] = props
        links.append(link_dict)
    if links:
        result["links"] = links

    if not result:
        raise ValueError("Webfinger document could not be parsed into a recognizable format")

    return result<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET
    from typing import Any

    result: Dict[str, Any] = {"subject": None, "aliases": [], "links": []}

    doc = document.strip()
    if not doc:
        return result

    # Try to parse as JSON first
    try:
        data = json.loads(doc)
    except Exception:
        # Not JSON, fall back to XRD XML parsing
        try:
            root = ET.fromstring(doc)
            # XRD namespace
            ns = {"xrd": "http://eclipse.org/xrd/1.0"}
            # Subject
            subject_el = root.find("xrd:Subject", ns)
            if subject_el is not None and subject_el.text:
                result["subject"] = subject_el.text.strip()
            # Aliases
            for alias_el in root.findall("xrd:Alias", ns):
                if alias_el.text:
                    result["aliases"].append(alias_el.text.strip())
            # Links
            for link_el in root.findall("xrd:Link", ns):
                link: Dict[str, str] = {}
                rel_el = link_el.find("xrd:Rel", ns)
                href_el = link_el.find("xrd:Href", ns)
                if rel_el is not None and rel_el.text:
                    link["rel"] = rel_el.text.strip()
                if href_el is not None and href_el.text:
                    link["href"] = href_el.text.strip()
                if link:
                    result["links"].append(link)
            return result
        except ET.ParseError as exc:
            raise ValueError(f"Unable to parse webfinger as XRD XML: {exc}") from exc
    # Successfully parsed as JSON
    if isinstance(data, dict):
        # Subject
        if "subject" in data and isinstance(data["subject"], str):
            result["subject"] = data["subject"]
        # Aliases
        if "aliases" in data:
            if isinstance(data["aliases"], list):
                result["aliases"] = [str(a) for a in data["aliases"] if isinstance(a, str)]
            else:
                # Some implementations use a single string
                result["aliases"] = [str(data["aliases"])]
        # Links
        if "links" in data:
            links = data["links"]
            if isinstance(links, list):
                for l in links:
                    if isinstance(l, dict):
                        rel = l.get("rel") or l.get("rel_url") or l.get("type")
                        href = l.get("href") or l.get("uri")
                        if rel and href:
                            result["links"].append({
                                "rel": str(rel),
                                "href": str(href),
                            })
            elif isinstance(links, dict):
                rel = links.get("rel") or links.get("rel_url") or links.get("type")
                href = links.get("href") or links.get("uri")
                if rel and href:
                    result["links"].append({
                        "rel": str(rel),
                        "href": str(href),
                    })
    else:
        raise ValueError("Parsed JSON is not an object as expected for webfinger")

    return result
