def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    # Sanitize handle: strip 'acct:' prefix if present, ensure it contains '@'
    try:
        if handle.lower().startswith('acct:'):
            acct = handle[5:]
        else:
            acct = handle
        user_part, host_part = acct.split('@', 1)
        # Build the webfinger URL
        url = f"https://{host_part}/.well-known/webfinger?resource=acct:{acct}"
    except Exception:
        # Invalid handle format
        return None

    # Try to fetch the document using urllib.request
    try:
        import urllib.request
        import urllib.error

        with urllib.request.urlopen(url, timeout=10) as resp:
            if resp.status != 200:
                return None
            # Read and decode the response
            content_bytes = resp.read()
            # Prefer UTF-8, fallback to ISO-8859-1
            try:
                content = content_bytes.decode('utf-8')
            except UnicodeDecodeError:
                content = content_bytes.decode('iso-8859-1')
            return content
