def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        if not handle:
            return None
        handle = handle.strip()
        # Ensure the account URI is in the form acct:local@domain
        if not handle.lower().startswith("acct:"):
            handle = f"acct:{handle}"
        try:
            _, domain = handle.split("@", 1)
        except ValueError:
            return None
        # Encode the resource parameter
        import urllib.parse
        encoded_resource = urllib.parse.quote(handle, safe='')
        url = f"https://{domain}/.well-known/webfinger?resource={encoded_resource}"
        import urllib.request
        req = urllib.request.Request(
            url,
            headers={"User-Agent": "Mozilla/5.0 (Python WebFinger Client)"},
        )
        with urllib.request.urlopen(req, timeout=5) as resp:
            if resp.status != 200:
                return None
            try:
                data = resp.read()
                return data.decode("utf-8", errors="replace")
            except Exception:
                return None
    except Exception:
        return None<|return|>

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    from typing import Optional
    import urllib.request
    import urllib.parse

    if not isinstance(handle, str):
        raise TypeError("handle must be a string")

    # Basic validation: handle should contain '@'
    if '@' not in handle:
        return None

    account_user, domain = handle.split('@', 1)
    resource = urllib.parse.quote(f'acct:{account_user}@{domain}', safe='')
    url = f'https://{domain}/.well-known/webfinger?resource={resource}'

    try:
        headers = {'Accept': 'application/jrd+json,text/plain'}
        request = urllib.request.Request(url, headers=headers)
        with urllib.request.urlopen(request, timeout=10) as response:
            if response.status != 200:
