def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    if not isinstance(host, str) or not host.strip():
        raise TypeError("host must be a non-empty string")

    try:
        import urllib.request as _urllib_request
        import urllib.error as _urllib_error
        import xml.etree.ElementTree as _ET
    except Exception as e:
        raise RuntimeError(f"Failed to import required modules: {e}")

    url = f"https://{host.strip()}/.well-known/host-meta"

    try:
        with _urllib_request.urlopen(url, timeout=10) as resp:
            data = resp.read()
    except _urllib_error.HTTPError as e:
        if e.code == 404:
            raise ValueError(f"Host-meta not found at {url}")
        else:
            raise
    except _urllib_error.URLError as e:
        raise ValueError(f"Could not retrieve host-meta from {host}: {e.reason}")

    try:
        _ET.fromstring(data)
    except _ET.ParseError as e:
        raise ValueError(f"Failed to parse host-meta XML: {e}")

    # Attempt to create an XRD instance if the XRD module is available.
    # If unavailable or any error occurs, fallback to returning the parsed XML Element.
    try:
        from xrd import XRD
        return XRD.fromstring(data)
    except Exception:
        # In the absence of a proper XRD implementation, return the raw XML root.
        return _ET.fromstring(data)<|return|>

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    import urllib.request
    import urllib.error
    import urllib.parse
    from xml.etree import ElementTree as ET

    # Ensure host includes scheme and path to the host-meta file
    try:
        parsed = urllib.parse.urlparse(host if '://' in host else f'http://{host}')
        if not parsed.path:
            parsed = parsed._replace(path='/.well-known/host-meta')
        url = parsed.geturl()
    except Exception as exc:
        raise ValueError(f"Invalid host specification: {host}") from exc

    # Prepare the HTTP request with the necessary Accept header
    req = urllib.request.Request(url, headers={'Accept': 'application/xrd+xml'})

    # Attempt to fetch the host-meta document
    try:
        with urllib.request.urlopen(req, timeout=10) as resp:
            if resp.status != 200:
                raise ValueError(f"HTTP {resp.status} when accessing {url}")
            raw_data = resp.read()
    except urllib.error.URLError as exc:
        # If http failed, try https as a fallback
        if parsed.scheme == 'http':
            try:
                https_url = parsed._replace(scheme='https').geturl()
                req = urllib.request.Request(https_url, headers={'Accept': 'application/xrd+xml'})
                with urllib.request.urlopen(req, timeout=10) as resp:
                    if resp.status != 200:
                        raise ValueError(f"HTTP {resp.status} when accessing {https_url}")
                    raw_data = resp.read()
            except urllib.error.URLError as exc2:
                raise ConnectionError(f"Unable to retrieve host-meta from {host}") from exc2
        else:
            raise ConnectionError(f"Unable to retrieve host-meta from {host}") from exc

    # Parse the returned XML into an ElementTree Element
    try:
        xrd_element = ET.fromstring(raw_data)
    except ET.ParseError as exc:
        raise ValueError(f"Could not parse host-meta XML from {host}") from exc

    return xrd_element<|return|>

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    if not host or not isinstance(host, str):
        raise ValueError("Host must be a non-empty string")

    # Remove any scheme that might be present
    host = host.lower()
    for prefix in ("http://", "https://"):
        if host.startswith(prefix):
            host = host[len(prefix):]

    # Known location of host-meta for Diaspora
    paths = ["/.well-known/host-meta", "/.well-known/host-meta.json"]
    schemes = ("https://", "http://")

    # Try each scheme+path combination
    for scheme in schemes:
        for path in paths:
            url = scheme + host + path
            try:
                resp = requests.get(
                    url,
                    headers={"Accept": "application/xrd+xml, application/json"},
                    timeout=5,
                    allow_redirects=True,
                )
            except requests.RequestException as exc:
                # If an exception occurs, move on to next URL
                continue

            if resp.status_code != 200:
                continue

            content_type = resp.headers.get("Content-Type", "").split(";")[0].strip()
            if content_type.startswith("application/xrd+xml"):
                try:
                    # Assume XRD.can_parse_xml or similar method exists
                    if hasattr(XRD, "from_xml"):
                        return XRD.from_xml(resp.text)
                    else:
                        # Fallback: initialize XRD with XML string directly
                        return XRD(resp.text)
                except Exception as exc:
                    # If parsing fails, continue searching
                    continue
            elif content_type == "application/json":
                try:
                    # Many host-meta documents are JSON wrapped
                    if hasattr(XRD, "from_json"):
                        return XRD.from_json(resp.json())
                except Exception:
                    continue

    # If none succeeded, raise an informative error
    raise ValueError(f"Unable to retrieve a valid host-meta from {host}")
<|return|>

