def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    # Basic input validation
    if not isinstance(url, str):
        raise TypeError(f"url must be a str, got {type(url).__name__}")
    if not isinstance(method, str):
        raise TypeError(f"method must be a str, got {type(method).__name__}")
    if not isinstance(timeout, (int, float)):
        raise TypeError(f"timeout must be a number, got {type(timeout).__name__}")

    # Normalize method to lower case for compatibility
    method_name = method.lower()

    try:
        # Choose appropriate function from requests
        import requests
        if method_name == "post":
            response = requests.post(url, data=data, timeout=timeout, *args, **kwargs)
        elif method_name == "get":
            response = requests.get(url, data=data, timeout=timeout, *args, **kwargs)
        else:
            # Fallback to generic request if other method is provided
            response = requests.request(method_name, url, data=data, timeout=timeout, *args, **kwargs)

        return (response.status_code, None)

    except Exception as exc:
        # Catch all exceptions (including RequestException) and return None for status
        return (None, exc)<|return|>

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError("`dic` must be a dictionary")

    # Resolve key chain: allow key to itself be a sequence of keys
    if keys:
        key_chain = [key] + list(keys)
    else:
        if isinstance(key, (list, tuple)):
            key_chain = list(key)
        else:
            key_chain = [key]

    if not key_chain:
        raise ValueError("At least one key must be specified")

    parent = dic
    for k in key_chain[:-1]:
        if not isinstance(k, (str, int, float, bytes, bool, tuple, frozenset)):
            raise TypeError(f"Unsupported key type: {type(k)}")
        if k not in parent:
            parent[k] = {}
        elif not isinstance(parent[k], dict):
            raise ValueError(f"Conflict with key '{k}': existing value is not a dict")
        parent = parent[k]

    last_key = key_chain[-1]
    if not isinstance(last_key, (str, int, float, bytes, bool, tuple, frozenset)):
        raise TypeError(f"Unsupported key type: {type(last_key)}")
    parent[last_key] = val
    return None<|return|>

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    # Validate inputs
    if settings_dirs is None:
        raise ValueError("settings_dirs must be provided")
    # Ensure we have an iterable of strings (but not a string itself)
    try:
        iter(settings_dirs)
        if isinstance(settings_dirs, (str, bytes)):
            raise TypeError("'settings_dirs' cannot be a string")
    except TypeError:
        raise TypeError("'settings_dirs' must be an iterable of directory paths")
    if spec_option is not None and not isinstance(spec_option, (str, bytes)):
        raise TypeError("'spec_option' must be a string or None")
    result = []
    for dir_path in settings_dirs:
        if not isinstance(dir_path, (str, bytes)):
            # Skip non-string directory specifications
            continue
        try:
            if not os.path.isdir(dir_path):
                # Skip paths that are not directories
                continue
            for entry in os.listdir(dir_path):
                if not os.path.isfile(os.path.join(dir_path, entry)):
                    continue
                if spec_option is None or spec_option in entry:
                    result.append(entry)
        except (OSError, PermissionError):
            # Skip directories that cannot be accessed
            continue
    return result<|return|>

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type

    Parameters
    ----------
    settings_dirs : iterable of str
        Directory paths to search for files.
    spec_option : str or None
        File extension or glob pattern to filter the files.
        If ``None`` all files are returned.

    Returns
    -------
    list of str
        The list of file names that match the given specification.

    Raises
    ------
    ValueError
        If ``settings_dirs`` is not iterable or if any supplied path
        is not a directory.
    """
    import os
    import fnmatch

    if settings_dirs is None:
        raise ValueError("settings_dirs must be an iterable of directory paths")

    file_names = []

    for dir_path in settings_dirs:
        # Basic type check and existence check
        if not isinstance(dir_path, str):
            raise ValueError(f"Directory path must be a string, got {type(dir_path).__name__}")

        if not os.path.isdir(dir_path):
            raise ValueError(f"Directory does not exist: {dir_path}")

        try:
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                if not os.path.isfile(full_path):
                    continue

                if spec_option is None:
                    file_names.append(entry)
                else:
                    # If spec_option is an extension (starts with a dot)
                    if spec_option.startswith("."):
                        if entry.lower().endswith(spec_option.lower()):
                            file_names.append(entry)
                    else:
                        # Treat spec_option as a glob pattern
                        if fnmatch.fnmatch(entry, spec_option):
                            file_names.append(entry)
        except OSError as exc:
            # Catch directory read errors and re-raise with context
            raise ValueError(f"Error accessing directory {dir_path}: {exc}") from exc

    return file_names<|return|>

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    import fnmatch

    file_names = []

    # Normalize the input to a list
    if isinstance(settings_dirs, str):
        dirs = [settings_dirs]
    elif isinstance(settings_dirs, (list, tuple)):
        dirs = list(settings_dirs)
    else:
        raise TypeError("settings_dirs must be a string or a list/tuple of strings.")

    # Ensure the pattern is a string; default to wildcard
    if not isinstance(spec_option, (str, type(None))):
        raise TypeError("spec_option must be a string or None.")
    pattern = spec_option if spec_option is not None else "*"

    for d in dirs:
        if not isinstance(d, str):
            raise TypeError("Each directory path must be a string.")
        if not os.path.isdir(d):
            # Skip non-existent or invalid directories
            continue

        try:
            for entry in os.listdir(d):
                if fnmatch.fnmatch(entry, pattern):
                    file_names.append(os.path.join(d, entry))
        except OSError:
            # Skip directories that cannot be accessed
            continue

    return file_names<|return|>

