def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files."""
        import os
        import json
        try:
            import yaml
        except Exception:
            yaml = None

        def _resolve_dict(d, base_dir):
            if isinstance(d, dict):
                if d.get("include") is not None:
                    inc = d.pop("include")
                    if isinstance(inc, str):
                        inc_paths = [inc]
                    elif isinstance(inc, list):
                        inc_paths = inc
                    else:
                        return d

                    for path in inc_paths:
                        abs_path = os.path.abspath(os.path.join(base_dir, path))
                        if not os.path.isfile(abs_path):
                            continue
                        try:
                            if abs_path.lower().endswith(".json"):
                                with open(abs_path, "r", encoding="utf-8") as f:
                                    inc_data = json.load(f)
                            elif yaml and abs_path.lower().endswith((".yml", ".yaml")):
                                with open(abs_path, "r", encoding="utf-8") as f:
                                    inc_data = yaml.safe_load(f)
                            else:
                                continue
                        except Exception:
                            continue

                        # Recursively resolve includes inside the imported data
                        inc_resolved = _resolve_dict(inc_data, os.path.dirname(abs_path))

                        if isinstance(inc_resolved, dict):
                            # Merge or override keys, but do not overwrite existing keys unless they are also dicts
                            for key, value in inc_resolved.items():
                                if key in d and isinstance(d[key], dict) and isinstance(value, dict):
                                    d[key] = _resolve_dict(d[key], os.path.dirname(abs_path))
                                else:
                                    d[key] = value
                # Resolve nested structures
                for k, v in list(d.items()):
                    d[k] = _resolve_dict(v, base_dir)
                return d
            elif isinstance(d, list):
                return [_resolve_dict(item, base_dir) for item in d]
            else:
                return d

        # Determine the base directory for relative includes
        base_dir = getattr(self, "spec_dir", os.getcwd())
        return _resolve_dict(parser_dict, base_dir)<|return|>

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    if not isinstance(parser_dict, dict):
        raise TypeError("parser_dict must be a dict")

    def _merge(source, target):
        for key, value in source.items():
            if isinstance(value, dict) and isinstance(target.get(key), dict):
                _merge(value, target[key])
            else:
                target[key] = value

    try:
        includes = parser_dict.pop('include', None)
        if includes is not None:
            if not isinstance(includes, dict):
                raise ValueError("'include' directive must map to a dict")
            for inc_key, inc_val in includes.items():
                if isinstance(inc_val, dict):
                    target = parser_dict.get(inc_key, {})
                    if not isinstance(target, dict):
                        target = {}
                        parser_dict[inc_key] = target
                    _merge(inc_val, target)
                else:
                    parser_dict[inc_key] = inc_val
    except Exception as exc:
        raise RuntimeError(f"Failed to resolve include groups: {exc}") from exc<|return|>

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # Use a helper to handle recursion and cycle detection
    resolved_cache = {}
    def _resolve(group_name, stack=None):
        if stack is None:
            stack = set()
        if group_name in resolved_cache:
            return resolved_cache[group_name]
        if group_name not in parser_dict:
            raise KeyError(f"Group '{group_name}' not found in parser_dict")
        if group_name in stack:
            raise ValueError(f"Circular include detected: {' -> '.join(list(stack) + [group_name])}")
        stack.add(group_name)

        group_def = parser_dict[group_name]
        # If the group definition is not a dict with an 'include' key, nothing to resolve
        if not isinstance(group_def, dict) or 'include' not in group_def:
            resolved_cache[group_name] = group_def
            stack.remove(group_name)
            return group_def

        # Begin resolving includes
        includes = group_def.pop('include')
        if not isinstance(includes, (list, tuple)):
            includes = [includes]

        merged = {}
        for inc_name in includes:
            inc_def = _resolve(inc_name, stack)
            if isinstance(inc_def, dict):
                # Merge dictionaries; later entries override earlier ones
                merged.update(inc_def)
            else:
                # For non-dict includes, treat as a list under a standard key
                merged.setdefault('entries', []).extend(inc_def if isinstance(inc_def, (list, tuple)) else [inc_def])

        # After processing all includes, merge the remaining keys of the current group
        for key, value in group_def.items():
            if key in merged and isinstance(merged[key], dict) and isinstance(value, dict):
                merged[key].update(value)
            else:
                merged[key] = value

        resolved_cache[group_name] = merged
        stack.remove(group_name)
        return merged

    # Resolve all top‑level groups
    for key in list(parser_dict.keys()):
        parser_dict[key] = _resolve(key)

    # No explicit return value; the parser_dict is modified in place.<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    try:
        # Pull defaults from a spec attribute if it exists and is a dict
        spec = getattr(self, "spec", None)
        if isinstance(spec, dict):
            for key, val in spec.items():
                defaults[key] = val

        # Merge with any explicit defaults defined in the __init__ signature
        init = getattr(self.__class__, "__init__", None)
        if init and hasattr(init, "__signature__"):
            try:
                import inspect

                sig = inspect.signature(init)
                for name, param in sig.parameters.items():
                    if name == "self":
                        continue
                    if name not in defaults and param.default is not inspect._empty:
                        defaults[name] = param.default
            except Exception:
                # If signature introspection fails, ignore and continue
                pass
    except Exception as ex:
        # Log or handle unexpected errors without breaking the caller
        # (Assuming a logging mechanism exists; otherwise pass silently)
        pass
    return defaults<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    # Importing here to avoid module-level import
    import inspect

    defaults = {}

    # Retrieve the spec dictionary if present; fall back to empty dict
    spec = getattr(self, "spec", {})
    if not isinstance(spec, dict):
        spec = {}

    # 1. Attempt to use constructor defaults
    try:
        init_sig = inspect.signature(self.__init__)
    except (ValueError, TypeError):
        init_sig = None

    if init_sig:
        for name, param in init_sig.parameters.items():
            if name == "self":
                continue
            if param.default is inspect.Parameter.empty:
                continue  # no default provided
            # Get current value if any
            cur_val = getattr(self, name, None)
            # If the current value matches the default, consider it unspecified
            if cur_val == param.default:
                # Prefer value from spec if provided
                if name in spec:
                    defaults[name] = spec[name]
                else:
                    defaults[name] = param.default
            else:
                # Keep whatever current value we have
                defaults[name] = cur_val

    # 2. Fill in any spec entries that are missing from the defaults
    for key, val in spec.items():
        if key not in defaults:
            # If the attribute exists and is None, treat it as unspecified
            if hasattr(self, key):
                if getattr(self, key) is None:
                    defaults[key] = val
                else:
                    defaults[key] = getattr(self, key)
            else:
                defaults[key] = val

    # 3. Post‑process: remove entries that are still None (no usable default)
    final_defaults = {k: v for k, v in defaults.items() if v is not None}

    return final_defaults
<|return|>

