    elem_key = self.__class__.__name__
    elem_spec = spec.get(elem_key, {})
    attr_defaults = elem_spec.get("attributes", {})

    # Build a dictionary of defaults to apply.
    defaults = {}
    for attr_name, default_value in attr_defaults.items():
        # If the attribute is missing or explicitly set to None, use the default.
        if getattr(self, attr_name, None) is None:
            defaults[attr_name] = default_value
