def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    # Retrieve the specification dict (may be a dict of arg -> default or arg -> dict with metadata)
    spec = getattr(self, "spec", {})
    # Retrieve any arguments that were explicitly provided by the caller
    supplied = getattr(self, "args", {})
    resolved = {}

    required_keys = set()
    # Process the specification entries
    for key, value in spec.items():
        # We allow two styles: simple default or a dict with metadata
        if isinstance(value, dict):
            # Metadata dict may contain a default and a required flag
            if value.get("required"):
                required_keys.add(key)
            if "default" in value:
                resolved[key] = value["default"]
        else:
            # Assume a simple default value
            resolved[key] = value

    # Override with supplied values
    for key, val in supplied.items():
        resolved[key] = val

    # Verify that all required keys are present
    missing = required_keys - resolved.keys()
    if missing:
        raise ValueError(f"Missing required argument(s) from spec: {', '.join(sorted(missing))}")

    return resolved<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    # Ensure the instance contains the expected 'spec' attribute
    if not hasattr(self, "spec"):
        raise AttributeError("The object does not provide a 'spec' attribute.")
    spec = self.spec

    if not isinstance(spec, dict):
        raise TypeError(f"Expected spec to be a dict, got {type(spec).__name__}.")

    # The spec may expose its arguments under a sub‑dictionary called 'args'.
    spec_args = spec.get("args", {})
    if not isinstance(spec_args, dict):
        raise TypeError(f"Expected spec['args'] to be a dict, got {type(spec_args).__name__}.")

    # Determine which argument names to consider.
    # Common patterns are an 'args' dict or an iterable of names.
    if hasattr(self, "args") and isinstance(self.args, dict):
        arg_names = list(self.args.keys())
    else:
        try:
            # Fall back to any iterable of argument names on the instance.
            arg_names = list(getattr(self, "args", []))
        except TypeError:
            arg_names = []

    defaults = {}
    for name in arg_names:
        # Skip names already set on the instance.
        existing_val = getattr(self, name, None)
        if existing_val is not None:
            continue

        # Resolve value from the spec first.
        val = spec_args.get(name)

        # If the spec didn't provide a value, look for class‑wide defaults.
        if val is None:
            val = getattr(self.__class__, "DEFAULTS", {}).get(name)

        defaults[name] = val

    return defaults<|return|>

