        if not isinstance(cli_args, dict):
            raise TypeError("cli_args must be a dictionary")
        if not isinstance(answer_file_args, dict):
            raise TypeError("answer_file_args must be a dictionary")

        # The class can define a mapping of deprecated argument names to their
        # replacement names.  If not defined, an empty mapping is used.
        deprecated_mapping = getattr(self, "_deprecated_args", {})

        # Helper to report a deprecation warning
        def _report_deprecation(source, key, new_name):
            new_part = f" (use '{new_name}')" if new_name else " (no replacement available)"
            print(f"[DEPRECATED] Argument '{key}' used in {source}{new_part}")

        # Check CLI arguments
        for key in list(cli_args.keys()):
            if key in deprecated_mapping:
                _report_deprecation("CLI", key, deprecated_mapping[key])

        # Check answer-file arguments
        for key in list(answer_file_args.keys()):
            if key in deprecated_mapping:
                _report_deprecation("answer file", key, deprecated_mapping[key])<|return|>

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    if not isinstance(cli_args, dict):
        raise TypeError("cli_args must be a dictionary")
    if not isinstance(answer_file_args, dict):
        raise TypeError("answer_file_args must be a dictionary")

    # Retrieve the set of deprecated argument names; default to empty set
    deprecated = getattr(self, "DEPRECATED_ARGS", set())
    if not isinstance(deprecated, (set, list, tuple)):
        deprecated = set()

    seen = set()
    warnings = []

    # Check CLI arguments for deprecation
    for arg in cli_args:
        if arg in deprecated and arg not in seen:
            warnings.append(f"Argument '{arg}' from CLI is deprecated and will be ignored.")
            seen.add(arg)

    # Check answer file arguments for deprecation
    for arg in answer_file_args:
        if arg in deprecated and arg not in seen:
            warnings.append(f"Argument '{arg}' from answer file is deprecated and will be ignored.")
            seen.add(arg)

    # Print any warnings
    for w in warnings:
        print(w)<|return|>

