        if min_val is None and hasattr(self, f"{name}_min"):
            min_val = getattr(self, f"{name}_min")
        if max_val is None and hasattr(self, f"{name}_max"):
            max_val = getattr(self, f"{name}_max")

        # Perform validation if we have a constraint
        if min_val is not None:
            try:
                if value < min_val:
