def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                 spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation of input arguments
    if not isinstance(subcommand, str) or not subcommand:
        raise ValueError("subcommand must be a non‑empty string")
    if not isinstance(type_name, str) or not type_name.isidentifier():
        raise ValueError("type_name must be a valid Python identifier")
    if not isinstance(option_name, str) or not option_name:
        raise ValueError("option_name must be a non‑empty string")
    if not isinstance(spec_option, dict):
        raise ValueError("spec_option must be a dictionary")

    # Define the parsing/validation logic for the complex argument
    def _parse(value):
        """
        Convert the raw string value into the desired complex type.

        The default implementation splits the string on commas and strips
        whitespace, applying optional validators and choice restrictions
        provided in spec_option.
        """
        if not isinstance(value, str):
            raise ValueError(f"Value for {option_name!s} must be a string")

        try:
            # Basic split‑by‑comma parsing
            parts = [p.strip() for p in value.split(",") if p.strip()]
            # Nothing to return if input was empty
            if not parts:
                return tuple()

            # Optional per‑part validation
            validator = spec_option.get("validator")
            if validator is not None:
                if not callable(validator):
                    raise ValueError("spec_option['validator'] must be callable")
                for part in parts:
                    if not validator(part):
                        raise ValueError(
                            f"Validation failed for {option_name!r} part: {part!r}"
                        )

            # Optional choice restriction
            choices = spec_option.get("choices")
            if choices is not None:
                if not isinstance(choices, (list, set, tuple)):
                    raise ValueError("spec_option['choices'] must be a sequence")
                for part in parts:
                    if part not in choices:
                        raise ValueError(
                            f"{option_name!r} part {part!r} not in allowed choices {choices!r}"
                        )

            return tuple(parts)

        except Exception as exc:
            # Normalise to a simple ValueError to keep the interface consistent
            raise ValueError(f"Could not parse {option_name!r}: {exc}") from exc

    # Create a lightweight object that mimics a type instance for callers
    class _ComplexArgType:
        """
        A callable type that can be used as a custom argparse type or
        any other place where the complex argument must be parsed.
        """

        __name__ = type_name
        __module__ = __name__

        def __init__(self):
            # Store the spec_option for introspection
            self.spec_option = spec_option

        def __call__(self, value):
            return _parse(value)

        def __repr__(self):
            return f"<ComplexArgType {self.__name__} for {subcommand}.{option_name}>"

    # Set a helpful docstring on the type
    _ComplexArgType.__doc__ = (
        f"Complex argument type for option {option_name!s} "
        f"of subcommand {subcommand!s}"
    )

    return _ComplexArgType()
<|return|>

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Prepare result containers
    control_args = {}
    nested_args = {}

    # Attempt to determine which keys are controller keys.
    # If the user has defined a CONTROL_KEYS set on the instance, use it.
    control_keys = getattr(self, "CONTROL_KEYS", set())
    # If CONTROL_KEYS is not defined or empty, default to typical control prefixes.
    if not control_keys:
        # A conservative default list; can be overridden by subclass.
        control_keys = {"debug", "verbose", "timeout", "dry_run", "force"}

    # Normalize args into a mapping of key -> value
    try:
        if isinstance(args, dict):
            arg_map = args
        else:
            # Assume an iterable of (key, value) pairs
            arg_map = {k: v for k, v in args}
    except Exception as e:
        raise TypeError("args must be a mapping or an iterable of key/value pairs") from e

    for key, value in arg_map.items():
        if key in control_keys:
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args<|return|>

