        elif isinstance(item, (tuple, list)) and len(item) == 2:
            key, value = item
        else:
            raise ValueError(f"Argument {item!r} is not a valid key/value pair")

        key = key.strip()
        value = value.strip()

        # Determine which dict to place the argument in
        if (
            key.startswith(_CONTROL_KEY_PREFIXES[0])
            or key in _CONTROL_KEYS
            or key in _CUSTOM_KEYS
        ):
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args<|return|>

