        # Determine if key is a control argument
        is_control = False

        # Explicit list of control keys
        if control_keys and key in control_keys:
            is_control = True
        # Prefixes for control
        if control_prefixes and any(key.startswith(p) for p in control_prefixes):
            is_control = True
        # Default convention: keys starting with underscore are control
        if key.startswith("_"):
            is_control = True

        if is_control:
            control_args[key] = val
        else:
            nested_args[key] = val

    return control_args, nested_args<|return|>

