def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import json
    import os
    import sys

    # Build base command
    cmd = ['ansible-playbook']

    # Handle verbosity flags
    try:
        v_level = int(verbose) if verbose is not None else 0
    except Exception:
        v_level = 0
    if v_level > 0:
        cmd.extend(['-v'] * v_level)

    # Resolve playbook path relative to workspace if needed
    if ir_workspace and not os.path.isabs(playbook_path):
        workspace_path = getattr(ir_workspace, 'path', None) or getattr(ir_workspace, 'workspace_path', None)
        if workspace_path:
            playbook_path = os.path.join(workspace_path, playbook_path)

    cmd.append(playbook_path)

    # Add additional ansible-playbook arguments
    if ansible_args:
        for key, value in ansible_args.items():
            # Support flags without value and flags with value
            if isinstance(value, bool):
                if value:
                    flag = key if key.startswith('-') else '--' + key
                    cmd.append(flag)
            elif isinstance(value, list):
                flag = key if key.startswith('-') else '--' + key
                for v in value:
                    cmd.append(flag)
                    cmd.append(str(v))
            else:
                flag = key if key.startswith('-') else '--' + key
                cmd.append(flag)
                cmd.append(str(value))

    # Handle extra_vars
    if extra_vars:
        try:
            ev = json.dumps(extra_vars, separators=(',', ':'))
        except Exception as exc:
            raise ValueError(f"Could not serialize extra_vars to JSON: {exc}") from exc
        cmd.extend(['--extra-vars', ev])

    # Environment: inherit and allow plugin to inject
    env = os.environ.copy()
    if hasattr(ir_plugin, 'env') and isinstance(ir_plugin.env, dict):
        env.update(ir_plugin.env)

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            env=env,
            check=False
        )
    except FileNotFoundError as exc:
        raise RuntimeError("ansible-playbook command not found in PATH") from exc
    except Exception as exc:
        raise RuntimeError(f"Error running ansible-playbook: {exc}") from exc

    # Log output if verbosity requested
    if verbose:
        if result.stdout:
            sys.stdout.write(result.stdout)
        if result.stderr:
            sys.stderr.write(result.stderr)

    # Raise if playbook failed
    if result.returncode != 0:
        raise RuntimeError(
            f"ansible-playbook exited with status {result.returncode}\n"
            f"Stdout:\n{result.stdout}\n"
            f"Stderr:\n{result.stderr}"
        )

    return result<|return|>

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import json, os, subprocess, shlex

    # Validate mandatory inputs
    if not isinstance(playbook_path, str) or not playbook_path:
        raise ValueError("playbook_path must be a non-empty string")
    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook not found: {playbook_path}")

    cmd = ["ansible-playbook", playbook_path]

    # Verbosity
    if verbose is not None:
        try:
            v = int(verbose)
        except Exception:
            raise ValueError("verbose must be an integer or None") from None
        if v > 0:
            # Add -v repeated v times
            cmd.extend(["-v"] * v)

    # Extra vars
    if extra_vars is not None:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dict")
        try:
            json_str = json.dumps(extra_vars)
        except Exception as e:
            raise ValueError("failed to serialize extra_vars to JSON") from e
        cmd.extend(["--extra-vars", json_str])

    # Additional ansible-playbook arguments
    if ansible_args is not None:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for key, value in ansible_args.items():
            if not isinstance(key, str) or not key:
                raise ValueError(f"arg key must be a non-empty string: {key!r}")
            # If value is a boolean flag
            if isinstance(value, bool):
                if value:
                    cmd.append(key)
                # if False we skip the flag
            elif value is None:
                # flag without value
                cmd.append(key)
            else:
                cmd.append(key)
                # Convert list/tuple to space-separated string
                if isinstance(value, (list, tuple)):
                    value_str = " ".join(map(str, value))
                else:
                    value_str = str(value)
                cmd.append(value_str)

    # Run the command, capture output
    try:
        result = subprocess.run(
            cmd,
            cwd=ir_workspace.path if hasattr(ir_workspace, "path") else None,
            check=True,
            capture_output=True,
            text=True,
        )
    except subprocess.CalledProcessError as e:
        # Return stdout and stderr for debugging
        err_msg = f"ansible-playbook failed (exit {e.returncode}):\nSTDOUT:\n{e.stdout}\nSTDERR:\n{e.stderr}"
        raise RuntimeError(err_msg) from e
    except FileNotFoundError as e:
        raise RuntimeError("ansible-playbook executable not found. Ensure Ansible is installed and available in PATH") from e
    except Exception as e:
        raise RuntimeError(f"unexpected error running ansible-playbook: {e}") from e

    # Return the captured stdout (and optionally stderr if needed)
    return result.stdout.strip()<|return|>

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    import json
    import subprocess

    # Basic type checks
    if not isinstance(cli_args, list):
        raise TypeError("cli_args must be a list of command line arguments")
    if not isinstance(vars_dict, dict) and vars_dict is not None:
        raise TypeError("vars_dict must be a dict")
    if vars_dict is None:
        vars_dict = {}
    if ir_workspace is None:
        raise ValueError("ir_workspace must not be None")
    if ir_plugin is None:
        raise ValueError("ir_plugin must not be None")

    # Build the ansible-playbook command
    cmd = ["ansible-playbook"]
    cmd.extend(cli_args)
    # Pass the vars_dict as JSON via --extra-vars
    try:
        extra_vars_json = json.dumps(vars_dict)
    except (TypeError, OverflowError) as exc:
        raise ValueError(f"vars_dict contains non-serializable objects: {exc}") from exc
    cmd.extend(["--extra-vars", extra_vars_json])

    # Execute the command and capture output
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=True,
        )
    except subprocess.CalledProcessError as exc:
        # Return the command's output even if it failed
        return {
            "returncode": exc.returncode,
            "stdout": exc.stdout,
            "stderr": exc.stderr,
        }

    # Return the successful results
    return {
        "returncode": result.returncode,
        "stdout": result.stdout,
        "stderr": result.stderr,
    }<|return|>

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if not isinstance(values_dict, dict):
        raise TypeError(f"values_dict must be a dict, got {type(values_dict).__name__}")
    if not isinstance(parser_name, str):
        raise TypeError(f"parser_name must be a string, got {type(parser_name).__name__}")

    # Attempt to fetch argument spec mapping for the given parser.
    # It is expected that subclasses or external code provide a
    # `self._parser_specs` dictionary mapping parser names to a mapping of
    # argument names to desired types.
    try:
        arg_spec = self._parser_specs[parser_name]
    except (AttributeError, KeyError, TypeError):
        # No specs available or parser_name key missing – nothing to convert.
        return

    # Walk through all key/value pairs in the dictionary,
    # converting those for which a target type is known.
    for key, value in list(values_dict.items()):
        # Skip keys that aren't specified in the spec.
        if key not in arg_spec:
            continue

        target_type = arg_spec[key]
        try:
            if target_type is bool:
                if isinstance(value, str):
                    lowered = value.lower()
                    if lowered in ("true", "1", "yes"):
                        values_dict[key] = True
                    elif lowered in ("false", "0", "no"):
                        values_dict[key] = False
                    else:
                        raise ValueError()
                else:
                    values_dict[key] = bool(value)

            elif target_type is list:
                if isinstance(value, str):
                    # Split comma-separated strings into a list.
                    values_dict[key] = [item.strip() for item in value.split(",") if item.strip()]
                else:
                    values_dict[key] = list(value)

            else:
                # Skip conversion for None values.
                if value is not None:
                    values_dict[key] = target_type(value)

        except Exception as exc:
            raise ValueError(
                f"Cannot convert argument '{key}' from {value!r} to {target_type.__name__}"
            ) from exc<|return|>

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Retrieve any explicit type mapping that might be defined for this parser
    type_map = getattr(self, "_arg_types", {}).get(parser_name, {})

    for key, raw_value in list(values_dict.items()):
        # Skip non-string values early
        if not isinstance(raw_value, str):
            continue

        # Prefer explicit type mapping if available
        cast_func = type_map.get(key)
        if cast_func:
            try:
                values_dict[key] = cast_func(raw_value)
                continue
            except Exception as exc:
                # Log the exception or silently fallback to other heuristics
                # For now, simply keep original value and continue
                pass

        # Heuristic type conversion
        val_lower = raw_value.lower()

        # Boolean conversion
        if val_lower in ("true", "false"):
            values_dict[key] = val_lower == "true"
            continue

        # Integer conversion
        try:
            if raw_value.strip().isdigit() or (
                raw_value.strip().startswith("-") and raw_value.strip()[1:].isdigit()
            ):
                values_dict[key] = int(raw_value)
                continue
        except Exception:
            pass

        # Floating point conversion
        try:
            f_val = float(raw_value)
            values_dict[key] = f_val
            continue
        except Exception:
            pass

        # List conversion (comma separated)
        if "," in raw_value:
            items = [item.strip() for item in raw_value.split(",")]
            converted_items = []
            for itm in items:
                # Try int first
                if itm.isdigit() or (
                    itm.startswith("-") and itm[1:].isdigit()
                ):
                    try:
                        converted_items.append(int(itm))
                        continue
                    except Exception:
                        pass
                # Try float
                try:
                    converted_items.append(float(itm))
                except Exception:
                    converted_items.append(itm)
            values_dict[key] = converted_items

    # No return needed as values_dict is modified in place.<|return|>

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict with arguments
    """
    import json
    import logging

    log = logging.getLogger(__name__)

    # Helper to cast a single value according to an expected type
    def _cast_value(value, expected_type):
        if expected_type is None:
            return value  # leave as is
        try:
            if expected_type is bool:
                if isinstance(value, str):
                    return value.strip().lower() in ('1', 'true', 'yes', 'on')
                return bool(value)
            if expected_type is int:
                return int(value)
            if expected_type is float:
                return float(value)
            if expected_type is list:
                if isinstance(value, list):
                    return value
                if isinstance(value, str):
                    # split by comma
                    return [item.strip() for item in value.split(',') if item.strip()]
                return list(value)
            if expected_type is set:
                if isinstance(value, set):
                    return value
                if isinstance(value, (list, tuple, str)):
                    return set(_cast_value(value, list))
                return set(value)
            if expected_type is tuple:
                if isinstance(value, tuple):
                    return value
                if isinstance(value, (list, str)):
                    return tuple(_cast_value(value, list))
                return tuple(value)
            if expected_type is dict or expected_type is object or expected_type is type(json):
                # Treat as JSON
                if isinstance(value, str):
                    return json.loads(value)
                if isinstance(value, dict):
                    return value
                # fall back to string
                return value
            # For any other callable type, attempt to call it
            if callable(expected_type):
                return expected_type(value)
        except (ValueError, TypeError, json.JSONDecodeError) as exc:
            log.debug(f"Failed to cast value '{value}' to {expected_type}: {exc}")
        return value

    # Optional parser-specific type map; each entry should be a dict:
    # {arg_name: expected_type}
    # We look for an attribute called `_type_spec` or fallback to empty mapping.
    type_map = getattr(self, '_type_spec', {}).get(parser_name, {})

    # If the type map references a special global map (e.g. self._global_type_map),
    # evaluate it lazily.  This allows subclasses to override the mapping for specific
    # parsers without modifying the base class.
    if isinstance(type_map, str):
        type_map = getattr(self, type_map, {})

    for key, raw_val in values_dict.items():
        expected = type_map.get(key)
        values_dict[key] = _cast_value(raw_val, expected)

    # The method mutates values_dict in place; return None for clarity.
    return None<|return|>

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if not isinstance(parser_name, str):
