    # Grab the type mapping for this parser. Sub‑classes can supply a
    # mapping as ``_<parser>_arg_types`` or rely on a generic ``_arg_types``
    # dictionary that maps parser names to type dictionaries.
    type_map_attr = f'_{parser_name}_arg_types'
    type_map = getattr(self, type_map_attr, None)

    if type_map is None:
        fallback = getattr(self, '_arg_types', {})
        type_map = fallback.get(parser_name, {})

    if not isinstance(type_map, dict):
        type_map = {}

    # Iterate over the provided arguments and cast where a target type
    # is defined.
    for key, value in list(values_dict.items()):
        if key not in type_map:
            continue

        target_type = type_map[key]

        try:
            if target_type is bool:
                # Normalize common string representations of booleans.
                if isinstance(value, str):
                    values_dict[key] = value.strip().lower() in ('true', '1', 'yes', 'y')
                else:
                    values_dict[key] = bool(value)
            elif target_type in {list, tuple}:
                # Assume comma‑separated string when the source is a string.
                if isinstance(value, str):
                    values_dict[key] = [x.strip() for x in value.split(',') if x.strip()]
                else:
                    values_dict[key] = list(value)
            else:
                # Generic conversion: int, float, complex, etc.
                values_dict[key] = target_type(value)
        except Exception as exc:
            msg = f"Error converting argument '{key}' to {target_type.__name__}: {exc}"
            raise ValueError(msg) from exc

