def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    # Basic validation
    if not isinstance(plugin_dir, str):
        raise TypeError('plugin_dir must be a string path')
    if not os.path.isdir(plugin_dir):
        raise ValueError(f'The directory {plugin_dir!r} does not exist or is not a directory')

    # Locate a spec file – we look for plugin.json by default
    spec_path = None
    for candidate in ('plugin.json', 'spec.json'):
        path = os.path.join(plugin_dir, candidate)
        if os.path.isfile(path):
            spec_path = path
            break
    if spec_path is None:
        raise FileNotFoundError(f'No plugin.json or spec.json found in {plugin_dir!r}')

    # Load the spec
    try:
        with open(spec_path, 'r', encoding='utf-8') as fp:
            data = json.load(fp)
    except Exception as exc:
        raise ValueError(f'Failed to load plugin spec from {spec_path!r}: {exc}')

    # Flatten nested dictionaries
    flat = {}
    def _flatten(prefix, value):
        if isinstance(value, dict):
            for k, v in value.items():
                _flatten(f'{prefix}.{k}' if prefix else k, v)
        else:
            flat[prefix] = value

    _flatten('', data)

    return flat<|return|>

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    # Basic input validation
    if not isinstance(plugin_dir, (str, Path)):
        raise TypeError(f"plugin_dir must be a string or pathlib.Path, got {type(plugin_dir).__name__}")

    path = Path(plugin_dir) if not isinstance(plugin_dir, Path) else plugin_dir

    if not path.exists():
        raise FileNotFoundError(f"Plugin directory '{plugin_dir}' does not exist")
    if not path.is_dir():
        raise NotADirectoryError(f"'{plugin_dir}' is not a directory")

    # Determine which spec file exists
    spec_file = None
    for ext in ("plugin.json", "plugin.yaml", "plugin.yml", "plugin.json"):
        possible = path / ext
        if possible.exists() and possible.is_file():
            spec_file = possible
            break
    if spec_file is None:
