                spec_data = json.load(f)
            else:  # assume yaml
                import yaml
                spec_data = yaml.safe_load(f)
        if not isinstance(spec_data, dict):
            raise ValueError(f"Specification file '{spec_file}' does not contain a dictionary")
    except Exception as exc:
        raise ValueError(f"Failed to load plugin specification from '{spec_file}': {exc}") from exc

    # Recursively flatten the dictionary
    def _flatten(current, prefix=""):
        items = {}
        if isinstance(current, dict):
            for k, v in current.items():
                new_key = f"{prefix}.{k}" if prefix else k
                items.update(_flatten(v, new_key))
        elif isinstance(current, list):
            for idx, val in enumerate(current):
                new_key = f"{prefix}[{idx}]"
                items.update(_flatten(val, new_key))
        else:
            items[prefix] = current
        return items

    flat_dict = _flatten(spec_data)
