    """
    import json
    import os

    if not isinstance(plugin_dir, (str, bytes)):
        raise TypeError("plugin_dir must be a string path")

    # Determine the plugin spec file (try .json or .yaml/.yml)
    spec_path = None
    for ext in ('.json', '.yaml', '.yml'):
        candidate = os.path.join(plugin_dir, 'plugin' + ext)
        if os.path.isfile(candidate):
            spec_path = candidate
            break
    if not spec_path:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    # Load the spec content
    try:
        with open(spec_path, 'r', encoding='utf-8') as f:
            content = f.read()
        if spec_path.endswith('.json'):
            spec_dict = json.loads(content)
        else:  # simple YAML parsing
            # Use json for parsing YAML-like content if possible
            try:
                import yaml
                spec_dict = yaml.safe_load(content)
            except Exception:
                # Fallback: basic parsing for simple key: value pairs
                spec_dict = {}
                for line in content.splitlines():
                    if ':' in line:
                        key, val = line.split(':', 1)
                        spec_dict[key.strip()] = val.strip()
    except Exception as exc:
        raise ValueError(f"Failed to parse plugin spec: {exc}") from exc

    if not isinstance(spec_dict, dict):
        raise ValueError("Plugin spec does not contain a dictionary")

    # Flatten the dictionary
    flat = {}

    def _flatten(d, parent_key=''):
        if isinstance(d, dict):
            for k, v in d.items():
                new_key = f"{parent_key}.{k}" if parent_key else k
                _flatten(v, new_key)
        elif isinstance(d, (list, tuple)):
            for idx, item in enumerate(d):
                new_key = f"{parent_key}[{idx}]"
                _flatten(item, new_key)
        else:
            flat[parent_key] = d

    _flatten(spec_dict)
    return flat<|return|>

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    from pathlib import Path

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            if v is None:
                continue
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            elif isinstance(v, list):
                for i, item in enumerate(v):
                    list_key = f"{new_key}[{i}]"
                    if isinstance(item, dict):
                        items.update(_flatten(item, list_key, sep=sep))
                    else:
                        items[list_key] = item
            else:
                items[new_key] = v
        return items

    # Resolve the plugin directory
    plugin_path = Path(plugin_dir)
    if not plugin_path.is_dir():
        raise FileNotFoundError(f"Plugin directory '{plugin_dir}' does not exist or is not a directory.")

    # Look for standard plugin spec files
    spec_file = None
    for candidate in ('plugin.json', 'plugin.yaml', 'plugin.yml'):
        potential = plugin_path / candidate
        if potential.is_file():
            spec_file = potential
            break

    if spec_file is None:
        raise FileNotFoundError(f"No plugin spec file found in '{plugin_dir}'. Expected one of 'plugin.json', 'plugin.yaml', 'plugin.yml'.")

    # Load the spec content
    try:
        with spec_file.open('r', encoding='utf-8') as f:
            if spec_file.suffix in {'.json'}:
                raw_spec = json.load(f)
            else:
                try:
                    import yaml
                except ImportError as exc:
                    raise ImportError("PyYAML is required to load YAML plugin specs.") from exc
                raw_spec = yaml.safe_load(f)
    except Exception as exc:
        raise ValueError(f"Failed to parse the plugin spec file '{spec_file}': {exc}") from exc

    if not isinstance(raw_spec, dict):
        raise ValueError(f"The plugin spec file '{spec_file}' does not contain a top-level dictionary.")

    # Flatten and return
    return _flatten(raw_spec)<|return|>

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import json
    import os
    from pathlib import Path

    # Resolve path
    try:
        path = Path(plugin_dir).expanduser().resolve(strict=True)
    except Exception as e:
        raise ValueError(f"Invalid plugin directory '{plugin_dir}': {e}")

    if not path.is_dir():
        raise ValueError(f"Provided path '{plugin_dir}' is not a directory")

    # Determine spec file (JSON or YAML)
    spec_file = None
    for candidate in ("plugin.json", "plugin.yaml", "plugin.yml"):
        candidate_path = path / candidate
        if candidate_path.is_file():
            spec_file = candidate_path
            break

    if spec_file is None:
        raise ValueError(f"No plugin spec file found in '{plugin_dir}'. Expected one of: plugin.json, plugin.yaml, plugin.yml")

    # Load spec
    try:
        if spec_file.suffix.lower() == ".json":
            with spec_file.open('r', encoding='utf-8') as f:
                spec = json.load(f)
        else:
            # Try YAML
            try:
                import yaml
            except ImportError as exc:
                raise ValueError(f"YAML spec found but PyYAML is not installed: {exc}")

            with spec_file.open('r', encoding='utf-8') as f:
                spec = yaml.safe_load(f)
    except Exception as e:
        raise ValueError(f"Failed to load plugin spec from '{spec_file}': {e}")

    if not isinstance(spec, dict):
        raise ValueError(f"Plugin spec must be a mapping; got {type(spec)!r}")

    # Helper to flatten nested dicts
    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep))
            else:
                items[new_key] = v
        return items

    flat_spec = _flatten(spec)
    return flat_spec
