    import os
    import logging

    env_var = "CONFIG_PATH"

    try:
        # Do nothing if the variable is already defined
        if os.getenv(env_var) is not None:
            return

        # Attempt to get the config path from a common attribute
        path = getattr(self, "config_path", None)
        if path is None:
            # Try alternative attribute names
            path = getattr(self, "path", None)

        if not path:
            raise AttributeError(f"Unable to determine config path to set for environment variable '{env_var}'")

        os.environ[env_var] = path

    except Exception as exc:
        logging.exception(
            "Failed to inject config path into environment variable '%s': %s", env_var, exc
