def extend_cli(self, root_subparsers):
    """Adds the spec cli options to to the main entry point.

    :param subparser: the subparser object to extend.
    """
    # Attempt to add a subparser for the spec command and populate it with
    # any provided CLI arguments that the current instance is aware of.
    try:
        if not hasattr(root_subparsers, "add_parser"):
            raise TypeError(
                "root_subparsers must be an argparse SubParsers object (must provide add_parser method)"
            )
        # Create a new parser for the "spec" subcommand.
        parser = root_subparsers.add_parser(
            "spec",
            help="Spec-related command line options",
        )
        # If this instance defines a dictionary of additional arguments
        # (e.g., self.spec_cli_args = {"--flag": {"help": "...", "action": "store_true"}, ...}),
        # add them to the newly created parser.
        if hasattr(self, "spec_cli_args"):
            if isinstance(self.spec_cli_args, dict):
                for arg, kwargs in self.spec_cli_args.items():
                    if not isinstance(kwargs, dict):
                        raise ValueError(
                            f"Expected a dict of keyword arguments for argument '{arg}', got {type(kwargs)!r}"
                        )
                    parser.add_argument(arg, **kwargs)
            else:
                raise TypeError(
                    f"spec_cli_args attribute must be a dict, got {type(self.spec_cli_args)!r}"
                )
        # Store the parser on the instance so other parts of the system can
        # manipulate it if necessary.  This is optional and depends on the
        # surrounding framework but is often useful.
        self._spec_cli_parser = parser
        return parser
    except Exception as exc:
        # Provide a clear error message that preserves the original stack trace.
        raise RuntimeError(f"Failed to extend CLI: {exc}") from exc<|return|>

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    try:
        import os
    except ImportError as exc:
        raise RuntimeError("os module is required") from exc

    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("both 'path' and 'root' must be strings")

    # Normalize paths to use the OS specific separator
    norm_root = os.path.normpath(root)
    norm_path = os.path.normpath(path)

    # Ensure that the path actually starts with the root
    if not norm_path.startswith(norm_root):
        raise ValueError(f'Root "{root}" not found at the beginning of path "{path}"')

    # Remove the root part
    stripped = norm_path[len(norm_root):]

    # Remove a leading separator if present
    if stripped.startswith(os.sep):
        stripped = stripped[len(os.sep):]

    return stripped<|return|>

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("`path` and `root` must be strings")
    if root == "":
        return path  # nothing to strip
    if not path.startswith(root):
        raise ValueError(f"Root '{root}' not found in path '{path}'")
    stripped = path[len(root):]
    # Remove a leading separator if present
    if stripped.startswith('/') or stripped.startswith('\\'):
        stripped = stripped[1:]
    return stripped<|return|>
